      [56] = {n="Borghertz's Lurking Hands",d="Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana'diel."},
      [57] = {n="Borghertz's Dragon Hands",d="Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana'diel."},
      [58] = {n="Borghertz's Calling Hands",d="Client: Guslam (Durable Shields,\n Upper Jeuno)\nSummary:\n Gauntlets wrought by Borghertz,\n the legendary craftsman, lie hidden\n somewhere in Vana'diel."},
      [59] = {n="Axe the Competition",d="Client: Brutus (Chocobo Stables,\n Upper Jeuno)\nSummary:\n The Tenshodo wants Brutus's opinion\n on which axe they should carry in\n their stores. Brutus has asked you to\n test one of the axes until its blade\n has gone dull."},
      [60] = {n="Wings of Gold",d="Client: Brutus (Chocobo Stables,\n Upper Jeuno)\nSummary:\n The guiding bell is hidden somewhere\n inside Delkfutt's Tower. Brutus\n wants you to bring it back for his\n deceased chocobo."},
      [61] = {n="Scattered Into Shadow",d="Client: Brutus (Chocobo Stables,\n Upper Jeuno)\nSummary:\n Many animals conscripted during the\n war did not return. Brutus wants\n you to put their souls to rest."},
      [62] = {n="A New Dawn",d="Client: Dietmund (Merchant's House,\n Lower Jeuno)\nSummary:\n Something is amiss in the Eldieme\n Necropolis. Observe the fiends and\n find a solution."},
      [63] = {n="Painful Memory",d="Client: Mertaire (Merry Minstrel\n Meadhouse, Lower Jeuno)\nSummary:\n Take Mertaire's bracelet to\n Ranguemont Pass and immerse it in\n the Waters of Oblivion."},
      [64] = {n="The Requiem",d="Client: Bki Tbujhja (Merry Minstrel\n Meadhouse, Lower Jeuno)\nSummary:\n A certain post is rotated at the\n meadhouse. Now, it's your turn."},
      [65] = {n="The Circle of Time",d="Client: Imasuke (Qufim Tunnel,\n Port Jeuno)\nSummary:\n Solve the riddle of the ring, and\n find the truth behind it."},
      [66] = {n="Searching for the Right Words",d="Client: Ilumida (House, Upper Jeuno)\nSummary:\n A \"moondrop\" from the Boyahda Tree\n is required to open the chest\n Ilumida's late husband left for her."},
      [67] = {n="Beat Around the Bushin",d="Client: Atori-Tutori\n (Tenshodo, Lower Jeuno)\nSummary:\n If you want information on the\n black belt, you need to first\n bring back what Atori-Tutori wants."},
      [68] = {n="Ducal Hospitality",r=1,d="Client: Taillegeas (Dining Hall,\n Ru'Lude Gardens)\nSummary:\n Taillegeas has asked you to collect\n several items desired by guests of\n the duchy."},
      [69] = {n="In the Mood for Love",d="Client: Odasel (Gems by Kshama,\n Lower Jeuno)\nSummary:\n Odasel wants to find out which of the\n three beauties in the gem store has\n feelings for him. According to a\n passing Elvaan girl, a jewel known as\n the \"Chameleon Diamond\" could help\n solve his dilemma..."},
      [70] = {n="Empty Memories",d="Client: Harith (Grand Duke Palace,\n Ru'Lude Gardens)\nSummary:\n The mysterious \"society\" that\n Harith works for is supposedly\n performing research on a strange\n life form known as the Empty."},
      [71] = {n="Hook, Line, and Sinker",d="Client: Omer (Market Bridge,\n Lower Jeuno)\nSummary:\n Help Omer retrieve his prized fishing\n rod that was stolen from him by an\n Elvaan girl.\n Apparently the rod was lost when she\n fished up a monster out on Qufim\n Island..."},
      [72] = {n="A Chocobo's Tale",d="Client: Nevela (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Nevela wants to hear the story\n surrounding the birth of a chocobo\n in the Upper Jeuno stables.\n The chocobo's mother is said to have\n been from the stables in Bastok..."},
      [73] = {n="A Reputation in Ruins",d="Client: Migliorozz (Temple of\n the Goddess, Upper Jeuno)\nSummary:\n The Tenshodo has opened the ruins\n of Pso'Xja to adventurers.\n Migliorozz has asked you to perform\n a task involving the gate that lies\n in the deepest part of the southwest\n tower of the ruins."},
      [74] = {n="The Gobbiebag Part V",d="Client: Bluffnix (Muckvix's\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack bigger\n than a gobbiebag if you bring him\n the following: a square of bugard\n leather, a paktong ingot, a square\n of Moblinweave, and a rhodonite."},
      [75] = {n="The Gobbiebag Part VI",d="Client: Bluffnix (Muckvix's\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack even\n bigger if you bring him the\n following: a square of balloon\n cloth, a shakudo ingot, a high\n quality eft skin, and an iolite."},
      [76] = {n="Beyond the Sun",d="Client: Maat (Grand Duke Palace,\n Ru'Lude Gardens)\nSummary:\n After clearing all of Maat's final\n challenges, you will finally learn\n his secret..."},
      [77] = {n="Unlisted Qualities",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Luto wants you to find out if the\n person you chose from her list is\n holding a certain mirror."},
      [78] = {n="Girl in the Looking Glass",d="Client: Laurana (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Laurana's daughter has gone\n missing. She is a young girl with\n blonde hair, and was wearing a\n brown dress and a brown cap."},
      [79] = {n="Mirror, Mirror",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Luto has recently discovered that\n another mirror bearing strange\n properties exists in the world.\n It is supposedly somewhere in\n San d'Oria and she wants you to\n go look for it."},
      [80] = {n="Past Reflections",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Luto wants you to search the\n Optistery library in Windurst for\n a book that can help her repair\n the broken mirror."},
      [81] = {n="Blighted Gloom",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Luto has asked you to locate a\n special metal that can be used to\n repair the broken mirror.\n According to her research, this\n substance can only be found inside\n an extremely rare species of slime."},
      [82] = {n="Blessed Radiance",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Palometa still lies in cursed\n slumber. You must find a way\n to save her!"},
      [83] = {n="Mirror Images",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Save Palometa from her mysterious\n captor."},
      [84] = {n="Chameleon Capers",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n A friend of Luto has used a magical\n costume kit to change into a child,\n but now he can't return to his original\n form.\n Luto wants you to help find a way\n to change him back."},
      [85] = {n="Regaining Trust",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Your adventuring fellow is\n in the hospital after being\n attacked by a monster in Qufim.\n You should go make sure\n your friend is not too badly hurt."},
      [86] = {n="Storms of Fate",d="Client: Esha'ntarl\n (Audience Chamber, Ru'Lude Gardens)\nSummary:\n Bahamut returned to the heavens\n following the defeat of the Keeper\n of the Apocalypse, but recently\n he was witnessed descending upon\n Cape Riverne with an army of\n wyrms. Go to Bahamut and find out\n his intentions."},
      [87] = {n="Mixed Signals",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Your adventuring fellow is acting\n strangely. Talk to Luto to see what\n you can find out."},
      [88] = {n="Shadows of the Departed",d="Client: Esha'ntarl\n (Audience Chamber, Ru'Lude Gardens)\nSummary:\n Strange readings have been recorded\n from the Emptiness surrounding the\n mothercrystals.\n Travel to the crags of Holla, Dem,\n and Mea and investigate the\n coordinates where this phenomenon\n is occurring."},
      [89] = {n="Apocalypse Nigh",d="Client: Esha'ntarl\n (Audience Chamber, Ru'Lude Gardens)\nSummary:\n The next incarnation of the Keeper\n of the Apocalypse is attempting to\n cross over into Vana'diel. Sing the \n Lay of the Immortals before the fifth\n mothercrystal and put an end to this\n threat once and for all!"},
      [90] = {n="Lure of the Wildcat (Jeuno)",d="Client: Ajithaam (Artisan Bridge,\n Upper Jeuno)\nSummary:\n The mercenary company\n \"Salaheem's Sentinels\" has asked\n you to help recruit new members."},
      [91] = {n="The Road to Aht Urhgan",d="Client: Faursel (Tenshodo,\n Lower Jeuno)\nSummary:\n If you want to ride the mercenary\n transport ship from Mhaura, you\n must bring the required items to\n the Tenshodo."},
      [92] = {n="Chocobo on the Loose!",d="Client: Brutus (Chocobo Stables,\n Upper Jeuno)\nSummary:\n A chocobo has run away from the\n stables in Upper Jeuno, and Brutus\n wants you to help bring it back."},
      [93] = {n="The Gobbiebag Part VII",d="Client: Bluffnix (Muckvix's\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack even\n bigger if you bring him the\n following: a square of lynx\n leather, an adaman ingot, a\n square of rainbow cloth, and\n a deathstone."},
      [94] = {n="The Gobbiebag Part VIII",d="Client: Bluffnix (Muckvix's\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack even\n bigger if you bring him the\n following: a square of smilodon\n leather, an electrum ingot, a \n square of cilice, and an angelstone."},
      [95] = {n="Lakeside Minuet",d="Client: Laila (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Laila has asked that you bring her\n a stardust pebble before she'll\n consider allowing you to join\n Troupe Brilioth."},
      [96] = {n="The Unfinished Waltz",d="Client: Laila (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Troupe Brilioth is aiming for a\n dance style that will captivate\n and enchant. Work out how to take\n your dancing to the next level,\n then come back and show Laila."},
      [97] = {n="The Road to Divadom",d="Client: Laila (Artisan Bridge,\n Upper Jeuno)\nSummary:\n As a child, Laila had an\n inspirational encounter with a\n piper at Lake Mechieume in Jugner\n Forest. In order to become a\n great dancer like Laila, you\n should seek a skilled musician\n to play a tune for you."},
      [98] = {n="Comeback Queen",d="Client: Laila (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Deliver Wyatt's proposal to the\n owner of the music shop in Bastok\n Markets so he can pass it on to\n Valeriano."},
      [99] = {n="A Furious Finale",d="Client: Laila (Artisan Bridge,\n Upper Jeuno)\nSummary:\n Obtain a \"dancer's testimony\" and\n bring it to Laila."},
      [100] = {n="The Miraculous Dale",d="Client: Rakuru-Rakoru\n (Holy Owen's Square, Lower Jeuno)\nSummary:\n Rakuru-Rakoru from the Orastery\n wants you to collect research\n data by defeating all the monsters\n recorded in the Data Analyzer\n and Logger EX (Dale)."},
      [101] = {n="Clash of the Comrades",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n As a test of strength, you have\n agreed to meet your fellow in single\n combat at the Qu'Bia Arena.\n Who will emerge victorious in\n this face-off between friends?"},
      [102] = {n="Unlocking a Myth (Warrior)",d="Client: Zalsuhm (Muckvix's\n Junk Shop, Lower Jeuno)\nSummary:\n Self-styled leading researcher of\n mystical artifacts, Zalsuhm, claims\n that the weapon you acquired deep\n within Nyzul Isle conceals immense\n power. Wielding the now unlocked\n weapon will cause a magical evolution\n to take place...eventually."},
