      [122] = {n="JNQuest",d="Client:"},
      [123] = {n="The Gobbiebag Part IX",d="Client: Bluffnix (Muckvix's\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack even\n bigger if you bring him the\n following: an orichalcum ingot, a\n square of peiste leather, a square\n of oil-soaked cloth, and an\n oxblood orb."},
      [124] = {n="The Gobbiebag Part X",d="Client: Bluffnix (Muckvix's\n Junk Shop, Lower Jeuno)\nSummary:\n Bluffnix will make your pack even\n bigger if you bring him the\n following: a molybdenum ingot, a\n square of griffon leather, a square of\n foulard, and an angel skin orb."},
      [125] = {n="JNQuest",d="Client:"},
      [126] = {n="JNQuest",d="Client:"},
      [127] = {n="JNQuest",d="Client:"},
      [128] = {n="In Defiant Challenge",d="Client: Maat (Grand Duke Palace,\n Ru'Lude Gardens)\nSummary:\n Apparently, your innate limits can\n be breached by acquiring the\n necessary items."},
      [129] = {n="Atop the Highest Mountains",d="Client: Maat (Grand Duke Palace,\n Ru'Lude Gardens)\nSummary:\n Collect three stones of frigicite\n from fiend-infested caverns in the\n north. Bring them to Maat to further\n expand your innate limits."},
      [130] = {n="Whence Blows the Wind",d="Client: Maat (Grand Duke Palace,\n Ru'Lude Gardens)\nSummary:\n Your innate limits can be pushed\n further by collecting the crests of\n the Orcs, the Quadav, and the\n Yagudo."},
      [131] = {n="Riding on the Clouds",d="Client: Maat (Grand Duke Palace,\n Ru'Lude Gardens)\nSummary:\n Use Maat's hints to search out four\n people who will trade you a strange\n stone for a Kindred's seal. Only then\n will you know your true limits."},
      [132] = {n="Shattering Stars",d="Client: Maat (Grand Duke Palace,\n Ru'Lude Gardens)\nSummary:\n Maat has issued a final challenge\n to test your limits. Return with the\n item he has requested and the trial\n will begin."},
      [133] = {n="New Worlds Await",d="Client: Nomad Moogle (Grand Duke\n Palace, Ru'Lude Gardens)\nSummary:\n Has the enigmatic nomad moogle truly\n ascertained ancient secrets that will\n allow you to exceed long-standing\n limits?\n Acquire five Kindred's seals and\n three merit points and see for\n yourself!"},
      [134] = {n="Expanding Horizons",d="Client: Nomad Moogle (Grand Duke\n Palace, Ru'Lude Gardens)\nSummary:\n The nomad moogle claims to have\n perfected another procedure that will\n send your powers burgeoning to even\n greater heights. Acquire five Kindred's\n crests and four merit points if you\n fancy yourself ready for the\n undertaking."},
      [135] = {n="Beyond the Stars",d="Client: Nomad Moogle (Grand Duke\n Palace, Ru'Lude Gardens)\nSummary:\n The nomad moogle claims to have\n perfected another procedure that will\n send your powers burgeoning to even\n greater heights. Acquire ten Kindred's\n crests and five merit points if you\n fancy yourself ready for the\n undertaking."},
      [136] = {n="Dormant Powers Dislodged",d="Client: Nomad Moogle (Grand Duke\n Palace, Ru'Lude Gardens)\nSummary:\n The nomad moogle has invited a\n Tarutaru of questionable affiliation\n to supervise his latest physical\n enhancement project.\n Acquire the items requested as well\n as ten merit points if you have the\n stomach to proceed."},
      [137] = {n="Beyond Infinity",d="Client: Nomad Moogle (Grand Duke\n Palace, Ru'Lude Gardens)\nSummary:\n Atori-Tutori has deigned to present\n you with your final challenge--a\n sparring match with the smug Taru\n himself. Acquire a soul gem and\n soul gem clasp and meet your\n opponent for the ultimate showdown."},
      [160] = {n="A Trial in Tandem",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n You have been entrusted with lifting\n the spirits of your comrade, who has\n been mired in a crisis of confidence\n since suffering defeat at the Qu'Bia\n Arena. Head to the Ru'Lude Gardens,\n where the Magian Mooglehood will\n offer their assistance."},
      [161] = {n="A Trial in Tandem, Redux",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Another invitation has arrived from\n the Magian Mooglehood. Strike forth\n with your comrade in pursuit of yet\n loftier heights of power!"},
      [162] = {n="Yet Another Trial in Tandem",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Your comrade's zeal for self-\n improvement knows no limits, and the\n Magian Mooglehood stands ever ready\n to assist in this endeavor. Make your\n way to Ru'Lude Gardens, where a new\n challenge awaits!"},
      [163] = {n="A Quaternary Trial in Tandem",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n The Magian Mooglehood has requested\n the help of you and your companion\n once again, just in time to quench\n that thirst for knowledge and power!\n Venture to the Ru'Lude Gardens to\n receive a taste of what's to come!"},
      [164] = {n="A Trial in Tandem Revisited",d="Client: Luto Mewrilah\n (Artisan Bridge, Upper Jeuno)\nSummary:\n Appease the Magian Mooglehood by\n slaying some brutes and appease your\n new client by collecting twenty\n Kindred's crests on the way to\n bettering yourself and your partner!"},
      [166] = {n="All in the Cards",r=1,d="Client: Chululu (Fortunetellers,\n Lower Jeuno)\nSummary:\n Collect the complete set of Tarut\n cards by trading with your fellow\n adventurers, that you might help\n spread the joy and wisdom of\n fortune-telling across the realm."},
      [167] = {n="Martial Mastery",d="Client: Atori-Tutori (Grand Duke\n Palace, Ru'Lude Gardens)\nSummary:\n Amass fifteen merit points to fulfill\n your contract with Atori-Tutori and\n open the path to heretofore unseen\n powers..."},
      [168] = {n="VW Op. #115: Valkurm Duster",d="Client: Mawl'gofaur\n (Audience Chamber, Ru'Lude Gardens)\nSummary:\n A yet-unstable planar rift has been\n sighted in the Valkurm Dunes.\n Engage and eliminate any Voidwalkers\n that may emerge from this\n dimensional disturbance."},
      [169] = {n="VW Op. #118: Buburimu Squall",d="Client: Mawl'gofaur\n (Audience Chamber, Ru'Lude Gardens)\nSummary:\n A yet-unstable planar rift has been\n sighted on Buburimu Peninsula.\n Engage and eliminate any Voidwalkers\n that may emerge from this\n dimensional disturbance."},
      [170] = {n="Prelude to Puissance",d="Client: Nomad Moogle (Grand Duke\n Palace, Ru'Lude Gardens)\nSummary:\n Atori-Tutori has a present for you,\n but first you must procure the\n seasoning stone he seeks..."},
      [171] = {n="Researchers from the West",d="Client: Anastase\n (Main Promenade, Ru'Lude Gardens)\nSummary:\n A research expedition from the Sacred\n City of Adoulin is seeking\n collaborators. They require information\n about geomagnetic founts in various\n areas to assist in the testing of\n their mystical devices."},
      [172] = {n="Middle Lands Investigation",d="Client: Anastase\n (Main Promenade, Ru'Lude Gardens)\nSummary:\n Help find geomagnetic founts in the\n areas divined by eccentric\n clairvoyant, Quwi Orihbhe."},
      [173] = {n="Further Founts",d="Client: Anastase\n (Main Promenade, Ru'Lude Gardens)\nSummary:\n More geomagnetic founts have been\n discovered throughout the Middle\n Lands. Record any relevant data\n and report back to Anastase."},
      [174] = {n="Beam Me Up...No, Not There!",r=1,d="Client: Anastase\n (Main Promenade, Ru'Lude Gardens)\nSummary:\n Some fount data has destabilized,\n causing travelers to be warped to\n unexpected locations. Use the\n waypoint to travel to these locations\n and re-record the data. Beware--you\n may not end up where you wanted to\n be."},
      [175] = {n="Now Recording...",r=1,d="Client: Darcia (Chamber of Commerce\n and Industry, Lower Jeuno)\nSummary:\n Not all tests are tests of steel. In\n order to get permission to visit\n Adoulin, you must record data located\n in a certain part of the Middle\n Lands. The Adventurers' Mutual Aid\n Network will provide your reward."},
      [176] = {n="Teleports by Twilight",d="Client: Nantoto (Merry Minstrel\n Meadhouse, Lower Jeuno)\nSummary:\n For adventurers of appropriate\n aptitude who have made a name for\n themselves through Records of\n Eminence: make a pilgrimage to six\n telepoints throughout Vana'diel."},
      [177] = {n="Shifty Shades of Prey",d="Client: Nantoto (Merry Minstrel\n Meadhouse, Lower Jeuno)\nSummary:\n For adventurers of even more\n appropriate aptitude whose feats in\n Records of Eminence are\n widely renowned: travel to the\n Eldieme Necropolis and shine some\n light on a few shadows."},
      [178] = {n="To Kill Mocking Birds",d="Client: Nantoto (Merry Minstrel\n Meadhouse, Lower Jeuno)\nSummary:\n For adventurers of incredible aptitude\n whose feats in Records of Eminence\n are household topics of discussion:\n make some Yagudo High Priests in\n Castle Oztroja pray to their maker!"},
      [179] = {n="Full Speed Ahead!",d="Client: Mapitoto (Chocobo\n Stables, Upper Jeuno)\nSummary:\n Hop on board Mapitoto's slightly\n ornery raptor and head to Batallia\n Downs. Seek out Syrillia once you\n have arrived."},
      [186] = {n="The Flying Machine of Eld",d="Client: Jeridade (Chocobo\n Stables, Upper Jeuno)\nSummary:\n Jeridade has a dream: to\n create a flying machine for the\n ages. If you have any leads,\n be sure to bring them to\n Mapitoto."},
    }},
    other = { name = "Other Areas", ids = {
      [0] = {n="Rycharde the Chef",d="Client: Rycharde\n (Sailors' Stay, Mhaura)\nSummary:\n Rycharde needs your help\n to find some dhalmel meat."},
      [1] = {n="Way of the Cook",d="Client: Rycharde\n (Sailors' Stay, Mhaura)\nSummary:\n Rycharde needs your help\n finding some ingredients.\n He needs a beehive chip\n and some dhalmel meat."},
      [2] = {n="Unending Chase",d="Client: Rycharde\n (Sailors' Stay, Mhaura)\nSummary:\n Rycharde wants you to get him\n an ingredient called a puffball."},
      [3] = {n="His Name Is Valgeir",d="Client: Rycharde\n (Sailors' Stay, Mhaura)\nSummary:\n Rycharde wants you to\n deliver a dish to Valgeir\n in Selbina, and report on\n how he liked it."},
      [4] = {n="Expertise",d="Client: Take\n (Sailors' Stay, Mhaura)\nSummary:\n Take wants you to bring\n back one of Valgeir's\n dishes from Selbina."},
      [5] = {n="The Clue",d="Client: Rycharde\n (Sailors' Stay, Mhaura)\nSummary:\n Rycharde seeks an ingredient\n known as crawler's eggs."},
      [6] = {n="The Basics",d="Client: Rycharde\n (Sailors' Stay, Mhaura)\nSummary:\n Rycharde wants you to\n deliver a dish to Valgeir\n in Selbina, and report on\n how he liked it."},
      [7] = {n="Orlando's Antiques",d="Client: Orlando\n (Orlando's Antiques, Mhaura)\nSummary:\n Find where the Goblins bury\n their junk.\n Bring back eight of the same\n type of junk and Orlando will\n reward you well."},
      [8] = {n="The Sand Charm",d="Client: Celestina (Goldsmiths' \n Guild Salesroom, Mhaura)\nSummary:\n Retrieve the sand charm\n Celestina's father carried.\n Your one clue: a sailor\n saw a pirate wearing it."},
      [9] = {n="A Potter's Preference",d="Client: Nereus\n (Sailors' Stay, Mhaura)\nSummary:\n Nereus seeks a dish of\n Gusgen clay from the\n depths of the Gusgen Mines."},
      [10] = {n="The Old Lady",d="Client: Vera\n (Outside Warehouse, Mhaura)\nSummary:\n Fulfill her request if you want\n the promised rewards."},
      [11] = {n="Fisherman's Heart",d="Client: Katsunaga\n (Port Area, Mhaura)\nSummary:\n Bring Katsunaga a gugru\n tuna and he'll tell you\n all he knows about your\n fishing history."},
      [16] = {n="Donate to Recycling",d="Client: Romeo (Atop Fishermen's\n Guild Salesroom, Selbina)\nSummary:\n Donate five pieces of\n onion equipment to help\n new recruits everywhere.\n Donors may receive an award."},
      [17] = {n="Under the Sea",d="Client: Oswald\n (Shepherd's Muster, Selbina)\nSummary:\n Oswald needs help retrieving\n his ring from the\n jaws of the ocean."},
      [18] = {n="Only the Best",d="Client: Melyon\n (Weavers' Guild Salesroom, Selbina)\nSummary:\n Melyon will pay premium prices\n for any of the following:\n five heads of La Theine cabbage,\n three ears of millioncorn,\n one clump of Boyahda moss."},
      [19] = {n="An Explorer's Footsteps",d="Client: Abelard\n (Mayor's Residence, Selbina)\nSummary:\n The mayor wants you to find\n stone monuments left by a certain\n adventurer and copy their writings\n to clay."},
      [20] = {n="Cargo",d="Client: Vuntar\n (Foot of Central Stairs, Selbina)\nSummary:\n Vuntar will pay premium price\n for rolanberries, but for only\n those that are thoroughly aged \n and can serve as food for long\n voyages."},
      [21] = {n="The Gift",d="Client: Oswald\n (Shepherd's Muster, Selbina)\nSummary:\n Oswald wants to order something\n nutritious to cheer his girlfriend\n up a bit. Get him the special\n ingredient, a danceshroom."},
      [22] = {n="The Real Gift",d="Client: Oswald\n (Shepherd's Muster, Selbina)\nSummary:\n With his girlfriend still\n in the doldrums, Oswald\n wants to give her a pearl\n necklace. Find him a shall\n shell so he can make one."},
      [23] = {n="The Rescue",d="Client: Thunder Hawk\n (Mayor's Residence, Selbina)\nSummary:\n Rescue two merchants from\n captivity. They should be\n somewhere in the Quadav\n camp in Beadeaux."},
      [24] = {n="Elder Memories",d="Client: Isacio\n (Waterfront, Selbina)\nSummary:\n You must prove yourself worthy\n before you can learn Isacio's\n fighting techniques."},
      [25] = {n="Test My Mettle",r=1,d="Client: Devean (Behind\n Shepherd's Muster, Selbina)\nSummary:\n Find the pair of power sandals\n hidden in a jar somewhere\n in Davoi. Bring them back\n before time runs out\n for a cash prize."},
      [26] = {n="Inside the Belly",d="Client: Zaldon (Fishermen's\n Guild Salesroom, Selbina)\nSummary:\n Some fish in Vana'diel\n like to eat shiny objects.\n If you catch one, let Zaldon\n cut it open for you."},
      [27] = {n="Trial by Lightning",r=1,d="Client: Ripapa (In front of\n the Sailors' Stay, Mhaura)\nSummary:\n Ring the tuning fork of lightning\n upon the protocrystal in the\n Boyahda Tree. A path will open to\n the trial that awaits."},
      [28] = {n="Trial-Size Trial by Lightning",d="Client: Lacia (In front of\n the Sailors' Stay, Mhaura)\nSummary:\n The Rhinostery has developed a\n new \"mini\" tuning fork of lightning.\n Ringing it upon the protocrystal\n in the Boyahda Tree will open\n the path to a one-on-one battle\n with the beast that awaits inside.\n However, only summoners are\n allowed to take up this challenge."},
      [29] = {n="It's Raining Mannequins",d="Client: Fyi Chalmwoh (Goldsmiths' \n Guild Salesroom, Mhaura)\nSummary:\n Fyi Chalmwoh wants to build a\n mannequin that rivals those of\n times past. It's your job to gather\n information on how to make one."},
      [30] = {n="Recycling Rods",d="Client: Keshab-Menjab\n (Outside Orlando's Antiques,\n Mhaura)\nSummary:\n You've been asked to help\n bring in cleanly snapped rods for\n recycling. The recycled rods are\n supposedly sold somewhere around\n Bibiki Bay."},
      [31] = {n="Picture Perfect",d="Client: Diederik\n (Port, Selbina)\nSummary:\n Diederik has lost a painting ordered\n by a valued customer. He wants you\n to help him earn time or get a new\n painting before anyone notices."},
      [32] = {n="Waking the Beast",r=1,d="Client: Carbuncle\n (La Theine Plateau)\nSummary:\n Carbuncle wants you to visit all the\n protocrystals and gather the\n elemental energy of the sleeping\n gods. Will their imminent awakening\n mean fortune or doom for Vana'diel?\n Only Carbuncle's ancient friend at the\n Full Moon Fountain may know..."},
      [33] = {n="Survival of the Wisest",d="Client: Prof. Schultz\n (Xarcabard)\nSummary:\n What will be the first and final\n assignment given to you by Gunther\n Schultz II, the legendary reformer of\n military strategy? Your rite of passage\n begins by obtaining a scholar's\n testimony..."},
      [34] = {n="Monstrosity",d="Client: Suspicious Hume\n (Pashhow Marshlands)\nSummary:\n You can expand the horizons of your\n soul, and it all begins by bringing\n either a rabbit hide, lizard tail,\n or two-leaf mandragora bud to one of\n the oddly accented and suspicious\n personages in Northern San d'Oria,\n Port Bastok, or Port Windurst."},
      [35] = {n="Kupofried's H2H Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [36] = {n="Kupofried's Dagger Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [37] = {n="Kupofried's Sword Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [38] = {n="Kupofried's Great Sword Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [39] = {n="Kupofried's Axe Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [40] = {n="Kupofried's Great Axe Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [41] = {n="Kupofried's Scythe Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [42] = {n="Kupofried's Polearm Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [43] = {n="Kupofried's Katana Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [44] = {n="Kupofried's Great Katana Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [45] = {n="Kupofried's Club Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [46] = {n="Kupofried's Staff Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [47] = {n="Kupofried's Archery Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [48] = {n="Kupofried's Marksmanship Moogle Magic",d="Client: Kupofried\n (Walk of Echoes)\nSummary:\n Certain arcane powers known as\n \"weapon skills\" in adventurer\n vernacular can supposedly be harbored\n in one's body through the use of\n moogle magic."},
      [64] = {n="A Hard Day's Knight",d="Client: Quelveuiat (Altar of the Dawn,\n Tavnazia)\nSummary:\n Your initiation into the Tavnazian\n order of knights requires you to\n assess the situation from the\n lookout platform in the south of\n Lufaise Meadows."},
      [65] = {n="X Marks the Spot",d="Client: Despachiaire (Elders' Quarters,\n Tavnazia)\nSummary:\n Despachiaire has asked you to\n investigate the Mithran Tracker\n who has come looking for\n Cardinal Mildaurion."},
      [66] = {n="A Bitter Past",d="Client: Frescheque\n (Third floor, Tavnazian Safehold)\nSummary:\n Try to find some information on\n the fate of a little girl who was\n kidnapped in a forest near the\n safehold. Her father says that she\n was wearing a tiny wristlet that is\n similar to her mother's."},
      [67] = {n="The Call of the Sea",d="Client: Anteurephiaux\n (First Floor, Tavnazian Safehold)\nSummary:\n You've been asked to travel to the\n Tavnazian coastline and find a rare\n shell carried by a monster--\n preferably a \"spirally\" one that\n makes sound when you blow into it."},
      [68] = {n="Paradise, Salvation, and Maps",d="Client: Nivorajean\n (Second floor, Tavnazian Safehold)\nSummary:\n To complete a map of the\n Sacrarium, Nivorajean needs\n you to find a piece of the\n old floorplans."},
      [69] = {n="Go! Go! Gobmuffin!",d="Client: Epinolle\n (Third floor, Tavnazian Safehold)\nSummary:\n Epinolle wants you to find and\n bring back a Goblin that has left\n for Cape Riverne to make a map\n of the area."},
      [70] = {n="The Big One",r=1,d="Client: Travonce\n (Tributary, Tavnazian Safehold)\nSummary:\n Travonce's final wish before he\n dies is to reel in \"the big one.\"\n However, your services are required\n to protect him from the monsters\n that lurk below the calm waters of\n Lufaise Meadows."},
      [71] = {n="Fly High",d="Client: Ferchinne\n (Tributary, Tavnazian Safehold)\nSummary:\n \"A noble bird that walks on four\n legs. A proud beast that has the\n wings of an eagle.\" No, this is not\n a riddle; it is a description of the\n beast from which you must retrieve\n two tailfeathers."},
      [72] = {n="Unforgiven",d="Client: Elysia\n (Second Floor, Tavnazian Safehold)\nSummary:\n Find and bring back the hairpin\n that Elysia dropped while doing\n her shopping."},
      [73] = {n="Secrets of Ovens Lost",r=1,d="Client: Jonette\n (Tributary, Tavnazian Safehold)\nSummary:\n Jonette's dream is to revitalize the\n safehold's children by serving them\n an array of traditional Tavnazian\n dishes. However, she needs a\n cookbook to fulfill that dream."},
      [74] = {n="Petals for Parelbriaux",d="Client: Ondieulix\n (Main Entrance, Tavnazian Safehold)\nSummary:\n You have been asked to find a\n rare plant that is often used in\n medicines. It supposedly grows\n somewhere on the Lufaise Meadows."},
      [75] = {n="Elderly Pursuits",d="Client: Despachiaire (Elders' Quarters,\n Tavnazia)\nSummary:\n Despachiaire has asked you to\n investigate the origin of his late\n wife's amulet."},
      [76] = {n="In the Name of Science",d="Client: Yurim (First Floor,\n Tavnazia)\nSummary:\n Yurim wants to show you the\n fruits of her research, but lacks\n the materials to begin the final\n stage of the experiment.\n\n You know what you have to do!"},
      [77] = {n="Behind the Smile",d="Client: Enaremand\n (Third floor, Tavnazian Safehold)\nSummary:\n One last material is required to\n complete Enaremand's final masterpiece.\n Perhaps the mannequin craftswoman\n in Mhaura has some clues to where\n you may be able to find it."},
      [78] = {n="Knocking on Forbidden Doors",d="Client: Enaremand\n (Third floor, Tavnazian Safehold)\nSummary:\n Enaremand's final masterpiece is\n complete, but not as complete\n as he would like. The troubled\n mannequin craftsman has now asked\n you to help him find a necromancer\n in order to breathe life into\n his creation..."},
      [79] = {n="Confessions of a Bellmaker",d="Client: ??? (Stone Monument,\n Riverne - Site #A01)\nSummary:\n A mysterious figure has requested\n your help repairing an old bell\n damaged in the recent earthquakes."},
      [80] = {n="In Search of the Truth",d="Client: Tressia\n (Patrol HQ, Tavnazian Safehold)\nSummary:\n Search for information regarding\n what happened on the day\n Wazozo's treasure was stolen."},
      [81] = {n="Uninvited Guests",r=1,d="Client: Justinius\n (Patrol HQ, Tavnazian Safehold)\nSummary:\n You have been asked to expel the\n black-robed intruders lurking around\n Monarch Linn."},
      [82] = {n="Tango with a Tracker",d="Client: Despachiaire (Elders' Quarters,\n Tavnazia)\nSummary:\n A letter from Shikaree X addressed\n to you has arrived in the safehold.\n It appears she wants to gauge your\n battle prowess in Boneyard Gully."},
      [83] = {n="Requiem of Sin",d="Client: Despachiaire (Elders' Quarters,\n Tavnazia)\nSummary:\n A letter from Shikaree Y addressed\n to you has arrived in the safehold.\n It appears you have been challenged\n to a duel in Boneyard Gully."},
      [84] = {n="VW Op. #026: Tavnazian Terrors",d="Client: Owain\n (Main Entrance, Tavnazian Safehold)\nSummary:\n Reports suggest that planar rifts have\n materialized in Lufaise Meadows, the\n Misareaux Coast, the Uleguerand Range,\n and Attohwa Chasm. Engage and\n exterminate any interdimensional\n threats you may face."},
      [85] = {n="VW Op. #004: Bibiki Bombardment",d="Client: Owain\n (Main Entrance, Tavnazian Safehold)\nSummary:\n Word has it that planar rifts have\n arisen in Bibiki Bay, and that the\n dauntless Prishe has set out to put a\n stop to them. Get there first and\n exterminate all the interdimensional\n beasties you find!"},
      [96] = {n="Bombs Away!",d="Client: Buffalostalker Dodzbraz\n (Uleguerand Range)\nSummary:\n Dodzbraz is an Orc that despises\n snolls.\n If you bring him two \"cluster cores,\"\n Dodzbraz will give you something\n useful to use against them."},
      [97] = {n="Mithran Delicacies",d="Client: Anguenet\n (Carpenters' Landing)\nSummary:\n If you give a \"muddy siredon\" to the\n Tonberry that stands beside\n Anguenet, he will make you one of\n the Mithra's favorite foods."},
      [100] = {n="Give a Moogle a Break",d="Client: Moogle\n (Mog House)\nSummary:\n Your moogle wants to take\n a power bow and a beetle ring\n to his family for the holidays.\n He sure would be happy\n if you found them for him."},
      [101] = {n="The Moogle's Picnic!",d="Client: Moogle\n (Mog House)\nSummary:\n Your moogle wants to take a\n shrimp lure and some Selbina butter\n back home. He sure would be happy\n if you found them for him."},
      [102] = {n="Moogles in the Wild",d="Client: Moogle\n (Mog House)\nSummary:\n Your moogle wants to take a\n raptor mantle and a wool hat to\n his friends in the Outlands.\n He sure would be happy if you found\n them for him."},
      [103] = {n="Missionary Moblin",d="Client: Koblakiq\n (Oldton Movalpolos)\nSummary:\n Koblakiq has stopped receiving\n letters from her brother Zeelozok\n after he went to speak with the\n Orcish overlord in Davoi.\n Koblakiq wants you to go there\n and search for him."},
      [104] = {n="For the Birds",d="Client: Koblakiq\n (Oldton Movalpolos)\nSummary:\n A letter has arrived from Zeelozok\n asking for an \"arnica root\" to be\n brought to Castle Oztroja.\n Koblakiq has entrusted this task\n to you..."},
      [105] = {n="Better the Demon You Know",d="Client: Koblakiq\n (Oldton Movalpolos)\nSummary:\n Zeelozok has set out on a journey\n to destroy the Kindred's Divinity\n of Darkness. Koblakiq wants you\n to find her a \"Demon pen\" so she\n can learn more about their demon\n adversaries."},
      [106] = {n="An Understanding Overlord?",r=1,d="Client:\n Loo Kohor (Monastic Cavern)\nSummary:\n Yagudo messenger Loo Kohor needs\n to deliver an important message.\n However, he cannot proceed, as he\n is attacked every time he sets foot\n in the Monastic Cavern. Your job is\n to take the missive and place it\n where the Overlord is sure to find it."},
      [107] = {n="An Affable Adamantking?",r=1,d="Client:\n Raptorlegs Gedwad (Qulun Dome)\nSummary:\n Gedwad has orders to sneak into\n the Qulun Dome and gather info on\n the Quadav's defenses. However, he\n is stuck at the entrance. Your job\n is to take Gedwad's seeker bats and\n place them somewhere they can spy\n on the Adamantking."},
      [108] = {n="A Moral Manifest?",r=1,d="Client:\n Hooknox (Altar Room)\nSummary:\n Hooknox's plan to steal treasure\n from the Yagudo vault falls through\n when her disguise becomes too\n itchy. Your job is to take the key\n Hooknox swiped and use it to\n collect the riches...without being\n discovered by the Yagudo guards."},
      [109] = {n="A Generous General?",r=1,d="Client:\n Gu'Zho Thunderblade\n (Oldton Movalpolos)\nSummary:\n Gu'Zho has traveled to Movalpolos\n to become a mercenary. However,\n he cannot find the box to submit\n his application. Your job is to take\n Gu'Zho's letter to the box and lead\n the Goblin serjeant back to where\n Thunderblade will be waiting."},
      [110] = {n="Records of Eminence",d="Summary:\n You have officially taken your first\n step down the road to fame with the\n Adventurers' Mutual Aid Network's new\n system: Records of Eminence.\n Now go clear some objectives and\n show Vana'diel your true worth!"},
      [111] = {n="Unity Concord",d="Summary:\n Fight for the glory of your Unity\n leader under this new system\n established by the Adventurers'\n Mutual Aid Network!"},
      [200] = {n="Titillating Tomes",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n The Great Kupellion has come to your\n Mog Garden to help cure the MHMU\n scholars' wibbly wobbly woozies.\n He will need drill calamary from the\n coastal fishing net, a calico comet\n from the pond, and a philosopher's\n stone from a mineral vein."},
      [201] = {n="Release the Fleece",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Susuroon swears fearsome beasts are\n menacing the garden, and employed\n Chacharoon--a supposedly world-class\n bodyguard--to deal with the threat.\n For now, let the bodyguard's lamb\n roam free in the Mog Garden to lure\n these monsters in."},
      [202] = {n="Feeding Frenzy",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n The fearsome beasts in question\n are apparently a rare breed of crab\n that plagued the garden before. While\n Atelloune's research on them may\n yield helpful clues, all you can do is\n motivate the lamb by feeding it\n La Theine cabbage."},
      [203] = {n="Cry Not, Caretaker",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Crabs have ambushed and killed\n Chacharoon's beloved lamb. He has\n decided not to waste the animal's\n life, and thus needs a spool of cotton\n thread to craft an item to bolster his\n defenses and honor his fallen friend."},
      [204] = {n="Chacharoon's Cheer",d="Client: Susuroon\n (Mog Garden)\nSummary:\n Susuroon needs your help getting\n Chacharoon interested in the jingly.\n The young Qiqirn idolizes adventurer\n types, so try handing him a gold\n beastcoin to convince him of your\n worth."},
      [205] = {n="Trial of the Chacharoon",d="Client: Susuroon\n (Mog Garden)\nSummary:\n Chacharoon's life savings have been\n pilfered by some uncouth savage, and\n Susuroon can't face the young one\n himself. Head toward the newly\n cultivated area via the path located\n near the boat to find him."},
      [206] = {n="Doctor Chacharoon",d="Client: Chacharoon\n (Mog Garden)\nSummary:\n Chacharoon has asked you to help\n rescue a sickly adamantoise hatchling\n that has washed up on the shore.\n According to Chacharoon's diagnosis,\n the turtle needs hot soup to recover.\n Gather 12 crayfish for the soup and\n trade them to the Green Thumb Moogle."},
      [207] = {n="Rowing Together",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n While preparing to accommodate four\n creatures in the Mog Garden's rearing\n grounds, Chacharoon has suddenly\n found himself inundated with work.\n Concerned for his health, the Green\n Thumb Moogle has sent you to the\n Goblins' shop in Lower Jeuno to help\n him gather supplies."},
      [208] = {n="Glittering Gals",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n A mysterious troupe of wistful women\n has come to your Mog Garden. They\n seem to be interested in riding\n crabs. Assist them in their endeavor\n by cultivating seeds in your garden."},
      [209] = {n="Sally Forth!",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n The engimatic troupe is now interested\n in sheep. Help the Green Thumb moogle\n out by bringing him Grow-M-Good."},
      [1039] = {n="Full Fields",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Peek inside the basket that rests at\n the end of the Mog Garden furrow."},
      [1040] = {n="Green Groves",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Look around the grove of trees in the\n Mog Garden."},
      [1041] = {n="Mining Missive",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Examine the large boulder in the\n Mog Garden."},
      [1042] = {n="Pond Probing",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Test the waters of the Mog Garden\n pond."},
      [1043] = {n="Coastal Chaos",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Haul in the net cast off the coast of\n the Mog Garden."},
      [1044] = {n="Seed Sowing",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Take a look at the basket near the\n Mog Garden furrow and sow a seed."},
      [1045] = {n="Flotsam Finding",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Check what drifted in on the tide by\n examining a spot on the Mog Garden's\n coastline."},
      [1047] = {n="Courtesy Crustacean",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n The Green Thumb Moogle's friend,\n Monsieur Kupont, is coming to pay him\n a visit, and the vacationing visitor\n appreciates rare and beautiful shells.\n There simply has to be some original\n marine life in the Mog Garden..."},
      [1048] = {n="Trinket for the Tyrant",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n Now Monsieur Kupont's villainous\n friend Kupivolo is joining the fray in\n the Adoulin Islands. Placate this\n pernicious patron by acquiring some\n article of note within the\n Mog Garden."},
      [1049] = {n="Hypnotic Hospitality",d="Client: Green Thumb Moogle\n (Mog Garden)\nSummary:\n A mob of merry moogles has\n manifested in your Mog Garden.\n Stockpile the subsequent sundries so\n your grand guests can be properly\n pampered: a moat carp creel from the\n pond as well as a branch of gnatbane\n and a date from the furrows."},
    }},
    outlands = { name = "Outlands", ids = {
      [0] = {n="FR Quest 0",d="Client�F\n�@"},
      [1] = {n="The Firebloom Tree",r=1,d="Client: Soun Abralah (Ryuhkowa's\n Mercenary Merchandise, Kazham)\nSummary:\n Journey to the Yuhtunga Jungle and\n retrieve a piece of firebloom wood\n from the most fire-resistant side of\n the Firebloom Tree. To check the\n most fire-resistant side, you must\n take a vine from each side of the\n tree to Ifrit's Cauldron for testing."},
      [2] = {n="Greetings to the Guardian",r=1,d="Client: Hari Pakhroib (Pakhroib's\n Residence, Kazham)\nSummary:\n Take your offering to the guardian\n of Kazham to the altar on the crater\n of Mount Yuhtunga."},
      [3] = {n="A Question of Taste",r=1,d="Client: Jakoh Wahcondalo\n (Wahcondalo's Residence, Kazham)\nSummary:\n It all started with a letter sent to\n Kazham's chieftainness by the young\n Windurstian artist, Angelica. Now,\n no one can stop the budding painter."},
      [4] = {n="Everyone's Grudging",d="Client: Jakoh Wahcondalo\n (Wahcondalo's Residence, Kazham)\nSummary:\n You have been cursed by the\n Tonberries' rancor flames, and\n Kazham's chieftainness has ordered\n you out of the village."},
      [5] = {n="FR Quest 5",d="Client�F\n�@"},
      [6] = {n="You Call That a Knife?",d="Client: Mhebi Juhbily (Near Mihgo's\n Residence, Kazham)\nSummary:\n Mhebi wants to set her Tonberry\n free, but first, someone has to do\n something about his rusty knife."},
      [7] = {n="Missionary Man",d="Client: Rauteinot (Near the village\n gate, Kazham)\nSummary:\n First, find a slab of Elshimo marble\n in the Yuhtunga Jungle to help the\n young missionary realize his vision."},
      [8] = {n="Gullible's Travels",d="Client: Magriffon (Celodehki's\n Bed & Breakfast, Kazham)\nSummary:\n Magriffon has given all his worldly\n possessions to save a pack of poor\n Opo-opos from starvation. Now he\n needs someone to save him from\n getting kicked out of the bed &\n breakfast before he has completed\n his \"top-secret\" mission."},
      [9] = {n="Even More Gullible's Travels",d="Client: Magriffon (Celodehki's\n Bed & Breakfast, Kazham)\nSummary:\n Magriffon has spent all of his (your?)\n money to save a maiden in distress.\n Now he needs someone to save him\n (again) from getting kicked out of\n the bed & breakfast before he has\n completed his \"top-secret\" mission."},
      [10] = {n="Personal Hygiene",d="Client: Gatih Mijurabi (M & P's\n Market, Kazham)\nSummary:\n The Mithra of Kazham are having a\n hard time holding in their lunches,\n thanks to the hideous odor you\n obtained after getting too close to\n the blue Rafflesia pollen. The only\n way to get clean is by taking a\n long dip in a hot spring located\n deep beneath the sea."},
      [11] = {n="The Opo-opo and I",d="Client: Vuih Stecoppah (Docks,\n Kazham)\nSummary:\n The Opo-opo in Kazham love your\n new \"fragrance.\" Bring them what\n they want--in the correct order--\n and they will make you their king!"},
      [12] = {n="Trial by Fire",r=1,d="Client: Ronta-Onta (Near\n Wahcondalo's Residence, Kazham)\nSummary:\n Ring the tuning fork of fire upon\n the protocrystal in Ifrit's Cauldron.\n A path will open to the trial that\n awaits."},
      [13] = {n="Cloak and Dagger",d="Client: Jakoh Wahcondalo\n (Wahcondalo's Residence, Kazham)\nSummary:\n The Chieftainess has come up with\n a deadly new dagger technique, but\n needs you to help her devise a way\n of dodging it. However, you must\n first complete your training."},
      [14] = {n="A Discerning Eye (Kazham)",r=1,d="Client: Swift (Airship Dock, Kazham)\nSummary:\n You have been asked to return a\n dropped item to its rightful owner.\n The passenger should be on the next\n airship flight."},
      [15] = {n="Trial-Size Trial by Fire",d="Client: Dodmos (Near Wahcondalo's\n Residence, Kazham)\nSummary:\n The Rhinostery has developed a\n new \"mini\" tuning fork of fire.\n Ringing it upon the protocrystal\n in Ifrit's Cauldron will open\n the path to a one-on-one battle\n with the beast that awaits inside.\n However, only summoners are\n allowed to take up this challenge."},
      [100] = {n="Voidwatch Ops: Border Crossing",d="Client: Kieran (Storage Area, Norg)\nSummary:\n The Voidwatch has begun conducting\n secret operations outside of\n Jeuno and the three nations.\n Receive briefings from agents in\n Kazham and Rabao, then join the\n fight against the Voidwalkers!"},
      [101] = {n="VW Op. #054: Elshimo List",d="Client: Hildegard (Village Gate,\n Kazham)\nSummary:\n Planar rifts have been reported\n in the Yuhtunga Jungle, Ifrit's\n Cauldron, and the Temple of\n Uggalepih. Engage the Voidwalkers\n at each location and obliterate\n them!"},
      [102] = {n="VW Op. #101: Detour to Zepwell",d="Client: Gushing Spring (Oasis, Rabao)\nSummary:\n Planar rifts have been reported\n in the Western Altepa Desert,\n the Kuftal Tunnel, and the Quicksand\n Caves. Engage the Voidwalkers at\n each location and obliterate them!"},
      [103] = {n="VW Op. #115: Li'Telor Variant",d="Client: Kieran (Storage Area, Norg)\nSummary:\n Planar rifts have been reported\n in the Sanctuary of Zi'tah,\n the Boyahda Tree, and Ro'Maeve.\n Engage the Voidwalkers at each\n location and obliterate them!"},
      [104] = {n="Skyward Ho, Voidwatcher!",d="Client: Kieran (Storage Area, Norg)\nSummary:\n Planar rifts have been reported\n in Ru'Aun Gardens, Ve'Lugannon\n Palace, and the Shrine of\n Ru'Avitau. Engage the Voidwalkers\n at each location and obliterate\n them!"},
      [128] = {n="The Sahagin's Key",d="Client�F\n�@"},
      [129] = {n="Forge Your Destiny",d="Client: Jaucribaix (Near the Captain's\n Quarters, Norg)\nSummary:\n A lump of bomb steel and a sacred\n branch are required to make a new\n katana. You will have to ask\n Jaucribaix's pupils to find out where\n you can get these items."},
      [130] = {n="Black Market",d="Client: Muzaffar (Storage area, Norg)\nSummary:\n Bring sets of either four northern\n furs, four pieces of eastern pottery,\n or four southern mummies for a\n hefty reward."},
      [131] = {n="Mama Mia",d="Client�FMamaulabion (Near the\n Auction House, Norg)\nSummary:\n Mamaulabion would like you to\n bring him any \"thuper-dee-duper,\n overflowing with thpethial power\n itemth\" you happen to come across\n in your travels. However, he was\n not able to provide you with any\n details on their whereabouts."},
      [132] = {n="Stop Your Whining",d="Client: Washu (Buccaneer's Quarters,\n Norg)\nSummary:\n Fill up an empty barrel with Opo-opo\n brew found fermenting in trees in\n the Yhoator Jungle, and bring it\n back to Norg ASAP."},
      [133] = {n="Trial by Water",r=1,d="Client: Edal-Tahdal (Near\n the Quay, Norg)\nSummary:\n Ring the tuning fork of water upon\n the protocrystal in the Den of\n Rancor. A path will open to the\n trial that awaits."},
      [134] = {n="Everyone's Grudge",d="Client: Magephaud (Next to the\n central staircase, Norg)\nSummary:\n Bring back three gold beastcoins if\n you want to learn how to rid\n yourself of the Tonberries' rancor."},
      [135] = {n="Secret of the Damp Scroll",d="Client: Shivivi (Near the Captain's\n Quarters, Norg)\nSummary:\n Take the damp scroll you have to\n Horlais Peak and dip it into the hot\n springs there. Only then will you be\n able to read it."},
      [136] = {n="The Sahagin's Stash",d="Client: Laisrean (Storage area,\n Norg)\nSummary:\n Bring back something from the\n Sahagins' storage area in the Sea\n Serpent Grotto. Anything will do."},
      [137] = {n="It's Not Your Vault",d="Client: Keal (Quay, Norg)\nSummary:\n Bring back a sealed iron box from\n the Sahagin-infested Norg vault."},
      [138] = {n="Like a Shining Subligar",d="Client: Heiji (2nd floor, Norg)\nSummary:\n Ten rusty subligaria are needed for\n the training of young ninjas. Heiji\n will accept them one at a time."},
      [139] = {n="Like Shining Leggings",d="Client: Heizo (2nd floor, Norg)\nSummary:\n Ten pairs of rusty leggings are\n needed for the training of young\n ninjas. Heizo will accept them one\n at a time."},
      [140] = {n="The Sacred Katana",d="Client: Jaucribaix (Near the Captain's\n Quarters, Norg)\nSummary:\n Your mumeito and a handful of\n crystal scales are needed to forge\n a katana that will be used in a\n Norg ritual."},
      [141] = {n="Yomi Okuri",d="Client: Gilgamesh (Captain's Quarters,\n Norg)\nSummary:\n Twenty years ago, a small nation\n was destroyed by the flames of war,\n and many died without reason.\n Your assistance is required in\n holding a ritual to send these\n troubled souls to their proper\n resting place in the afterlife."},
      [142] = {n="A Thief in Norg!?",d="Client: Gilgamesh (Captain's Quarters,\n Norg)\nSummary:\n At the close of the Great War,\n Gilgamesh's father trapped a terrible\n spirit within a helm. That helm has\n been stolen, and it is your job to\n hunt down the thief and get it back."},
      [143] = {n="20 in Pirate Years",d="Client: Ryoma (Quay, Norg)\nSummary:\n Norg has begun investigating an\n ancient scroll that was rediscovered\n as of late. Speak with Tenshodo\n member Kagetora in Bastok for\n more details."},
      [144] = {n="I'll Take the Big Box",d="Client: Ryoma (Quay, Norg)\nSummary:\n The trick box that you brought back\n to Norg has been identified as a\n fake. Your assistance is required in\n finding the real box. Start your\n search by pressing Ensetsu in Bastok\n for more information."},
      [145] = {n="True Will",d="Client: Ryoma (Quay, Norg)\nSummary:\n The Sahagin have stolen Mitsunari's\n treasure and hid it somewhere in the\n jungle on Elshimo Island.  It is\n your job to find it."},
      [146] = {n="The Potential Within",d="Client: Jaucribaix (Near the Captain's\n Quarters, Norg)\nSummary:\n Use the katana given to you by\n Jaucribaix to find your true potential.\n When the blade has lost its power,\n then you will know you have been\n accepted."},
      [147] = {n="Bugi Soden",d="Client: Ryoma (Quay, Norg)\nSummary:\n Wield the katana given to you by\n Ryoma until it has been drained of\n its power. Only then will you be\n ready to inherit the knowledge of the\n ancient ninja masters."},
      [148] = {n="Trial-Size Trial by Water",d="Client: Verctissa (Near\n the Quay, Norg)\nSummary:\n The Rhinostery has developed a\n new \"mini\" tuning fork of water.\n Ringing it upon the protocrystal\n in the Den of Rancor will open\n the path to a one-on-one battle\n with the beast that awaits inside.\n However, only summoners are\n allowed to take up this challenge."},
      [149] = {n="An Undying Pledge",d="Client:\n Stray Cloud\n (Quay, Norg)\nSummary:\n Find Stray Cloud's friend Gubokka\n in the Sea Serpent Grotto."},
      [160] = {n="Wrath of the Opo-opos",d="Summary:\n The Opo-opos are not happy that\n you stole their \"red treasure.\"\n Perhaps a polished stone of the\n same color would satisfy them?"},
      [161] = {n="Wandering Souls",d="Summary:\n Is there any way to soothe\n the spirits that wander about\n Cape Teriggan?\n Perhaps a rain lily...?"},
      [162] = {n="Soul Searching",d="Summary:\n Dispel the troubled souls of\n those who perished while on\n their pilgrimages."},
      [163] = {n="Divine Might",d="Client: Yve'noile (Entry Hall,\n The Shrine of Ru'Avitau)\nSummary:\n Use the Ark Pentasphere at the\n La'Loff Amphitheater to confront\n and defeat all five Crystal Warriors\n simultaneously."},
      [164] = {n="Divine Might",d="Client: Yve'noile (Entry Hall,\n The Shrine of Ru'Avitau)\nSummary:\n The dissipated essence of the\n Crystal Warriors has once again\n coalesced into physical form.\n Your battle is not yet over!"},
      [165] = {n="Open Sesame",d="Client: Lokpix (Eastern Altepa Desert)\nSummary:\n There's supposedly a way to open\n that troublesome door in the\n Quicksand Caves by yourself. If you\n wish to know the secret, bring back\n a tremorstone and a meteorite.\n Should you lack a meteorite, either\n a soil gem or twelve soil geodes\n will suffice."},
      [192] = {n="Don't Forget the Antidote",d="Client: Edigey (Sand dune,\n Rabao)\nSummary:\n Edigey wants you to bring him\n some sand scorpion poison so he\n can make an antidote, an\n essential item for the desert\n caravans."},
      [193] = {n="The Missing Piece",d="Client: Alfesar (Near the oasis,\n Rabao)\nSummary:\n The friar Alfesar has asked you to\n find the remaining part of a stone\n tablet that was found in the\n Quicksand Caves that lie beneath\n the Altepa Desert."},
      [194] = {n="Trial by Wind",r=1,d="Client: Agado-Pugado (Near the oasis,\n Rabao)\nSummary:\n Ring the tuning fork of wind upon\n the protocrystal in Cape Teriggan.\n A path will open to the trial that\n awaits."},
      [195] = {n="The Kuftal Tour",d="Client: Datta (Near the oasis,\n Rabao)\nSummary:\n You have been asked to participate\n in a tour planned by Datta.\n Travel to the cliff inside the\n entrance to the Kuftal Tunnel with\n a party of two or more people of\n level forty or less, then meet\n with Datta's partner, Hawk Nose."},
      [196] = {n="The Immortal Lu Shang",d="Client: Irmilant (Near the oasis,\n Rabao)\nSummary:\n Irmilant has said he will repair your\n broken Lu Shang's fishing rod.\n Along with the broken fishing rod,\n you must bring him a piece of\n ancient lumber and two light\n crystals."},
      [197] = {n="Trial-Size Trial by Wind",d="Client: Rahi Fohlatti (Near the oasis,\n Rabao)\nSummary:\n The Rhinostery has developed a\n new \"mini\" tuning fork of wind.\n Ringing it upon the protocrystal\n in Cape Teriggan will open the\n path to a one-on-one battle\n with the beast that awaits inside.\n However, only summoners are\n allowed to take up this challenge."},
      [199] = {n="Chasing Dreams",d="Client: Zoriboh (Near the oasis,\n Rabao)\nSummary:\n A young cargo hauler named\n Sanctia has suddenly left Rabao,\n and Zoriboh wants you to find her.\n According to Zoriboh, she has\n probably headed for Norg to board\n a ship bound for the Tavnazian\n Marquisate..."},
      [200] = {n="The Search for Goldmane",d="Client: Zoriboh (Near the oasis,\n Rabao)\nSummary:\n How is little Sanctia doing?\n Zoriboh wants you to take her a\n present from her father and see\n that she is keeping out of trouble."},
      [201] = {n="Indomitable Spirit",d="Client: Irmilant (Near the oasis,\n Rabao)\nSummary:\n Irmilant has asked you to bring the\n two base materials required to craft\n a legendary fishing rod. These\n materials seem to have found their\n way into the bellies of sea creatures\n that still elude the finest fishermen."},
      [202] = {n="Fish Favors the Bold",d="Client: Irmilant (Near the oasis,\n Rabao)\nSummary:\n The exalted fisherman has posed to\n you a challenge. Collect legendary fish\n from the four corners of Vana'diel."},
      [203] = {n="Thanks for All the Fish",d="Client: Jourdenaux (Near the oasis,\n Rabao)\nSummary:\n Lu Shang's fishing rod has a hidden\n power deep inside, which Jordenaux has\n offered to draw forth if he deems you\n worthy--by collecting 60 types of fish\n and fulfilling all Records of Eminence\n objectives in the \"Fishing (Tenacity)\"\n category."},
    }},
    toau = { name = "Treasures of Aht Urhgan", ids = {
      [0] = {n="Keeping Notes",d="Client: Ahkk Jharcham (Port\n Al Zahbi, Aht Urhgan Whitegate)\nSummary:\n Ahkk Jharcham wants you to bring\n her a sheet of parchment and a jar\n of black ink so she can write down\n her secret."},
      [1] = {n="Arts and Crafts",d="Client: Hadahda (Stoneserpent\n Square, Aht Urhgan Whitegate)\nSummary:\n Hadahda wants you to collect\n pieces of paper with letters\n written on them. You are to\n bring him one each of M, U,\n and T, and two each of A and D."},
      [2] = {n="Olduum",d="Client: Dkhaaya (Balrahn Way,\n Aht Urhgan Whitegate)\nSummary:\n Dkhaaya wants you to bring him an\n artifact of the Olduum civilization."},
      [3] = {n="Got It All",d="Client: Tehf Kimasnahya (Balrahn\n Way, Aht Urhgan Whitegate)\nSummary:\n Tehf Kimasnahya wants you to\n get a vial of luminous water\n from Ekhu Pesshyadha."},
      [4] = {n="Get the Picture",d="Client: Balakaf (Port Ephramad,\n Aht Urhgan Whitegate)\nSummary:\n Take pictures with Balakaf's\n \"image recorder\" at the places\n he specifies."},
      [5] = {n="An Empty Vessel",d="Client: Waoud (Heretic's Alley,\n Aht Urhgan Whitegate)\nSummary:\n There is a rare treasure in the\n \"Middle Lands\" that Waoud needs\n someone to obtain for him..."},
      [6] = {n="Luck of the Draw",d="Client: Ratihb (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Ratihb wants you to check on\n his son Wasuhd, who has gone\n in search of his older brother."},
      [7] = {n="No Strings Attached",d="Client: Iruki-Waraki (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n If you want to learn how to\n become a puppetmaster, you must\n bring an automaton to Iruki-Waraki."},
      [8] = {n="Finding Faults",r=1,d="Client: Hishahma (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Journey to the lands where\n dangerous monsters reside and\n investigate their weak points.\n According to previous research,\n each type of monster should\n possess two weak points."},
      [9] = {n="Give Peace a Chance",d="Client: Mishhar (Serpentking Square,\n Aht Urhgan Whitegate)\nSummary:\n Mishhar wants you to find out what\n Isween is doing out in the Wajaom\n Woodlands at night."},
      [10] = {n="The Art of War",r=1,d="Client: Hishahma (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Hishahma's special forces are\n struggling in their battle against\n certain monsters. You must find\n an effective strategy to defeat\n the enemy."},
      [12] = {n="A Taste of Honey",d="Client: Qutiba (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Qutiba wants you to bring her\n three pots of white honey so she\n can make the famous Near Eastern\n confectionery \"irmik helvasi.\""},
      [13] = {n="Such Sweet Sorrow",d="Client: Dabhuh (Gladiator's Alley,\n Aht Urhgan Whitegate)\nSummary:\n Dabhuh wants you to bring him\n a Merrow scale."},
      [14] = {n="Fear of the Dark II",d="Client: Suldiran (Galeserpent Square,\n Al Zahbi)\nSummary:\n Bring Suldiran two imp wings."},
      [15] = {n="Cook-a-roon?",d="Client: Ququroon (North of the\n Weapon Shop, Nashmau)\nSummary:\n Ququroon wants to practice cooking\n so he can open a restaurant one day.\n Help him out by bringing him the\n ingredients he requires."},
      [16] = {n="The Die Is Cast",d="Client: Ratihb (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Yadhiwa cheated Balajaha out of\n a large sum of money. Help him\n get back the gold he lost to her\n crafty devices."},
      [17] = {n="Two Horn the Savage",d="Client: Milazahn (Balrahn Way,\n Aht Urhgan Whitegate)\nSummary:\n The ferocious \"Two Horn the\n Savage\" has been wreaking havoc\n around the Empire, but nobody\n knows the creature's identity or\n its whereabouts. You are to lead\n an investigation into the facts\n surrounding this frightening beast."},
      [18] = {n="Totoroon's Treasure Hunt",d="Client: Totoroon (Port, Nashmau)\nSummary:\n Totoroon has found a\n \"soooper-doooper\" treasure.\n He will tell you where it is hidden\n in exchange for something sweet."},
      [19] = {n="What Friends Are For",d="Client: Tsetseroon (Junk Seller,\n Nashmau)\nSummary:\n Tsetseroon needs a cobalt jellyfish\n and a chunk of tin ore to make his\n special stew."},
      [20] = {n="Rock Bottom",d="Client: Zurtermor (Mount Zhayolm)\nSummary:\n Zurtermor has dropped his\n precious pickaxe into a crevasse..."},
      [21] = {n="Beginnings",d="Client: Raubahn\n(???, Aht Urhgan Whitegate)\nSummary:\n An unavoidable decision...\n If you would seek even greater\n power, meet with the Immortals\n stationed at the Azouph Isle,\n Dvucca Isle, Mamool Ja, Halvung,\n and Ilrusi staging points."},
      [22] = {n="Omens",d="Client: Raubahn\n(???, ???)\nSummary:\n The only choice you have left is to\n forge ahead in the quest for power,\n or face your own destruction...\n If ambition still fuels your soul,\n head to the Navukgo Execution\n Chamber and obliterate the\n monstrous flan!"},
      [23] = {n="Transformations",d="Client: Raubahn\n(???, Imperial Ward)\nSummary:\n A juvenile soulflayer has been\n discovered in the Alzadaal Undersea\n Ruins. Make your way to the ruins\n and eliminate this threat."},
      [24] = {n="Equipped for All Occasions",d="Client: Qultada (Arrapago Reef)\nSummary:\n In order to become an official\n Seagull Phratrie crew member, you\n need a proper weapon. According to\n the crew, you may be able to find\n one in an old cave..."},
      [25] = {n="Navigating the Unfriendly Seas",d="Client: Zweeha (Arrapago Reef)\nSummary:\n The seas around Arrapago Reef\n cannot be navigated without a\n hydrogauge, and it is your job to\n find one. Ships from the Kingdom\n of Ephramad all had one, but that\n was long ago..."},
      [26] = {n="Against All Odds",d="Client: Zweeha (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Qultada has been captured by the\n Empire. Head to Arrapago with the\n Seagull Phratrie crew and save\n your captain!"},
      [27] = {n="The Wayward Automaton",d="Client: Iruki-Waraki (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Iruki-Waraki's automaton has been\n stolen! Go to Nashmau and see if\n you can find some information on\n its whereabouts."},
      [28] = {n="Operation Teatime",d="Client: Iruki-Waraki (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Iruki-Waraki wants you to\n cooperate with his plan to take\n back his automaton."},
      [29] = {n="Puppetmaster Blues",d="Client: Iruki-Waraki (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Iruki-Waraki has lost all faith in\n himself. Meet with his teacher and\n try to find a way to get Elisabeth\n to come around."},
      [30] = {n="Moment of Truth",d="Client: Mishhar (Serpentking Square,\n Aht Urhgan Whitegate)\nSummary:\n Mishhar wants you to explain to\n Minfram the facts about what\n happened between Isween and the\n beastmen."},
      [31] = {n="Three Men and a Closet",d="Client: Kubhe Ijyuhla (Serpentking\n Square, Aht Urhgan Whitegate)\nSummary:\n The three volunteer soldiers Foudeel,\n Wahboud, and Bashraf have been\n acting strange lately. To help Kubhe\n find out what is really going on, you\n first must travel to the Wajaom\n Woodlands and train with Foudeel."},
      [32] = {n="Five Seconds of Fame",d="Client: Balakaf (Port Ephramad,\n Aht Urhgan Whitegate)\nSummary:\n You are to scour the city for\n various intriguing events and\n record them on Balakaf's new\n photopticator."},
      [40] = {n="The Beast Within",d="Client: Raubahn\n(???, ???)\nSummary:\n No questions. No refusals.\n Obtain a \"blue mage's testimony\"\n and present yourself at the\n Imperial Whitegate."},
      [41] = {n="Breaking the Bonds of Fate",d="Client: Qultada (Arrapago Reef)\nSummary:\n Qultada is waiting on Arrapago\n Reef for you to bring him a\n corsair's testimony. The reasons\n for his request are shrouded in\n mystery..."},
      [43] = {n="Saga of the Skyserpent",d="Client: Biyaada (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Venture into Halvung to search for\n the Skyserpent General's stolen\n keepsake."},
      [44] = {n="Ode to the Serpents",d="Client: Fari-Wari (Shararat\n Teahouse, Aht Urhgan Whitegate)\nSummary:\n Fari-Wari is working on the sequel\n to his masterpiece and has asked\n you to interview the adjutants to\n the Serpents Generals in Al Zahbi."},
      [45] = {n="When the Bow Breaks",d="Client: Gaweesh (Al Zahbi)\nSummary:\n Find the Galeserpent General in the\n Wajaom Woodlands, where she\n spends her spare time gazing on\n some object from her past..."},
      [46] = {n="Fist of the People",d="Client: Talhaal (Al Zahbi)\nSummary:\n Talhaal has agreed to tell you\n about the Stoneserpent General's\n deeds. Wait for him at the Shararat\n Teahouse."},
      [47] = {n="Soothing Waters",d="Client: Fari-Wari (Shararat\n Teahouse, Aht Urhgan Whitegate)\nSummary:\n Fari-Wari is under pressure from\n moneylenders to repay his loan,\n but it seems he's found a new\n theme for his next bestseller..."},
      [48] = {n="Embers of His Past",d="Client: Fari-Wari (Shararat Teahouse,\n Aht Urhgan Whitegate)\nSummary:\n Fari-Wari is seeking inspiration for\n his latest masterpiece, but things get\n messy when his would-be protagonist\n is put on trial for a bizarre crime..."},
      [60] = {n="The Prankster",d="Client: Ahaadah (Philosopher's Alley,\n Aht Urhgan Whitegate)\nSummary:\n Alcander and Ahaadah want you\n to help Tinga-Matonga become a\n respectable citizen."},
      [61] = {n="Delivering the Goods",d="Client: Fochacha (Serpentking\n Square, Aht Urhgan Whitegate)\nSummary:\n Fochacha's cooking supplies have\n been stolen! Her son has gone to\n retrieve them, but how is he faring?\n You might try looking for him at\n the Shararat Teahouse, where\n gourmet aficionados are known to\n reside..."},
      [62] = {n="Vanishing Act",d="Client: Ulamaal, Qutiba (Shararat\n Teahouse, Aht Urhgan Whitegate)\nSummary:\n The leader of the \"Epicureans\" has\n been missing ever since saying he\n was going to the port.\n Where could he have gone...?"},
      [63] = {n="Striking a Balance",d="Client: Wazyih (Stoneserpent Square,\n Aht Urhgan Whitegate)\nSummary:\n Wazyih's failure to deliver a\n package has resulted in a rift\n between him and Saliyahf.\n The self-proclaimed \"Defenders\n of Aht Urhgan\" need your help!"},
      [64] = {n="Not Meant to Be",d="Client: Wadayra (Northern Gate,\n Nashmau)\nSummary:\n Wadayra wants you to look for her\n precious son, Ahgdeen, who has run\n away from home. He must be sorely\n missing his dear mother by now.\n Apparently he was last sighted in\n the northern part of Caedarva Mire."},
      [65] = {n="Led Astray",d="Client: Galiwao (Way of the\n Devout, Aht Urhgan Whitegate)\nSummary:\n Help Galiwao and his colleagues\n locate their employer before their\n worst fears are realized."},
      [66] = {n="Rat Race",d="Client: Kakkaroon (Port, Nashmau)\nSummary:\n Young Rapipi adores the Qiqirn\n and wants to make friends with\n all the furry beastmen in Nashmau.\n However, therein lies the dilemma\n for poor Kakkaroon, who is deathly\n afraid of children. Perhaps \"Nadee\"\n can provide some advice on how to\n bring the two together."},
      [67] = {n="The Prince and the Hopper",d="Client: Maudaal (Victory Arch,\n Aht Urhgan Whitegate)\nSummary:\n You have been hired by Professor\n Clavauert B Chanoix to accompany\n him and his guinea toad, Salwa-\n Molwa, to Mamook where they will\n conduct research on the elusive\n Poroggo."},
      [68] = {n="VW Op. #050: Aht Urhgan Assault",d="Client: Camille (Postern,\n Wajaom Woodlands)\nSummary:\n The Empire may refuse to recognize\n their existence, but planar rifts have\n indeed appeared in Arrapago Reef,\n Mount Zhayolm, Mamook, and\n Caedarva Mire. Eradicate each of the\n Voidwalker threats to save the realm!"},
      [69] = {n="VW Op. #068: Subterranean Skirmish",d="Client: Camille (Postern,\n Wajaom Woodlands)\nSummary:\n The Immortals have hinted at\n planar rift appearances in\n Aydeewa Subterrane. Venture\n underground to bore through this\n latest Voidwalker threat!"},
      [70] = {n="An Imperial Heist",d="Client: Ovjang\n (Salaheem's Sentinels,\n Aht Urhgan Whitegate)\nSummary:\n Locate and retrieve the ancient\n weapons stolen from the Imperial\n Treasury. Quartz transmitters planted\n on the weapons indicate that they lay\n somewhere in the deepest ruins of\n Nyzul Isle..."},
      [71] = {n="Duties, Tasks, and Deeds",d="Client: Paparoon\n (Nashmau)\nSummary:\n Honorary officer Paparoon has been\n brought on to see that you carry out\n your imperial orders. Alexandrite,\n Wyrmseeker Areuhat, assault memoires,\n holy relics... A multitude of paths lay\n open before you."},
      [72] = {n="Forging a New Myth",d="Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n Driven by ambition, yet still\n haunted by the dismebodied whispers\n that come at the weapon's touch, you\n have been ordered by Nashmeira in\n the name of the Empire to harness\n the seemingly unconquerable power\n of the mythic weapons."},
      [73] = {n="Coming Full Circle",d="Client: Balrahn\n (Nyzul Isle)\nSummary:\n \"You must call upon the cemetery\nin Caedarva Mire while bearing your\nmythic weapon. Seek out the great\npowers at rest there...\"\n But exactly to what end does the\ngreat Balrahn intend to send you...?"},
      [74] = {n="Waking the Colossus",d="Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n Curious readings from the chamber\n where the iron colossus sleeps have\n Imperial researchers ill at ease. At Her\n Majesty's behest, seek the support of\n the four nations for a plan to repair\n the colossus and free the Empire from\n its shadow once and for all."},
      [75] = {n="Divine Interference",r=1,d="Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n The avatar of Alexander once again\n threatens to force its way through the\n spatial distortion in Nyzul. Procure a\n replacement power source from the\n Moblin Megomak and reactivate the\n colossus to send the extradimensional\n intruder back whence it came."},
      [76] = {n="The Rider Cometh",d="Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n Ominous rumors circulating among the\n mercenary ranks speak of Dark Rider\n sightings deep within the Hazhalm\n Testing Grounds. Could this\n occurrence bear any connection to\n the unsealed spatial distortion? It\n falls to you to investigate."},
      [77] = {n="Unwavering Resolve",r=1,d="Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n Ghatsad aims to seal the distortion\n that is the Dark Rider's portal into\n this world. You must procure another\n key and return to Hazhalm to collect\n the data he seeks. Meanwhile, Ovjang\n and Mnejing would ask of you a favor\n of their own..."},
      [78] = {n="A Stygian Pact",r=1,d="Client: Nashmeira\n (Throne Room, Imperial Ward)\nSummary:\n To reclaim the soul of Prince Luzaf,\n you have have entered an unholy\n covenant with the Dark Divinity. What\n trials await you as Odin's knight?\n Shrink not from the shadows, and be\n strong in your convictions, that you\n might emerge unscathed!"},
      [90] = {n="Promotion: Private First Class",d="Client: Naja Salaheem (Salaheem's\n Sentinels, Aht Urhgan Whitegate)\nSummary:\n President Naja wants you to bring\n her an imp wing."},
      [91] = {n="Promotion: Superior Private",d="Client: Naja Salaheem (Salaheem's\n Sentinels, Aht Urhgan Whitegate)\nSummary:\n Your task is to find some hard\n evidence that the \"Dark Rider\" has\n truly appeared out of legend and is\n terrorizing the Empire."},
      [92] = {n="Promotion: Lance Corporal",d="Client: Naja Salaheem (Salaheem's\n Sentinels, Aht Urhgan Whitegate)\nSummary:\n Falzum, your fellow mercenary, has\n been given the task of creating a\n batch of mythralline liquid. As his\n superior, it is your job to teach\n him how a mercenary carries out\n his duty."},
      [93] = {n="Promotion: Corporal",d="Client: Naja Salaheem (Salaheem's\n Sentinels, Aht Urhgan Whitegate)\nSummary:\n To track the movements of the\n Dark Rider, you have been given a\n quartz transmitter to place in his\n warhorse's hoofprints."},
      [94] = {n="Promotion: Sergeant",d="Client: Naja Salaheem (Salaheem's\n Sentinels)\nSummary:\n The perfumier Liliroon has come to\n Salaheem's Sentinels in search of\n help, believing it to be a famous\n detective agency. President Naja\n wants you to help collect her\n lucrative reward."},
      [95] = {n="Promotion: Sergeant Major",d="Client: Naja Salaheem (Salaheem's\n Sentinels)\nSummary:\n You must fulfill your duty\n as a sergeant by training up\n your subordinates into proper\n mercenaries."},
      [96] = {n="Promotion: Chief Sergeant",d="Client: Abquhbah (Salaheem's\n Sentinels)\nSummary:\n Abquhbah has asked you to visit the\n weapon shop in his stead. His heavy\n sighs have you slightly worried..."},
      [97] = {n="Promotion: Second Lieutenant",d="Client: Naja Salaheem (Salaheem's\n Sentinels)\nSummary:\n To earn your position in the upper\n ranks of Salaheem's Sentinels, you\n have enrolled in the Salaheem\n Officer Academy.\n Be the best that you can be!"},
      [98] = {n="Promotion: First Lieutenant",d="Client: Naja Salaheem (Salaheem's\n Sentinels)\nSummary:\n Your final term at the Salaheem\n Officer Academy has begun.\n Will all the cadets survive until\n graduation...?"},
      [99] = {n="Promotion: Captain",d="Client: Abquhbah (Salaheem's\n Sentinels)\nSummary:\n Give President Naja a massage\n using the technique Abquhbah has\n shown you. Who knows? It may\n just tip the scales in your favor..."},
      [101] = {n="Scouting the Ashu Talif",r=1,d="Client: Halshaob (Port, Nashmau)\nSummary:\n According to a report, the pirate\n ship Ashu Talif's crew is armed and\n dangerous. The Maelstrom Company\n is to board the ship and judge the\n severity of the threat, and if\n possible, eliminate it."},
      [102] = {n="Royal Painter Escort",r=1,d="Client: Halshaob (Port, Nashmau)\nSummary:\n The Empress has sent her royal\n painter Faluuya to the Ashu Talif\n to sketch diagrams of the ship.\n The Maelstrom Company is to\n protect her as she completes her\n work."},
      [103] = {n="Targeting the Captain",r=1,d="Client: Halshaob (Port, Nashmau)\nSummary:\n The Imperial Army has decided that\n the only way to rid the Empire of\n the Ashu Talif is to dispose of its\n captain. The Maelstrom Company is\n to board the Ashu Talif with a small\n force and end the threat for good."},
    }},
    crystal_war = { name = "Crystal War", ids = {
      [0] = {n="Lost in Translocation",d="Client: Thorben (Entrance to\n Eldieme Necropolis, Batallia Downs)\nSummary:\n Thorben has dropped his squad's\n map of Grauberg somewhere in the\n Eldieme Necropolis.\n Find the map and return it to him."},
      [1] = {n="Message on the Wind",d="Client: Romualdo (Cannon Battery\n Batallia Downs)\nSummary:\n Romualdo believes he has heard\n the voice of his deceased father\n in Grauberg. He'd like to head there\n again to find out for sure, but is\n unable to leave his post..."},
      [2] = {n="The Weekly Adventurer",d="Client: Naiko-Paneiko (Crawlers'\n Nest)\nSummary:\n Battlefield journalist Naiko-Paneiko\n has received intriguing leads\n concerning the appearance of a\n monster in the Rolanberry Fields.\n Go nab the scoop!"},
      [3] = {n="Healing Herbs",d="Client: Maju-Naju \n (Rhinostery, Windurst Waters)\nSummary:\n Maju-Naju's research has ground to\n a halt. He needs research materials\n that are hard to find in this day\n and age..."},
      [4] = {n="Redeeming Rocks",d="Client: Kocco Ehllek (Windurst\n Waters)\nSummary:\n It seems young Kocco is always\n upsetting her mother with her\n mischievous pranks..."},
      [5] = {n="The Dawn of Delectability",d="Client: Ranpi-Monpi (Windurst\n Waters)\nSummary:\n The outbreak of war has\n done away with any semblance of\n motivation aspiring chef\n Ranpi-Monpi may have had. If only\n he could experience the unique and\n extraordinarily new delectable dish\n that he dreams of..."},
      [6] = {n="A Little Knowledge",d="Client: Erlene & Ulbrecht (Eldieme\n Necropolis, Batallia Downs)\nSummary:\n You have been given the chance\n to study the grimoire used by the\n famous Schultz School of Martial\n Theory.\n Your first task is to bring Erlene\n twelve sheets of vellum."},
      [7] = {n="The Fighting Fourth",d="Client: Adelbrecht (Freidrich\n Battery, Bastok Markets)\nSummary:\n Deliver rations to the Eduard\n Watchtower in North Gustaberg."},
      [8] = {n="Snake on the Plains",d="Client: Miah Riyuh\n (Cobra Command, Windurst Waters)\nSummary:\n Take a jar of Zonpa-Zippa's\n All-Purpose Putty to the stone\n towers in West Sarutabaruta, and\n repair any cracks you find in the\n doors."},
      [9] = {n="Steamed Rams",d="Client: Mainchelite (Victory Square,\n Southern San d'Oria)\nSummary:\n Recent sightings of an unidentified\n flying object have the Royal\n Knights perplexed. Venture out into\n East Ronfaure and collect three\n pieces of evidence that may assist\n the Kingdom in its investigation."},
      [10] = {n="Seeing Spots",d="Client: Wyatt (Lion Square,\n Southern San d'Oria)\nSummary:\n To assist in the war effort, or so he\n claims, Wyatt requires a number of\n ladybug wings to turn out some\n new armor. Gather some and bring\n them back to him for a reward."},
      [11] = {n="The Flipside of Things",d="Client: Rarcasmeault (Garlaige\n Citadel)\nSummary:\n Rarcasmeault has mistakenly placed\n a firepower case in the Firesand\n Storeroom. Retrieve it and bring it\n back to him."},
      [12] = {n="Better Part of Valor",d="Client: Wolfram (North Gustaberg,\n Bastok Markets Gate)\nSummary:\n Deliver the clump of animal hair to\n a man named Engelhart."},
      [13] = {n="Fires of Discontent",d="Client: Engelhart (Harmodios's Music\n Shop, Bastok Markets)\nSummary:\n Chairman Pale Eagle is planning to\n fan the growing fire of Galkan\n anger into a full-scale uprising.\n Gather as much information you\n can."},
      [14] = {n="Hammering Hearts",d="Client: Scarred Shark (Portside,\n Bastok Markets)\nSummary:\n A new type of Quadav armor has\n been causing tension in the\n military. Ghemp wants a heavy\n Quadav chestplate and heavy\n Quadav backplate for analysis.\n Obtain and deliver the items to\n Scarred Shark for a reward."},
      [15] = {n="Gifts of the Griffon",d="Client: Excenmille (Watchdog Alley,\n Southern San d'Oria)\nSummary:\n The Young Griffons have made good\n luck charms for their elders.\n Deliver the charms as your first\n duty to the order."},
      [16] = {n="Claws of the Griffon",d="Client: Altennia (Watchdog Alley,\n Southern San d'Oria)\nSummary:\n Altennia has asked you to watch\n over the Young Griffons as they\n devise a reckless plan to eliminate\n the Orcish threat..."},
      [17] = {n="The Tigress Stirs",d="Client: Dhea Prandoleh\n (Cobra Command, Windurst Waters)\nSummary:\n Volunteer mercenaries have arrived\n from Olzhirya just as Ajido-Marujido\n delivers news of a possible attack\n by an unseen breed of Yagudo.\n Bring Ajido the starfruit he buried\n somewhere in West Sarutabaruta."},
      [18] = {n="The Tigress Strikes",d="Client: Dhea Prandoleh\n (Cobra Command, Windurst Waters)\nSummary:\n The Mithra Mercenaries have set\n out towards Fort Karugo-Narugo to\n hunt down the Yagudo. You find\n yourself headed to the same\n destination in search of the\n impetuous young Ajido-Marujido..."},
      [19] = {n="Light in the Darkness",d="Client: Gentle Tiger (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n Gentle Tiger has been tirelessly\n watching the entrance to the\n Metalworks.\n How did Pagdako manage to sneak\n past him...?"},
      [20] = {n="Burden of Suspicion",d="Client: Gentle Tiger (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n It appears Senator Werner had a\n secret mercenary force in his employ.\n What other clandestine plans will be\n uncovered as the investigation\n continues...?"},
      [21] = {n="Evil at the Inlet",d="Client: Rodeupansat\n (Crawlers' Nest)\nSummary:\n Take Rodeupansat's evil warding\n seal and attach it to the\n southwestern tower at Vunkerl\n Inlet in order to cleanse the\n area of evil."},
      [22] = {n="The Fumbling Friar",d="Client: Fondactiont\n (Garlaige Citadel)\nSummary:\n Fondactiont wants you to find and\n bring back an important package\n that he \"dropped\" into the\n river in Grauberg."},
      [23] = {n="Requiem for the Departed",d="Client: Heptachiond\n (The Eldieme Necropolis)\nSummary:\n Heptachiond is running low on the\n incense he lights in prayer as an\n offering to the departed.\n Apparently, the incense is made\n by a friend who is now at Fort\n Karugo-Narugo."},
      [24] = {n="Boy and the Beast",d="Client: Excenmille\n (Vunkerl Inlet)\nSummary:\n Klythios the Gigas has hurt his\n leg during an epic fish-off with\n Excenmille. Make haste and go\n gather the correct healing herb\n to treat the injury."},
      [25] = {n="Wrath of the Griffon",d="Client: Rahal (Watchdog Alley,\n Southern San d'Oria)\nSummary:\n Squire Altennia has been captured\n by Orcs, and is being held at\n their encampment in southern\n Jugner Forest. Rescue her before\n it's too late!"},
      [26] = {n="The Lost Book",d="Client: Yoran-Oran\n (Rhinostery, Windurst Waters)\nSummary:\n A book that Yoran-Oran borrowed\n from the Library of Magic was\n supposedly stolen and taken to\n Giddeus by the Yagudo."},
      [27] = {n="Knot Quite There",d="Client: Romaa Mihgo\n (Aurastery, Windurst Waters)\nSummary:\n Koru-Moru has set off to Jeuno\n with an inexperienced Mithran\n escort.\n Romaa wants you to make sure\n they arrive safely."},
      [28] = {n="A Manifest Problem",d="Client: Romaa Mihgo\n (Fort Karugo-Narugo)\nSummary:\n After deciphering the Yagudo\n message, you return to Fort\n Karugo-Narugo to find the\n Tigresses missing.\n Fetch them back from Castle\n Oztroja before it's too late..."},
      [29] = {n="Beans Ahoy!",d="Client: Thierride (Pikeman's Way,\n Southern San d'Oria)\nSummary:\n Grounded fisherman Thierride is\n in search of a seasoning that\n will allow him to make the most\n mouthwatering bean dish in\n Vana'diel."},
      [30] = {n="Beast from the East",d="Client: Nichais (Lion Square,\n Southern San d'Oria)\nSummary:\n The task of ascertaining what\n truths or falsehoods might lie behind\n the legend of the so-called Mountain's\n Eye has fallen to you. At the behest\n of studious Nichais, make haste to the\n wilds of Grauberg and find what\n secrets may await..."},
      [31] = {n="The Swarm",d="Summary:\n A vermin infestation of unprecedented\n scale has broken out within the mines,\n severely disrupting mining operations\n and causing considerable financial\n loss to the industry. The Silvermines\n Pest Control Committee is urgently\n recruiting dauntless individuals to\n aid in their extermination. Items\n found within the premises can be\n utilized at your discretion."},
      [32] = {n="On Sabbatical",d="Client: Erlene & Ulbrecht (Eldieme\n Necropolis, Batallia Downs)\nSummary:\n Prof. Schultz, founder of the seminal\n Schultz School of Martial Theory, has\n vanished. Set out and find the missing\n professor to set Erlene's mind at ease,\n and to deliver Ulbrecht's message."},
      [33] = {n="Downward Helix",d="Client: Erlene (Eldieme Necropolis,\n Batallia Downs)\nSummary:\n Magicians in the service of the Allied\n Forces have been disappearing with\n unsettling regularity. To solve the\n mystery of their whereabouts, first\n journey to San d'Oria to participate in\n the emergency council being held\n there."},
      [34] = {n="Seeing Blood-red",d="Client: Erlene (Eldieme Necropolis,\n Batallia Downs)\nSummary:\n Ulbrecht's maniacal machinations have\n been made clear, and only one person\n holds the key to tracking him down.\n Find Professor Schultz!"},
      [35] = {n="Storm on the Horizon",d="Client: Klara (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n Senator Karst has left\n unescorted for a meeting with\n Chairman Pale Eagle. You are to\n accompany Mythril Musketeer\n Volker to the rendezvous point\n and bear witness to the exchange\n between the two leaders."},
      [36] = {n="Fire in the Hole",d="Client: Klara (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n Assist the Mythril Musketeers in\n their operation to destroy the\n siege turrets hidden inside the\n Ruhotz Silvermines."},
      [37] = {n="Perils of the Griffon",d="Client: Rahal (Watchdog Alley,\n Southern San d'Oria)\nSummary:\n As if the threat of disbandment was\n not enough, the Young Griffons must\n also fend off a determined Captain\n Rongelouts from confiscating their\n Orcish warmachine. Assist them in\n the desperate defense of their\n base!"},
      [38] = {n="In a Haze of Glory",d="Client: Diordinne\n (Garlaige Citadel)\nSummary:\n Despite heightened security, the\n Garlaige Citadel has been infiltrated\n by an unseen enemy who is emitting\n poisonous gas with brutal results.\n Amidst the confusion, zealous new\n captain, Rahal, has ventured off\n on his own. Find him and ensure he\n does not come to harm."},
      [39] = {n="When One Man Is Not Enough",d="Client: Romaa Mihgo\n (Cobra Command, Windurst Waters)\nSummary:\n The Mithran mercenary majors are\n feuding over exclusive rights to\n Lehko Habhoka who is now presumed\n to be hiding out in Sarutabaruta.\n Find and bring back the heartthrob\n before things get out of hand."},
      [40] = {n="A Feast for Gnats",d="Client: Robel-Akbel\n (Windurst Waters)\nSummary:\n The Cobra Unit and the newly\n arrived Cheetah Volunteers have\n received orders to conduct a\n joint diversionary operation in\n Sauromugue Champaign. Participants\n are to convene on-location."},
      [41] = {n="Say It with a Handbag",d="Client: Hampu-Kampu\n (Windurst Waters)\nSummary:\n Kipopo has vanished with the\n handcrafted handbag her father,\n Hampu-Kampu, made for a certain\n special someone. Locate Kipopo\n and ask her to return the handbag\n to her distraught father."},
      [42] = {n="Quelling the Storm",d="Client: Klara (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n The notorious assassin Darksteel\n Hurricane has returned in full force\n to wreak havoc on the embattled\n Republic of Bastok. Assist the\n Mythril Musketeers to locate and\n apprehend the blood-thirsty criminal\n before more lives are lost."},
      [43] = {n="Honor Under Fire",d="Client: Nicolaus (Entrance to \n Metalworks, Bastok Markets)\nSummary:\n A disconsolate Five Moons has\n departed for the Vunkerl Inlet,\n driven by the desire to attain\n closure over the death of his\n former hero and role model,\n Darksteel Hurricane. Follow your\n Mythril Musketeer comrade and offer\n him support in this time of need."},
      [44] = {n="The Price of Valor",d="Client: Rahal\n (Jugner Forest)\nSummary:\n Bloodwing Horde military tactician,\n Zogbog, has made bold claims that\n he holds the key to nullifying\n Tavnazia's impenetrable defensive\n walls. Help the Swiftwing Griffins\n in their risk-ridden mission to\n uncover the nature of his latest plot."},
      [45] = {n="Bonds That Never Die",d="Client: Cyranuce\n (Pashhow Marshlands)\nSummary:\n Determined not to let Machegue's\n death be in vain, Excenmille has\n disobeyed his father's direct orders\n and embarked on a solitary mission\n to slay the behemoth. Follow him to\n Jugner Forest and ensure his safety!"},
      [46] = {n="The Long March North",d="Client: Robel-Akbel\n (Windurst Waters)\nSummary:\n Battered but not beaten, the\n Windurstian army steels itself for a\n grueling march north. The first leg of\n the journey takes you to San d'Oria,\n where you and your Cobra companions\n will learn what trouble lies brewing\n on the Valdeaunian front."},
      [47] = {n="The Forbidden Path",d="Client: Lehko Habhoka\n (Windurst Waters)\nSummary:\n In his secret laboratory deep beneath\n Windurst, the genius Karaha-Baruha\n pores over ancient tomes, that he\n might once again summon the Great\n Beast in his nation's time of need.\n Deliver what he seeks to Velda-Galda\n by the gate to Windurst Walls!"},
      [48] = {n="A Jeweler's Lament",d="Client: Wahid (Gem Shop,\n Bastok Markets)\nSummary:\n His line of supply cut off due to the\n worsening war climate, the pompous\n gem merchant Wahid has entreated\n you to find a sunstone, an\n aquamarine, and a jadeite to\n replenish his inventory."},
      [49] = {n="Beneath the Mask",d="Client: Nicolaus (Entrance to\n Metalworks, Bastok Markets)\nSummary:\n Disgraced by the actions of the\n traitorous Captain Klara, the Mythril\n Musketeers have been relegated to\n serve in penal detachments. The mood\n turns darker still with the news that\n Zeid has deserted the ranks. Travel to\n Beadeaux to learn what you can from\n his commanding officer."},
      [50] = {n="What Price Loyalty",d="Client:\n Gentle Tiger (Entrance to Metalworks,\n Bastok Markets)\nSummary:\n Apprehended in Beaucedine after\n deserting his unit, Zeid awaits\n punishment in a dark cell of Benedikt\n Watchtower. Can nothing be done to\n save him from his fate? At his friend\n Gentle Tiger's behest, you travel to\n North Gustaberg to offer your aid."},
      [51] = {n="Songbirds in a Snowstorm",d="Client: Phillieulais S Dieuffon\n (Middle Gate, Southern San d'Oria)\nSummary:\n An immense beastman force seeks\n to strike at the sparsely manned\n rearguard of the northbound Allied\n expedition. You have been requested\n to join the Carmine Swallows on their\n mission to intercept the encroaching\n enemy host at Beaucedine."},
      [52] = {n="Blood of Heroes",d="Client: Excenmille\n (Xarcabard)\nSummary:\n Count Aurchiat lies dead, felled in\n an Orcish ambush that has left the\n Cardinal Stags severely weakened\n deep in the heart of enemy\n territory. The key to survival lies\n in a joint operation with the\n Iron Rams..."},
      [53] = {n="Sins of the Mothers",d="Client: Lehko Habhoka\n (Cobra Command, Windurst Waters)\nSummary: A state of emergency has\n been declared as the Shadow Lord's\n army marches inexorably toward the\n Federation. In the midst of the\n turmoil, Lehko Habhoka has summoned\n you to Heavens Tower with a task of\n particular import..."},
      [54] = {n="Howl from the Heavens",d="Client: Robel-Akbel (Windurst Waters)\nSummary:\n As the battered Federation forces\n prepare to defend their city from the\n approaching hordes, the inscrutable\n Robel-Akbel schemes in his dark\n chambers. What terrible secrets lie\n behind his mask? Deliver the magicite\n he seeks, and long-sought truths\n just may be revealed..."},
      [55] = {n="Succor to the Sidhe",r=1,d="Client: Callisto\n (Witchfire Glen, Grauberg)\nSummary:\n To save their ancestral home from\n a fate of destruction, the fey folk\n would entreat your aid."},
      [56] = {n="The Young and the Threadless",d="Client: Ponono\n (Windurst Waters)\nSummary:\n Unable to keep up with the\n overwhelming demand for her custom\n charm bracelets, the Windurstian\n clothcrafter Ponono has entrusted\n you with procuring a fresh supply of\n enchanted thread."},
      [57] = {n="Son and Father",d="Client: Exoroche (Eastgate,\n Southern San d'Oria)\nSummary:\n A child stands crying by San d'Oria\n Eastgate. Find his father for him."},
      [58] = {n="The Truth Lies Hid",d="Client: Volker (Entrance to Metalworks,\n Bastok Markets)\nSummary:\n Klara Bester, erstwhile captain of the\n Mythril Musketeers turned fugitive,\n has ensconced herself deep in the\n heart of Castle Zvahl. You must\n infiltrate the enemy stronghold with\n your comrades and uncover the truth\n behind your ex-commander's treachery."},
      [59] = {n="Bonds of Mythril",d="Client: Volker (Castle Zvahl Baileys)\nSummary:\n Fighting alongside ghastly demons one\n moment, risking her life to defend you\n the next... What is Captain Klara's\n true connection to the armies of\n shadow? Return to the site of your\n confrontation, that long sought-after\n truths may at last be revealed!"},
      [60] = {n="Chasing Shadows",d="Client: Rongelouts N Distaud\n (Auction House, Southern San d'Oria)\nSummary:\n Disturbing rumors of the late Count\n Aurchiat's return from the grave have\n stirred disquiet among the Cardinal\n Stags. Hasten to their Xarcabard\n encampment and uncover the truth\n behind the ominous tidings."},
      [61] = {n="Face of the Future",d="Client: Bostillette\n (Batallia Downs)\nSummary:\n Your latest encounter with Zogbog\n has led to you being hurled through\n time. No sooner had you awakened\n in present day Vana'diel than Iron\n Ram Engineer Bostillette appeared\n to entreat your aid. Make your way\n to base camp in the Jugner Forest\n if you would know more."},
      [62] = {n="Manifest Destiny",d="Client: Romaa Mihgo (Cobra Command,\n Windurst Waters)\nSummary:\n Having successfully turned back the \n Yagudo offensive, Lehko Habhoka\n and the Mithran mercenaries strike for\n Castle Oztroja to finish off their foe.\n The final conflict is nigh--report\n to the mercenary camp in the\n Meriphataud Mountains without delay!"},
      [63] = {n="At Journey's End",d="Client: Lehko Habhoka (Inner\n Chambers, Castle Oztroja)\nSummary:\n Lost souls scarred by the past strive\n toward their vision of a brighter\n future... When fates converge, a new\n chapter of history will unfold. Is this\n the end of their journey, or but a new\n beginning? Look to the starry heavens\n and your answer may be found..."},
      [64] = {n="Her Memories: Homecoming Queen",d="Mission Orders:\n Taken by nostalgia upon her return to\n present-day San d'Oria after a long\n absence, Lilisette decides to take a\n stroll down memory lane."},
      [65] = {n="Her Memories: Old Bean",d="Mission Orders:\n Rusty Anchor Pub owner Thierride bids\n you deliver his latest bean cuisine to\n old friend and Southern San d'Oria\n resident Amaura. In return for this\n favor, Thierride promises you his full\n cooperation."},
      [66] = {n="Her Memories: The Faux Pas",d="Mission Orders:\n The Elvaan gentleman you saw praying\n at the cathedral apparently seeks\n atonement for his callous treatment\n of a \"red-haired maiden.\"\n Could there be a connection between\n him and Lilisette? The friar informs\n you that the man might be found at\n Laborman's Way."},
      [67] = {n="Her Memories: Grave Resolve",d="Mission Orders:\n Despite no longer having memories of\n Lilisette, Halver's words spoken from\n his subconscious suggest that not all\n is lost. Could the Larzos of your\n reality possess knowledge that would\n aid your cause? Make haste to where\n he and you first met, at Sir Ragelise's\n gravestone."},
      [68] = {n="Her Memories: Operation Cupid",d="Mission Orders:\n Portia and Lilisette have skipped\n dance lessons and appear to be bound\n for Jeuno...but for what purpose?"},
      [69] = {n="Her Memories: Carnelian Footfalls",d="Mission Orders:\n Unbeknownst to you, Lilisette had\n sought admission into the Knights of\n the Iron Ram. Follow her footsteps\n to discover whether her attempt was\n successful."},
      [70] = {n="Her Memories: Azure Footfalls",d="Mission Orders:\n Unbeknownst to you, Lilisette had\n sought admission into the Seventh\n Cohors. Follow her footsteps to\n discover whether her attempt was\n successful."},
      [71] = {n="Her Memories: Verdure Footfalls",d="Mission Orders:\n Unbeknownst to you, Lilisette had\n sought admission into the Cobra\n Mercenaries. Follow her footsteps\n to discover whether her attempt\n was successful."},
      [72] = {n="Her Memories: Of Malign Maladies",d="Mission Orders:\n Lilisette had embarked on a\n frenetic journey to find a cure\n for Sir Ragelise's affliction.\n Has the passage of time seen\n the discovery of a remedy?"},
      [73] = {n="Champion of the Dawn",d="Client: Cait Sith???\n (Walk of Echoes)\nSummary:\n A familiar, enigmatic voice has asked\n you to travel to Ronfaure, Jugner\n Forest, and Beaucedine Glacier in the\n Shadowreign Era and gather latent\n energies present there."},
      [74] = {n="The Dawn Also Rises",r=1,d="Client: Cait Sith\n (Walk of Echoes)\nSummary:\n Challenging Cait Sith again requires\n another visit to either Ronfaure,\n Jugner Forest, or Beaucedine Glacier\n in the Shadowreign Era to gather a\n breath of dawn."},
      [75] = {n="A Forbidden Reunion",d="Client: Cait Sith\n (Walk of Echoes)\nSummary:\n Cait Sith has implored you to find a\n way to help the struggling Lilisette, for\n a cavernous maw has opened to the\n dark future. Go forth and ensure that\n the world does not fall."},
      [80] = {n="Guardian of the Void",d="Clients: Cait Sith, Kupofried\n (Pashhow Marshlands)\nSummary:\n At the behest of this enigmatic duo,\n you have sworn to protect Vana'diel\n from the Voidwalker menace.\n Seek out comrades in the fight, that\n you might send these interdimensional\n intruders back to the darkness\n whence they came!"},
      [81] = {n="Drafted by the Duchy",d="Mission Orders:\n You have been received an urgent\n call to arms from Voidwatch\n headquarters in Jeuno.\n Report promptly to the palace in\n Ru'Lude Gardens or the main gate\n in Sauromugue Champaign for a full\n briefing."},
      [82] = {n="Battle on a New Front",d="Mission Orders:\n You have been cleared to\n participate in the Jeuno region\n Voidwatch operation. Go forth and\n quell the Voidwalker menace!"},
      [83] = {n="VW Op. #126: Qufim Incursion",d="Mission Orders:\n The Voidwalker presence grows ever\n stronger at Qufim Island, Behemoth's\n Dominion, and Delkfutt's Tower. Lure\n out and eliminate hostiles to secure\n the area."},
      [84] = {n="A Cait Calls",d="Mission Orders:\n Cait Sith would speak to you about a\n matter of utmost importance. Make\n haste for the Pashhow Marshlands of\n the past and rendezvous with the\n ever-enigmatic feline."},
      [85] = {n="The Truth Is Out There",d="Mission Orders:\n The existence of another planar rift\n has been confirmed in the Walk of\n Echoes. Could this one hold the\n answers needed to quell the\n Voidwalker menace once and for all?\n Be ever vigilant, soldiers of the\n Voidwatch!"},
      [86] = {n="Re-Drafted by the Duchy",d="Mission Orders:\n Your presence has once again been\n requested at Voidwatch headquarters\n in Jeuno. Report promptly to the\n palace in Ru'Lude Gardens for further\n orders."},
      [87] = {n="A New Menace",d="Mission Orders:\n You have been authorized to\n participate in the latest Voidwatch\n effort in the greater three nations\n region. The Voidwalkers grow more\n formidable by the day--be ever\n vigilant!"},
      [88] = {n="No Rest for the Weary",d="Mission Orders:\n No sooner has one threat been\n quelled than another emerges. You\n have been granted a brief respite, but\n cannot help but feel concern at the\n state of the Voidwatch effort in the\n Crystal War era..."},
      [89] = {n="A World in Flux",d="Mission Orders:\n Little to your surprise, the Allied\n Nations of Crystal War-era Vana'diel\n are also at wit's end with the\n Voidwalker menace. Make your way to\n Vunkerl Inlet, Grauberg, and Fort\n Karugo-Narugo and dispatch any\n fiends that may emerge from the rifts."},
      [90] = {n="Between a Rock and Rift",d="Mission Orders:\n Could it be that the Walk of Echoes\n holds the key to the enigma that is\n the Voidwalker menace? With no word\n from Cait Sith or the mysterious\n moogle Kupofried, you decide to\n head to the Pashhow Marshlands\n rendezvous point to investigate..."},
      [91] = {n="A Farewell to Felines",d="Mission Orders:\n On the verge of unraveling the\n Voidwalker enigma, Kupofried suffered\n a shocking setback...the sudden\n disappearance of his feline cohort.\n What nefarious force whisked Cait\n Sith across the dimensional\n threshold? The plot ever thickens..."},
      [92] = {n="Third Tour of Duchy",d="Mission Orders:\n The Duchy has requested your\n presence yet again. Wherever have\n the Voidwalkers struck this time?\n In any event, make haste to the\n palace in Ru'Lude Gardens or the\n main gate in Sauromugue Champaign\n for further orders."},
      [93] = {n="Glimmer of Hope",d="Mission Orders:\n Rumors tell of crystalline stones\n obtainable from the corpses of fallen\n Voidwalkers. Should you happen upon\n any, seek out Kupofried in the\n Pashhow Marshlands for answers."},
      [94] = {n="Brace for the Unknown",d="Mission Orders:\n The first contact has been made with\n Cait Sith since she disappeared\n through a distortion in the Walk of\n Echoes, but Kupofried's tone hints\n that trying times lie ahead. Could the\n truth surrounding these planar rift\n appearances finally come to light!?"},
      [95] = {n="Provenance",d="Mission Orders:\n A place from which all radiance\n once shone brightly forth now dimly\n flickers on the brink of existence...\n It is here that the source of\n Vana'diel's suffering dwells, say\n the now multifarious caits."},
      [96] = {n="Crystal Guardian",d="Mission Orders:\n You have discovered that Vana'diel's\n plight can be traced back to a being\n that guards the fabled stone oft\n mentioned in songs of yore. Now all\n that remains is to lay it to rest."},
      [97] = {n="Endings and Beginnings",d="Mission Orders:\n As the caits tell it, Provenance is not\n the destination, but yet another point\n of departure. While the proverbial\n book may have been shut on this tale,\n it also signals the start of a new one."},
      [98] = {n="Ad Infinitum",d="Mission Orders:\n Far from being the center of\n destruction, Provenance is the source\n from which worlds of possibility shine\n forth. For those who have survived\n their trials in this ancestral land, the\n true adventure has only just begun."},
    }},
    abyssea = { name = "Abyssea", ids = {
      [0] = {n="Catering Capers",d="Client: Regine (Base Camp,\n Abyssea - La Theine)\nSummary:\n Regine has taken a wound and is\n unable to harvest and deliver the\n requested three plateau chestnuts\n to her sister Rugiette at the central\n encampment. You must complete the\n task in her stead, lest the people\n go without."},
      [1] = {n="Gift of Light",d="Client: Amaura (Base Camp,\n Abyssea - La Theine)\nSummary:\n Amaura has exhausted her supply\n of the key ingredient required to\n concoct a vital medication. Find\n and bring her the sunbeam fragment\n she needs before the survivors fall\n to illness!"},
      [2] = {n="Fear of the Dark III",d="Client: Secodiand (Base Camp,\n Abyssea - La Theine)\nSummary:\n Fetch three clionid wings."},
      [3] = {n="An Eye for Revenge",d="Client: Curilla (Base Camp,\n Abyssea - La Theine)\nSummary:\n As retribution, Curilla demands the\n eyeball of Lugarhoo, the vile gnole\n that took her left eye in a vicious\n attack."},
      [4] = {n="Unbreak His Heart",d="Client: Joulet (Central Encampment,\n Abyssea - La Theine)\nSummary:\n A fishing rod lies broken. You must\n repair and deliver it to Gallijaux at\n the southeastern encampment lest\n the survivors go hungry."},
      [5] = {n="Explosive Endeavors",d="Client: Fontoumant (Central Encampment,\n Abyssea - La Theine)\nSummary:\n Swarms of monsters have been\n observed emerging from ominous\n crevices in the valley floor.\n Neutralize them with experimental\n anti-Abyssean grenades."},
      [6] = {n="The Angling Armorer",d="Client: Exoroche (Central Encampment,\n Abyssea - La Theine)\nSummary:\n With no end in sight in the fight\n against the Abyssean hordes, keeping\n soldiers outfitted in battle-worthy\n gear has become a grave concern.\n Could the ponds of La Theine yield\n old but usable equipment?"},
      [7] = {n="Water of Life",d="Client: Miageau (Southeastern\n Encampment, Abyssea - La Theine)\nSummary:\n La Theine's water sources have been\n found to be contaminated! Miageau\n has entrusted you with vials of\n purification agent to cleanse each\n of the plateau's four ponds."},
      [8] = {n="Out of Touch",d="Client: Glenne (Southeastern\n Encampment, Abyssea - La Theine)\nSummary:\n Glenne has lost the means to\n contact her husband who is out\n on patrol. Find her husband afield\n and deliver a new linkpearl to him."},
      [9] = {n="Lost Memories",d="Client: Halver (Southeastern\n Encampment, Abyssea - La Theine)\nSummary:\n In order to brew a medicine that will\n restore Curilla's memory, Halver\n requires that you procure two\n lambent scales."},
      [10] = {n="Hope Blooms on the Battlefield",d="Client: Ayame (Central Command,\n Abyssea - Konschtat)\nSummary:\n The searing ward that serves as the\n last line of defense against the fell\n hordes of the highlands has suffered\n critical damage in an attack. Procure\n repair materials from throughout the\n base and deliver them to the engineer\n Raibaht before the fiends return!"},
      [11] = {n="Of Malnourished Martellos",d="Client: Raibaht (Central Command,\n Abyssea - Konschtat)\nSummary:\n The engineer overseeing martello\n maintenance has tasked you with\n replenishing the energy store of one\n of these curious magical structures.\n Acquire a supply of fuel, deposit it in\n the camp's martello, and report back\n when the operation is complete."},
      [12] = {n="Rose on the Heath",d="Client: Ayame (Central Command,\n Abyssea - Konschtat)\nSummary: The latest incursion of\n Abyssean fiends has left shattered\n linkshells in its wake, severing\n precious lines of communication\n between Captain Ayame and her\n comrades afield. Deliver three\n linkpearls, one each to Captains\n Rashid, Argus, and Helga, before an ill\n fate befalls these brave warriors of\n the resistance!"},
      [13] = {n="Full-of-Himself Alchemist",r=1,d="Client: Julio (Camp Courage,\n Abyssea - Konschtat)\nSummary: Self-serving and abrasive\n though he may be, the alchemist\n Julio's estimable potion-brewing skills\n are serving the embattled resistance\n well. Supply him with three purple\n polypores, that he may prepare a new\n batch of his prized product for the\n wounded troops."},
      [14] = {n="The Walking Wounded",r=1,d="Client: Rashid (Camp Courage,\n Abyssea - Konschtat)\nSummary:\n Five of Captain Rashid's best soldiers\n are battling bravely despite grievous\n wounds. Provide each of them with a\n soothing potion to restore them to\n fighting trim."},
      [15] = {n="Shady Business Redux",r=1,d="Client: Talib (Camp Hope,\n Abyssea - Konschtat)\nSummary:\n The boss of the storehouse traders\n has made you a business proposition\n you couldn't refuse. Bring him four\n limule pincers to receive a handsome\n reward."},
      [16] = {n="Addled Mind, Undying Dreams",d="Client: Silver Owl (Camp Hope,\n Abyssea - Konschtat)\nSummary:\n A guardsman of the former Republic,\n now scarred in mind and body, seeks\n your aid in carrying out a scheme he\n believes key to the survival of the\n resistance. Scour the bleak highlands\n in search of supplies lost during the\n raid of Bastok."},
      [17] = {n="The Soul of the Matter",r=1,d="Client: Cleades (Camp Vigilance,\n Abyssea - Konschtat)\nSummary:\n A reconnaissance expert has taken\n you under his wing to tutor you in the\n arcane art of soulgauging. Venture\n afield with your Soulgauger SGR-1\n and collect intelligence on the\n notorious fiends aprowl in the vicinity."},
      [18] = {n="Secret Agent Man",d="Client: Helga (Camp Vigilance,\n Abyssea - Konschtat)\nSummary: Captain Helga fears for the\n safety of fellow officer and covert\n ops specialist Naji, who has not\n returned from his latest mission. The\n loss of this elite operative would be a\n near-fatal blow to the resistance. You\n must track him down with all haste!"},
      [19] = {n="Playing Paparazzi",r=1,d="Client: Naji (Afield,\n Abyssea - Konschtat)\nSummary:\n Naji has grudgingly accepted you as\n his assistant, and entrusted you with\n continuing his work while his wounds\n keep him out of commission. Only\n close range shots of the most\n formidable foes to terrorize the\n highlands will suffice!"},
      [20] = {n="His Box, His Beloved",d="Client: Apururu (Central Encampment,\n Abyssea - Tahrongi)\nSummary:\n Apururu lacks for the starfruit needed\n to construct Cardians to protect her\n embattled countrymen. Travel to the\n northwestern encampment and procure\n one from the supply of the eccentric\n Kopuro-Popuro."},
      [21] = {n="Weapons, Not Worries",r=1,d="Client: Peshi Yohnts (Western\n Encampment, Abyssea - Tahrongi)\nSummary:\n A down-in-the-dumps artisan,\n seemingly too disheartened to take\n action herself, needs you to retrieve\n supplies for weaponcrafting. The\n hardened bone harvestable in the area\n should serve to raise her spirits."},
      [22] = {n="Cleansing the Canyon",d="Client: Kupipi (Central Encampment,\n Abyssea - Tahrongi)\nSummary:\n Fearsome fiends prowl the path to\n the western encampment, cutting off\n valuable supply routes and placing the\n survivors' well-being in peril. At\n Kupipi's behest, thin the ranks of\n these foes and return with three\n sanguinets as proof of the deed."},
      [23] = {n="Savory Salvation",r=1,d="Client: Piketo-Puketo (Western\n Encampment, Abyssea - Tahrongi)\nSummary:\n A culinarian with serious delusions of\n grandeur sees himself as the savior of\n his nation's people. Employ the\n fertilizer he's given you on a suitable\n tree and bring back anything edible\n that may grow."},
      [24] = {n="Bringing Down the Mountain",d="Client: Diegai (North of Central\n Encampment, Abyssea - Tahrongi)\nSummary:\n A young Galkan child fears for the\n safety and sanity of his friend and\n guardian. Seek out Baladanzo, who\n claims to have heard voices coming\n from the far side of an impassable\n rockslide..."},
      [25] = {n="A Sterling Specimen",r=1,d="Client: Ohbiru-Dohbiru (Central\n Encampment, Abyssea - Tahrongi)\nSummary:\n Having redirected his efforts to the\n study of the Abyssean ecosystem, a\n researcher from the Rhinostery seeks\n a live sample of a mutant strain of\n mandragora for hands-on examination.\n Speak with Kenapa-Keppa outside and\n make your contribution to science!"},
      [26] = {n="For Love of a Daughter",r=1,d="Client: Baha Mannohl (Northern\n Encampment, Abyssea - Tahrongi)\nSummary:\n A distraught Mithran mother seeks\n your help in finding a cure for her\n fever-stricken daughter. The\n substance she requires is a rare liquid\n said to be exuded by cacti of the\n canyon, but only after dark..."},
      [27] = {n="Sisters in Crime",r=1,d="Client: Cha Lebagta and Bopa Greso\n (Mountain Path, Abyssea - Tahrongi)\nSummary:\n Holding out hope that their\n disreputable band may yet be reunited,\n the two lackeys of the Cat Burglar\n have co-opted you to spread the\n news of their survival. Affix the\n ridiculous posters they've given you\n to the signposts in the canyon."},
      [28] = {n="When Good Cardians Go Bad",r=1,d="Client: Apururu (Central Encampment,\n Abyssea - Tahrongi)\nSummary:\n Apururu's Cardians now guard each\n encampment, but word has it that\n not all of them are functioning\n optimally. Speak to the Cardians at\n each location and report back on any\n glitches you may have detected."},
      [29] = {n="Tangling with Tongue-twisters",d="Client: Kupipi (Central Encampment,\n Abyssea - Tahrongi)\nSummary:\n Cuelebre. Adze. Minhocao. Chukwa.\n Mictlantecuhtli. No, this isn't the\n Federation spelling bee--these are the\n names of the five most formidable\n enemies plaguing the canyon. Slay\n one and bring back proof of your\n triumph."},
      [30] = {n="A Ward to End All Wards",r=1,d="Client: Belgidiveau (Base Camp,\n Abyssea - Vunkerl)\nSummary: \n The searing ward maintained by the\n brilliant Belgidiveau could not\n possibly be malfunctioning!\n Nevertheless, he requires your aid to\n perform a routine test. Deliver a body\n part of an Abyssean fiend to your\n client, and confirm that his remarkable\n creation is still performing optimally."},
      [31] = {n="The Boxwatcher's Behest",r=1,d="Client: Deraquien (Central Encampment,\n Abyssea - Vunkerl)\nSummary:\n Supplies must be delivered on foot to\n the newly constructed outpost, and\n the sluggardly Deraquien is clearly not\n up to the task. Go in his stead and\n deliver the goods to Captain\n Elmemague."},
      [32] = {n="His Bridge, His Beloved",r=1,d="Client: Cheupirudaux (Western\n Encampment, Abyssea - Vunkerl)\nSummary:\n The bridges across the inlet are in a\n state of dire disrepair. Go repair\n them, that a sensitive woodworker's\n heart may again rest easy."},
      [33] = {n="Bad Communication",r=1,d="Client: Ferdechiond (Outpost,\n Abyssea - Vunkerl)\nSummary:\n The linkpearls planted afield to gather\n intelligence on the Abyssean hordes\n are not functioning as intended, and\n Ferdechiond is displeased. Investigate\n the situation with all speed!"},
      [34] = {n="Family Ties",d="Client: Teigero-Bangero (Western\n Encampment, Abyssea - Vunkerl)\nSummary:\n A devoted Tarutaru father was\n separated from wife and child in their\n flight from Jeuno. Deliver his letter,\n that this loving family may be\n reunited once more."},
      [35] = {n="Aqua Pura",d="Client: High Bear (Outpost,\n Abyssea - Vunkerl)\nSummary:\n An enthusiastic researcher is on the\n verge of a discovery that might\n restore potable water to the inlet.\n Retrieve plant samples from the\n vicinity of the ponds, that his labors\n might at long last bear fruit."},
      [36] = {n="Aqua Puraga",r=1,d="Client: High Bear (Outpost,\n Abyssea - Vunkerl)\nSummary:\n An enthusiastic researcher is on the\n verge of a discovery that might\n restore potable water to the inlet...\n for certain this time! Retrieve plant\n samples from the vicinity of the\n ponds, that his labors might at long\n last bear fruit."},
      [37] = {n="Whither the Whisker",d="Client: Rahal (Central Encampment,\n Abyssea - Vunkerl)\nSummary:\n A savage pack of fiends terrorizes\n Vunkerl, their whisker of power and\n omniscience confounding the bravest\n attempts of a celebrated San d'Orian\n hero to secure the safety of his men.\n It falls to you to sever and retrieve\n this Samsonian strand!"},
      [38] = {n="Scattered Shells, Scattered Mind",r=1,d="Client: Aladoverre (Western\n Encampment, Abyssea - Vunkerl)\nSummary:\n The resistance's supply of linkshells\n has dwindled to dangerously\n low levels. Retrieve three from the\n field before your addle-minded client\n forgets just what exactly he asked\n you for."},
      [39] = {n="Wayward Wares",d="Client: Chapi Galepilai (Base Camp,\n Abyssea - Attohwa)\nSummary:\n A shipment of essential supplies\n intended for the Resistance outpost\n has been intercepted. Recover the\n scattered materials and deliver them\n to their intended destination."},
      [40] = {n="Looking for Lookouts",r=1,d="Client: Colti (Field Encampment,\n Abyssea - Attohwa)\nSummary:\n A regiment of scouts has gone astray\n while on a mission to survey\n Parradamo Tor. Deliver linkpearls and\n emergency rations to the hapless crew\n and restore communication between\n them and their flustered commanding\n officer."},
      [41] = {n="Flown the Coop",r=1,d="Client: Brutus (Field Encampment,\n Abyssea - Attohwa)\nSummary:\n One of the precious few chocobos\n who survived the flight from Jeuno\n has escaped from the stables. Track\n the bird, lure it out with gysahl\n greens, and capture it to return to\n safe captivity."},
      [42] = {n="Threadbare Tribulations",r=1,d="Client: Ponono (Field Encampment,\n Abyssea - Attohwa)\nSummary:\n A tailor seeks to raise morale by\n mending the garments of the soldiers,\n but lacks for the thread she needs to\n perform the task. Bring her the three\n amoeban pseudopods that she insists\n will serve as an ideal substitute."},
      [43] = {n="An Offer You Can't Refuse",r=1,d="Client: Garnev (Resistance Outpost,\n Abyssea - Attohwa)\nSummary:\n Your client has a deal for you:\n procure a piece of malachite from one\n of the sturdy pyxides, and he'll make\n it worth your while. What does he\n need it for? You're better off not\n knowing."},
      [44] = {n="Something in the Air",d="Client: Yoran-Oran (Base Camp,\n Abyssea - Attohwa)\nSummary:\n The Professor is concerned about\n the air quality, and has hypothesized\n that the source of the pollution\n lies to the west. Go investigate,\n and bring back the tangible evidence\n that your client needs to formulate a\n solution to the crisis."},
      [45] = {n="An Acrididaen Anodyne",r=1,d="Client: Yoran-Oran (Base Camp,\n Abyssea - Attohwa)\nSummary:\n Yoran-Oran has figured out a method\n that will stop the gasponia from\n giving off its noxious fumes, but he\n requires an elusive insect known as a\n rockhopper to prepare the formula."},
      [46] = {n="Hazy Prospects",d="Client: Harith (Base Camp,\n Abyssea - Attohwa)\nSummary:\n An astute alchemist has concluded\n that the miasmas seeping up through\n fissures in the ground are contributing\n to the tainted air. Follow the recipe\n he entrusted to you to synthesize the\n counteragent, test it on a miasma,\n then report back with your findings."},
      [47] = {n="For Want of a Pot",d="Client: Naruru (Base Camp,\n Abyssea - Attohwa)\nSummary:\n You must retrieve Naruru's favorite\n stewpot from the airship wreckage so\n that she can cook up a batch of\n piping hot stew from...no, for\n her fellow survivors!"},
      [48] = {n="Missing in Action",d="Client: Iron Eater (Base Camp,\n Abyssea - Misareaux)\nSummary:\n A fierce attack by the Abyssean\n hordes has left some members of\n Iron Eater's regiment stranded afield.\n Without the means to regain contact\n nor the manpower to dispatch a search\n party, a lone hero must strike out into\n the wilderness and find them. That\n hero is you."},
      [49] = {n="I Dream of Flowers",d="Client: Goraow (Second Encampment,\n Abyssea - Misareaux)\nSummary:\n Perpetual pessimist Goraow wishes he\n had flowers to offer to the grave of\n his fallen brethren..."},
      [50] = {n="Destiny Odyssey",d="Client: Goraow (Second Encampment,\n Abyssea - Misareaux)\nSummary:\n There can be no doubt. You are the\n hero destined to end Gukumatz's reign\n of terror. Slay this maniacal fiend and\n claim a body part as a trophy, that\n the souls of Goraow's fallen brethren\n may know true peace."},
      [51] = {n="Unidentified Research Object",r=1,d="Client: Yurim (Base Camp,\n Abyssea - Misareaux)\nSummary:\n Yurim requires a certain object in\n order to continue her research on\n Abyssean lifeforms, but is experiencing\n difficulties remembering its name..."},
      [52] = {n="Cookbook of Hope Restoring",r=1,d="Client: Jonette (First Encampment,\n Abyssea - Misareaux)\nSummary:\n Jonette's dream is to restore hope to\n the community of survivors by serving\n them an array of scrumptious dishes.\n However, she dropped the cookbook\n needed to fulfill that dream when\n fleeing from monsters. Be a dear and\n find it for her."},
      [53] = {n="Smoke over the Coast",r=1,d="Client: Hungry Wolf (First Encampment,\n Abyssea - Misareaux)\nSummary:\n Hungry Wolf hungers for meat! Hurry,\n before he transforms into a scrawny\n Hume before your very eyes!"},
      [54] = {n="Soil and Green",r=1,d="Client: Sieglinde (Base Camp,\n Abyssea - Misareaux)\nSummary:\n Sieglinde the alchemist is investigating\n soil quality along the coast, and has\n custom-designed a contraption for\n that purpose. Take the aptly named\n \"mineral gauge for dummies,\" and\n thrust it into a likely spot of earth\n by a tree."},
      [55] = {n="Dropping the Bomb",r=1,d="Client: Veit (Second Encampment,\n Abyssea - Misareaux)\nSummary:\n Caskets containing gunpowder intended\n for a critical blasting operation have\n been lost in transit. With his soldiers\n apparently a bunch of hopeless\n cravens, Veit requires that you\n retrieve the caskets, which were last\n seen being dumped into the river."},
      [56] = {n="Wanted: Medical Supplies",r=1,d="Client: Yasuji (First Encampment,\n Abyssea - Misareaux)\nSummary:\n The struggle against the Abyssean\n invaders grows ever fierce. To do\n your part, you must bring Yasuji any\n medical supplies you find within\n sturdy pyxides. For make benefit\n the great resistance effort, let us\n together!"},
      [57] = {n="Voices from Beyond",d="Client: Rukususu (Second Encampment,\n Abyssea - Grauberg)\nSummary:\n Rumors abound of ghosts haunting the\n mountains to the northwest. Rukususu\n requires that you bring irrefutable\n proof to substantiate this disturbing\n tale."},
      [58] = {n="Benevolence Lost",r=1,d="Client: Rukususu (Second Encampment,\n Abyssea - Grauberg)\nSummary:\n Water contamination has caused the\n pixies of Witchfire Glen to turn\n malevolent. By proliferating certain\n components in the water, however,\n it should be possible to restore the\n noble creatures to their former\n benevolent selves."},
      [59] = {n="Brugaire's Ambition",r=1,d="Client: Brugaire\n (Abyssea - Grauberg)\nSummary:\n At Brugaire's behest, you must\n confront and defeat the notorious\n Teekesselchen with the aid of\n prismatic elixir, the newly invented\n wonder draught."},
      [60] = {n="Chocobo Panic",r=1,d="Client: Kuoh Rhel\n (Abyssea - Grauberg)\nSummary:\n Kuoh Rhel's pack chocobo refuses to\n eat anything she feeds it, and grows\n more sickly by the day. Is there\n nothing under this accursed red sky\n that would entice the creature?"},
      [61] = {n="The Egg Enthusiast",r=1,d="Client: Ranpi-Monpi (Third Encampment,\n Abyssea - Grauberg)\nSummary:\n Ranpi-Monpi, culinarian extraordinaire,\n requires that you bring a fresh wivre\n egg from within the nesting grounds.\n Take extra care that the fragile egg\n is not damaged during transportation."},
      [62] = {n="Getting Lucky",r=1,d="Client: Kurou-Morou \n(Abyssea - Grauberg)\nSummary:\n Take your specified lucky item to\n the designated lucky spot, and good\n fortune will surely visit you...if\n Kurou-Morou the Magnificentaru\n speaks true."},
      [63] = {n="Her Father's Legacy",r=1,d="Client: Cornelia (First Encampment,\n Abyssea - Grauberg)\nSummary:\n For the survival of all those who call\n Grauberg home, Cornelia has assigned\n you the task of vanquishing the dread\n wyverns invariably seen in the company\n of the hydra Alfard."},
      [64] = {n="The Mysterious Head Patrol",d="Client: Eight of Hearts\n (Abyssea - Grauberg)\nSummary:\n Who is the mystery person who\n patrols the head of Eight of Hearts?\n Find a vertically challenged individual\n attired in yellow who possesses a\n silver pocket watch, and you will find\n the answer."},
      [65] = {n="Master Missing, Master Missed",d="Client: Eight of Clubs \n (Abyssea - Grauberg)\nSummary:\n Eight of Clubs is gravely concerned\n for his master, whose return is long\n overdue. Travel to the location where\n the man was headed, that you might\n glean knowledge to set the Cardian's\n mind at rest."},
      [66] = {n="The Perils of Kororo",d="Client: Kororo \n (Abyssea - Grauberg)\nSummary:\n Caring young Kororo cannot help but\n worry about Eight of Clubs' state of\n mind. Be a dear and check up on the\n Cardian in her stead."},
      [67] = {n="Let There Be Light",r=1,d="Client: Zauko (First Outpost,\n Abyssea - Uleguerand)\nSummary:\n Brother Zauko has entrusted you with\n a delivery of coal for the\n encampments, that the Divine Light\n of the Torch shall illuminate the\n realm now and forever."},
      [68] = {n="Look Out Below",r=1,d="Client: Baldric (Second Outpost,\n Abyssea - Uleguerand)\nSummary:\n Baldric seeks to put an end to the\n avalanches that plague the survivors\n by triggering small explosions to\n disperse accumulated snow. Assist him\n in an experiment to determine the\n optimal quantity of firesand for the\n task."},
      [69] = {n="Home, Home on the Range",d="Client: Moogle (Third Outpost,\n Abyssea - Uleguerand)\nSummary:\n Bereft of hearth and home but not\n heart and hope, a beleaguered moogle\n has asked you to help him rebuild a\n small piece of his glory days."},
      [70] = {n="Imperial Espionage",d="Client: Tyamah (Third Outpost,\n Abyssea - Uleguerand)\nSummary:\n A curious stranger from a distant land\n has tasked you with gathering\n information on the current state of\n the four nations of Altana."},
      [71] = {n="Imperial Espionage II",d="Client: Tyamah (Third Outpost,\n Abyssea - Uleguerand)\nSummary:\n Stranded far from home and looking\n considerably worse for the wear,\n Tyamah has called upon your services\n again. Your mission, if you choose to\n accept it: use a soulgauger to gather\n intel on unfamiliar Abyssean fiends."},
      [72] = {n="Boreal Blossoms",r=1,d="Client: Oruga (First Outpost,\n Abyssea - Uleguerand)\nSummary:\n Having run out of a vital salve, Oruga\n has sent you in search of a rare\n flower that blooms in wintry climes.\n Three blossoms are required to\n extract a sufficient quantity of the\n reagent."},
      [73] = {n="Brothers in Arms",d="Client: Zazarg (Third Outpost,\n Abyssea - Uleguerand)\nSummary:\n A vital linkpearl purloined by the vile\n Blanga, Zazarg lacks the means to\n contact his comrades. Retrieve the\n pearl, that he might confirm the\n safety of his countrymen."},
      [74] = {n="Scouts Astray",r=1,d="Client: Rondipur (Base Camp,\n Abyssea - Uleguerand)\nSummary:\n Rondipur's incompetent underlings\n have managed to get themselves lost\n on a routine scouting mission. Find\n them before they meet an untimely\n end."},
      [75] = {n="Frozen Flame Redux",r=1,d="Client: Guilboire (Third Outpost,\n Abyssea - Uleguerand)\nSummary:\n Following in the footsteps of his\n Crystal War veteran father, the\n enterprising Guilboire seeks to\n harness the power of snolls to strike\n back at the hordes. Travel to the test\n site and assist with data collection."},
      [76] = {n="Slip Slidin' Away",r=1,d="Client: Michilca (Base Camp,\n Abyssea - Uleguerand)\nSummary:\n The Resistance seeks to send a strike\n team into the bowels of Thousandfall\n Ridge, a confirmed breeding pit for\n the hordes. Help keep Michilca's men\n on course as they execute their\n hazardous approach."},
      [77] = {n="Classrooms Without Borders",r=1,d="Client: Moreno-Toeno (Base Camp,\n Abyssea - Altepa)\nSummary:\n His classroom may be lost, but\n Moreno-Toeno is determined to\n educate the next generation here in\n the wastelands. Bring him three\n manigordo fangs so he can conduct\n a science class for his pupils."},
      [78] = {n="The Secret Ingredient",r=1,d="Client: Nogelle (Base Camp,\n Abyssea - Altepa)\nSummary:\n Bean chef extraordinaire Nogelle lost\n her entire supply of Lufet lake salt in\n her escape from San d'Oria. Seek out\n a substitute ingredient, that she might\n put fire in the bellies of her fellow\n survivors with a piping pot of bean\n stew."},
      [79] = {n="Help Not Wanted",r=1,d="Client: Ken (Second Outpost,\n Abyssea - Altepa)\nSummary:\n A sniveling brat with an inferiority\n complex about never having graduated\n from military academy is too prideful\n to admit that he can't complete his\n mission on his own. Procure soul\n prints of the fiercest Abysseans for\n the ungrateful whelp."},
      [80] = {n="The Titus Touch",d="Client: Titus (Third Outpost,\n Abyssea - Altepa)\n Summary: Alchemical genius Titus is\n at it again, his latest masterful\n creation being...ink. Deliver this\n practical (if not particularly exciting)\n product to medic team leader Chumimi\n at the first outpost, that she might\n complete her report."},
      [81] = {n="Slacking Subordinates",r=1,d="Client: Chumimi (First Outpost,\n Abyssea - Altepa)\nSummary:\n Chumimi's good-for-nothing assistants\n Chemioue, Biggorf, and Tapoh Lihzeh\n still haven't done their homework.\n Hunt them down and relay their\n findings to Chumimi by any means\n necessary."},
      [82] = {n="Motherly Love",d="Client: Alisa (Fourth Outpost,\n Abyssea - Altepa)\nSummary:\n Alisa's dear husband Zacc and lovely\n daughter Enu have not returned from\n their little stroll outside the searing\n ward. Whatever could be keeping\n them...?"},
      [83] = {n="Look to the Sky",d="Client: Alisa (Fourth Outpost,\n Abyssea - Altepa)\nSummary:\n Finally at peace with the loss of her\n family, Alisa wishes you to bury her\n daughter Enu's favorite pendant in a\n spot as close to the sky as you can\n find. That's where the little girl\n would have wanted it..."},
      [84] = {n="The Unmarked Tomb",d="Client: Oiheaurese (First Outpost,\n Abyssea - Altepa)\nSummary:\n Doctor Oiheaurese, an authority on\n wyverns, has heard reports that a\n living wyvern egg lies buried beneath\n the shifting sands of Altepa. Can this\n elusive treasure be found...?"},
      [85] = {n="Proof of the Lion",r=1,d="Client: Excenmille (Third Outpost,\n Abyssea - Altepa)\nSummary:\n Excenmille, hero of the Crystal War,\n is disheartened by the lack of\n fortitude shown by his fellow\n survivors. Show to him that you are\n different by slaying the dread waugyl\n and returning with proof of your\n triumph."},
      [86] = {n="Brygid the Stylist Strikes Back",r=1,d="Client: Brygid (Fourth Outpost,\n Abyssea - Altepa)\nSummary:\n Brygid, the self-professed stylist\n extraordinaire, has given you some\n fashion advice. Her pull-no-punches\n style of fashion critiques seems\n somehow familiar..."},
      [87] = {n="Dominion Op #01 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n sand sweepers to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [88] = {n="Dominion Op #02 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n surveyors to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [89] = {n="Dominion Op #03 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n bonfires to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [90] = {n="Dominion Op #04 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n dune manticores to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [91] = {n="Dominion Op #05 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n manigordos to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [92] = {n="Dominion Op #06 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n camelopardalii to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [93] = {n="Dominion Op #07 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n desert puks to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [94] = {n="Dominion Op #08 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n ergdrakes to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [95] = {n="Dominion Op #09 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n dune cockatrices to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [96] = {n="Dominion Op #10 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n gastornes to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [97] = {n="Dominion Op #11 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n nannakolas to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [98] = {n="Dominion Op #12 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n akrabs to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [99] = {n="Dominion Op #13 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n fear deargs to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [100] = {n="Dominion Op #14 (Altepa)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Altepa)\nSummary:\n Slay a prescribed quota of\n barrens treants to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [101] = {n="Dominion Op #01 (Uleguerand)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Uleguerand)\nSummary:\n Slay a prescribed quota of\n mechanical menaces to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
