      [124] = {n="Ward Warden I (Attohwa)",r=1,d="Client: Resistance Sapper (Central\n Outpost, Abyssea - Attohwa)\nSummary:\n It is imperative that the pulse martello\n and the clone wards are kept in prime\n condition. This operation requires you\n to transport the necessary repair\n materials from the stockpile, using the\n enchanted sack provided. Be mindful\n that the sack does not rupture in the\n process."},
      [125] = {n="Ward Warden I (Misareaux)",r=1,d="Client: Resistance Sapper (Central\n Outpost, Abyssea - Misareaux)\nSummary:\n It is imperative that the pulse martello\n and the clone wards are kept in prime\n condition. This operation requires you\n to transport the necessary repair\n materials from the stockpile, using the\n enchanted sack provided. Be mindful\n that the sack does not rupture in the\n process."},
