      [142] = {n="Refuel and Replenish (La Theine)",r=1,d="Client: Machine Outfitter (Base Camp\n Abyssea - La Theine)\nSummary:\n Regular replenishment of the martellos\n located throughout the La Theine\n Plateau is vital to the resistance\n effort in this area. Refuel a martello\n and return the empty vat to the\n machine outfitter when your task is\n complete."},
