      [159] = {n="A Mightier Martello (Grauberg)",r=1,d="Client: Machine Outfitter (Base Camp,\n Abyssea - Grauberg)\nSummary:\n Upgrading the fuel capacity of the\n martellos in Grauberg will mean less\n frequent replenishment runs, easing\n the burden on Resistance troops in \n the area. Install a fuel reservoir in a\n martello, and return the excess parts\n to the machine outfitter when the\n job is done."},
      [160] = {n="A Journey Begins",d="How is it possible that no one else\n noticed the mysterious flash of light\n that lit up the skies of Port Jeuno?\n A man calling himself Joachim claims\n to know the answer..."},
      [161] = {n="The Truth Beckons",d="Client: Joachim\n (Port Jeuno)\nSummary:\n What is this phenomenon called\n \"noise\" of which Joachim\n speaks? If you would learn the\n truth, take the traverser stone\n and visit a cavernous maw that\n has been freed from its frozen\n state."},
      [162] = {n="Dawn of Death",d="Client: Joachim\n (Port Jeuno)\nSummary:\n Abyssea, a parallel world eerily\n similar yet deathly different\n from Vana'diel...\n What terrible cataclysm could have\n befallen this realm? Overhead, the\n sanguine sky is an ever-present\n portent of looming destruction..."},
      [163] = {n="A Goldstruck Gigas",d="Client: Ragemont\n (Cavernous Maw, La Theine Plateau)\nSummary:\n To restore hope to those who struggle\n for survival in Abyssea - La Theine,\n you must vanquish a fearsome Gigas\n who never leaves home without his\n golden helm."},
      [164] = {n="To Paste a Peiste",d="Client: Norrah\n (Cavernous Maw, Konschtat Highlands)\nSummary:\n A grossly oversized, mutated\n subspecies of peiste has been\n wreaking havoc upon the folk of\n Abyssea - Konschtat. Remove the\n fangs of this foul fiend, that\n tomorrow might be a better day."},
      [165] = {n="Megadrile Menace",d="Client: Kocchi-Arocchi\n (Cavernous Maw, Tahrongi Canyon)\nSummary:\n A giant worm thought long extinct\n has reemerged in Abyssea - Tahrongi,\n and now terrorizes those who have\n taken refuge in the canyon. Could\n this gargantuan beast be causing the\n recent destabilization of the boundary\n between worlds?"},
      [166] = {n="The Forbidden Frontier",d="Client: Joachim\n (Port Jeuno)\nSummary:\n Fierce battles rage across the\n disfigured landscape of Abyssea.\n Will you be the glimmer of hope\n for the survival of mankind?"},
      [167] = {n="First Contact",d="Client: Joachim\n (Port Jeuno)\nSummary:\n At Joachim's behest, you must meet\n with a mystery man whose identity\n cannot yet be disclosed. Make your\n way to the stone circle in the La\n Theine Plateau at a time between\n dusk and dawn."},
      [168] = {n="An Officer and a Pirate",d="Client: Gilgamesh\n (La Theine Plateau)\nSummary:\n The mystery man turned out to be an\n old pirate called Gilgamesh, sent by\n yet another mystery person to measure\n your suitability. What could be this\n \"truth\" of which he speaks?\n Meanwhile, events beyond the grasp\n of mortals are being set in motion..."},
      [169] = {n="Heart of Madness",d="Client: Joachim\n (Port Jeuno)\nSummary:\n You are the ray of hope for the\n people of Abyssea. Soldier on, if\n you would cast your light upon the\n truth which lies hidden within the\n depths of madness."},
      [170] = {n="Tenuous Existence",d="Client: Joachim\n (Port Jeuno)\nSummary:\n Gilgamesh wishes to speak with you\n again, most likely regarding some\n grave matter. As before, make your\n way to the stone circle in the La\n Theine Plateau at a time between\n dusk and dawn."},
      [171] = {n="Champions of Abyssea",d="Client: Joachim\n (Port Jeuno)\nSummary:\n Gilgamesh has brought you word of\n an unsettling phenomenon that has\n been observed the realm over. What\n could be causing this lattice-shaped\n breakdown of the land? The secret of\n this world of darkness will soon be\n revealed..."},
      [172] = {n="The Beast of Bastore",d="Client: Moniquaurie\n (Cavernous Maw, Jugner Forest)\nSummary:\n A gargantuan beast identified as a\n ruszor has been terrorizing the\n embattled folk of Abyssea - Vunkerl.\n Will a hero arise to end the reign of\n this tusked terror?"},
      [173] = {n="A Delectable Demon",d="Client: Kuchi Eyjhann\n (Cavernous Maw, Valkurm Dunes)\nSummary:\n A demonic, oversized, and highly\n palatable orobon has been the source\n of endless grief for the beleaguered\n folk of Abyssea - Misareaux. Will the\n survivors ever be free from its savage\n maw and the temptation of its\n succulent flesh?"},
      [174] = {n="A Fluttery Fiend",d="Client: Reinhard\n (Cavernous Maw, Buburimu Peninsula)\nSummary:\n The struggling folk of Abyssea - \n Attohwa have been living in constant\n fear of a dread wamoura. Must the\n survivors always cower in the shadow\n of this winged nightmare?"},
      [175] = {n="Scars of Abyssea",d="Client: Joachim\n (Port Jeuno)\nSummary:\n Endless floods of Abyssean monsters\n are threatening to overwhelm military\n outposts in Vunkerl, Attohwa, and\n Misareaux. Lend your stout sword\n arm to the defense of the ever-vital\n pulse martellos, that hope may live\n on within the resistance effort!"},
      [176] = {n="A Beaked Blusterer",d="Client: Orgis\n (Cavernous Maw, South Gustaberg)\nSummary:\n A fiendish roc, capable of kicking up\n flesh-rending winds in its wake, is the\n bane of the bedraggled survivors of\n Abyssea - Altepa. Can this feathery\n storm of death be stilled, and the\n people given the chance to pick up\n the pieces?"},
      [177] = {n="A Man-eating Mite",d="Client: Alberic\n (Cavernous Maw, Xarcabard)\nSummary:\n The hope-starved survivors of\n Abyssea - Uleguerand live in constant\n fear of a gargantuan diremite with a\n relish for man-flesh. How many victims\n must end up inside the belly of this\n foul beast before something is done?"},
      [178] = {n="An Ulcerous Uragnite",d="Client: Rurukaka\n (Cavernous Maw, North Gustaberg)\nSummary:\n An uncharacteristically aggressive\n uragnite has been a source of great\n torment to the survivors of Abyssea -\n Grauberg. Will a savior not rise to\n free the people from the threat of\n this belligerent bivalve?"},
      [179] = {n="Heroes of Abyssea",d="Client: Joachim\n (Port Jeuno)\nSummary:\n The poor souls stranded in Altepa,\n Uleguerand, and Grauberg face a\n constant struggle of simply subsisting\n in harsh climes. Yet cruel fate would\n also see them plagued by Abyssean\n horrors of unsurpassed ferocity. Help\n is direly needed if these beleaguered\n folk are to make it through the\n unending night."},
      [180] = {n="A Sea Dog's Summons",d="Client: Joachim\n (Port Jeuno)\nSummary:\n Joachim bears a message from\n Gilgamesh, who has need to speak\n to you once more. This time, make\n your way to the Hall of the Gods,\n deep within Ro'Maeve."},
      [181] = {n="Death and Rebirth",d="Client: Gilgamesh\n (Hall of the Gods)\nSummary:\n The chilling truth behind the\n cataclysm lies exposed: divine\n will is at work. But what chain\n of events could possibly have\n led to the disappearance of\n the Champions of Abyssea?"},
      [182] = {n="Emissaries of God",d="Client: Esha'ntarl\n (Hall of the Gods)\nSummary:\n The enigmatic caturae are suspected\n to hold the key to gaining access to\n Al'Taieu, the celestial capital. Defeat\n all six known species, that the door\n to salvation might be cast opened!"},
      [183] = {n="Beneath a Blood-red Sky",d="Client: Esha'ntarl\n (Hall of the Gods)\nSummary:\n With the caturae eliminated, a\n gateway to Al'Taieu has manifested\n in Vana'diel, on Qufim Island. What\n dark shadow lies in wait on the far\n side? There is but one way to find\n out!"},
      [184] = {n="The Wyrm God",d="Client: Prishe \n (Abyssea - Empyreal Paradox)\nSummary:\n Prishe, the sole survivor of mankind's\n ill-fated confrontation with Promathia,\n speaks of the Twilight God's\n transformation into a fearsome\n embodiment of terror and dread.\n The final battle is at hand, and the\n stakes are high: the very survival of\n Abyssea!"},
      [185] = {n="Meanwhile, Back on Abyssea",d="Mission Orders:\n Although the destructive will of the\n Twilight God is no more, the\n horrendous destruction wrought upon\n the land cannot be undone overnight.\n Yet now seeds of hope have been\n planted within the hearts of men...the\n hope that glory days shall once more\n return to Abyssea."},
      [186] = {n="A Moonlight Requite",d="Client: Prishe \n (Abyssea - Empyreal Paradox)\nSummary:\n You have made a solemn promise to\n pay visit to Prishe, who has sworn to\n watch over the world from a faraway\n demesne."},
      [187] = {n="Dominion Op #10 (Grauberg)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Grauberg)\nSummary:\n Slay a prescribed quota of\n glen crabs to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [188] = {n="Dominion Op #11 (Grauberg)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Grauberg)\nSummary:\n Slay a prescribed quota of\n seelies to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [189] = {n="Dominion Op #12 (Grauberg)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Grauberg)\nSummary:\n Slay a prescribed quota of\n unseelies to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [190] = {n="Dominion Op #13 (Grauberg)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Grauberg)\nSummary:\n Slay a prescribed quota of\n Goblin plunderers to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
      [191] = {n="Dominion Op #14 (Grauberg)",r=1,d="Client: Dominion Sergeant\n (Abyssea - Grauberg)\nSummary:\n Slay a prescribed quota of\n Goblin meatgrinders to further the\n Resistance effort in the area.\n After completing your objective,\n report back to any Dominion sergeant."},
    }},
    adoulin = { name = "Seekers of Adoulin", ids = {
      [0] = {n="Twitherym Dust",d="Client: Gurren-Murren (Frontier Station,\n Ceizak Battlegrounds)\nSummary:\n The southern section of the\n battlegrounds is home to a lek of\n twitherym, and the dust on their\n wings is said to have magical\n properties. Collect some sap exuding\n from the trees there and report back\n to Gurren-Murren."},
      [1] = {n="To Catch a Predator",d="Client: Lucretia (Frontier Bivouac,\n Ceizak Battlegrounds)\nSummary:\n One of the local mantids has been\n terrorizing the area. Use some of the\n chapuli around the bivouac as bait to\n lure it out of hiding and exterminate\n the threat."},
      [2] = {n="Empty Nest",d="Client: Bataron (Frontier Bivouac,\n Ceizak Battlegrounds)\nSummary:\n A wasp nest located in the area has\n been causing those at the bivouac\n much consternation. Vanquish eight of\n the belaboring wasps within and report\n back with your progress."},
      [5] = {n="Don't Clam Up on Me Now",d="Client: Oblor (Frontier Station,\n Yahse Hunting Grounds)\nSummary:\n Rations are starting to run low, and\n it's up to you to find some more!\n Collect five shellfish found along the\n seashore in Yahse Hunting Grounds."},
      [6] = {n="Hop to It",d="Client: Chya Mindorah (Frontier Bivouac,\n Yahse Hunting Grounds)\nSummary:\n Chapuli are wreaking havoc on the\n local flora. Head a ways to the north,\n where the chapuli have taken roost,\n and smoke out and vanquish their\n leader."},
      [9] = {n="Boiling Over",d="Client: Leautiere (Frontier Bivouac,\n Yahse Hunting Grounds)\nSummary:\n Haul yourself over to the Moh Gates,\n survey the magma there, and report\n back with your findings. The entrance\n to the Moh Gates is located in the\n north and west outreaches of Yahse\n Hunting Grounds."},
      [10] = {n="Poisoning the Well",d="Client: Fritha (Frontier Station,\n Foret de Hennetiel)\nSummary:\n Researching the properties of the\n Zoldeff River may lead to insights that\n aid the colonization initiative.\n Collect some water from the mouth of\n the river and bring it back to Fritha."},
      [12] = {n="Unsullied Lands",d="Client: Inmot-Pinmot (Frontier Bivouac,\n Foret de Hennetiel)\nSummary:\n Not all ground near the Zoldeff River\n has succumbed to corruption--an\n ergon locus located nearby is keeping\n the surrounding lands pristine. If you\n run across the locus, collect a sample\n of the surrounding sand."},
      [16] = {n="No Rime Like the Present",d="Client: Hegnor (Frontier Station,\n Morimar Basalt Fields)\nSummary:\n Rime ice forms on the coniferous\n trees of Morimar Basalt Fields during\n periods of snowfall. Studying this ice\n could yield information about the\n area's climate and ecosystem.\n Bring some back for research."},
      [18] = {n="A Geothermal Expedition",d="Client: Fallion (Frontier Bivouac,\n Morimar Basalt Fields)\nSummary:\n Hot springs are not only good for\n relaxation--they are also worth\n researching! Test the water of hot\n springs in different locations\n throughout Morimar Basalt Fields and\n summarize your findings."},
      [22] = {n="Endeavoring to Awaken",d="Client: Octavien (Sverdhried Hillock,\n Eastern Adoulin)\nSummary:\n Those who have attained a certain\n degree in the runic arts are oft asked\n to undergo the \"Trial of Reason,\"\n which is held in the subterranean\n Watergarden Coliseum. Clash swords\n with one of the Order of Orvail's\n finest and fulfil your destiny."},
      [23] = {n="Forging New Bonds",d="Client: Octavien (Sverdhried Hillock,\n Eastern Adoulin)\nSummary:\n Scour the lands for a capable\n blacksmith who can fashion a sword\n worthy of displaying at the Order of\n Orvail's traditional ceremony."},
      [24] = {n="Legacies Lost and Found",d="Client: Octavien (Sverdhried Hillock,\n Eastern Adoulin)\nSummary:\n Certain contraptions that create\n weapons imbued with the power of\n runes are supposedly scattered\n throughout the Middle Lands. Help the\n Federation of Windurst's Ohruru by\n investigating the issue."},
      [25] = {n="Destiny's Device",d="Client: Octavien (Sverdhried Hillock,\n Eastern Adoulin)\nSummary:\n Unearth the truth behind the ultimate\n trial so the Order of Orvail can avoid\n any more tragedies such as the one\n that took place two years prior."},
      [26] = {n="Granddaddy Dearest",r=1,d="Client: Alienor (Pioneers' Coalition,\n Western Adoulin)\nSummary:\n Alienor wants to send a care package\n containing Adoulinian delicacies to\n her grandfather in Jeuno, and also\n wishes to know about the ongoing\n expedition he leads."},
      [27] = {n="Wayward Waypoints",d="Client: Sharuru (Peacekeepers'\n Coalition, Eastern Adoulin)\nSummary:\n The curmudgeon Sharuru is concerned\n about the health of her waypoint\n friends located far outside of Adoulin\n proper. Help her recalibrate the\n waypoints in Jeuno and at the various\n frontier stations."},
      [28] = {n="One Good Turn...",d="Client: Chelidoine (Coronal Esplanade,\n Eastern Adoulin)\nSummary:\n Not every pioneer is a natural.\n Chelidoine needs some advice on how\n to be a boon rather than a burden in\n Adoulin's most pressing initiative."},
      [29] = {n="F.A.I.L.ure Is Not an Option",d="Client: Clautaire (Order of\n Thurandaut Residence, Western Adoulin)\nSummary:\n School projects are an important part\n of a young boy's studies, and\n Clautaire needs a hunk of bedrock to\n complete his report."},
      [30] = {n="Order Up",d="Client: Reja Ygridhi (Celennia Memorial\n Library, Eastern Adoulin)\nSummary:\n Visit the Twelve Orders and ascertain\n whether or not the information\n contained within the dossier that the\n library prepared on them is correct."},
      [31] = {n="It Never Goes Out of Style",r=1,d="Client: Veldeth (Frontier Station,\n Marjami Ravine)\nSummary:\n Velkk necklaces and Velkk masks are\n the order of the day. Bring two of\n either to Veldeth, who doesn't care\n how you get ahold of them."},
      [32] = {n="Water, Water, Everywhere",d="Client: Jhen Durheka (Frontier Bivouac,\n Marjami Ravine)\nSummary:\n Velkk encampments are impeding\n progress into surveys of the river in\n Marjami Ravine. Collect samples from\n the upper and lower sections, as well\n as from water near the Dho Gates."},
      [33] = {n="Dirt Cheap",d="Client: Mano-Amano (Frontier Station,\n Yorcia Weald)\nSummary:\n Numbing blossoms grow in a particular\n area of the weald. Find where that is\n and collect a soil sample."},
      [34] = {n="Flower Power",r=1,d="Client: Mano-Amano (Frontier Station,\n Yorcia Weald)\nSummary:\n Mano-Amano requires numbing\n blossoms for his research--three of\n them, in fact."},
      [35] = {n="Elementary, My Dear Sylvie",d="Client: Sylvie (Adoulin Waterfront,\n Western Adoulin)\nSummary:\n Sylvie's father, Hostenn, has\n volunteered to give you advanced\n geomancy lessons. Find him in the\n first frontier bivouac in Morimar\n Basalt Fields, and you may learn\n something that will further the limits\n of your geomantic prowess."},
      [36] = {n="For Whom the Bell Tolls",d="Client: Sylvie (Adoulin Waterfront,\n Western Adoulin)\nSummary:\n Sylvie's father, the venerable Hostenn,\n has gone missing, and Sylvie seeks the\n assistance of Ikhi Askamot. Head to\n the Order of Renaye Residence to\n beseech her aid."},
      [37] = {n="The Bloodline of Zacariah",d="Client: Sylvie (Adoulin Waterfront,\n Western Adoulin)\nSummary:\n Preparations for Hostenn's funeral are\n ongoing, and Sylvie wishes to\n commence a ritual for him. Collect\n three chunks of acuex ore, which can\n be found on acuexes in Cirdas Caverns."},
      [38] = {n="The Communion",d="Client: Sylvie (Adoulin Waterfront,\n Western Adoulin)\nSummary:\n Lhaiso Neftereh has fallen ill, perhaps\n because of the anomalies in the earth.\n Sylvie wants you to accompany her to\n the Order of Renaye residence in\n Eastern Adoulin to check up on Lhaiso."},
      [46] = {n="Flavors of Our Lives",d="Client: Berghent (Road to Big Bridge,\n Western Adoulin)\nSummary:\n Help an old man reclaim one of the\n only happy moments in his life by\n finding the ambrosial fruit he once\n tasted in his youth. Its craggy and\n moldy exterior hides a vivid red and\n succulent interior that cannot be\n mistaken for any other produce."},
      [50] = {n="Western Waypoints, Ho!",d="Client: Alienor (Pioneers' Coalition,\n Western Adoulin)\nSummary:\n Attune your geomagnetron to each of\n the waypoints in Western Adoulin and\n report back."},
      [51] = {n="Wes...Eastern Waypoints, Ho!",d="Client: Sharuru (Peacekeepers'\n Coalition, Eastern Adoulin)\nSummary:\n Attune your geomagnetron to each of\n the waypoints in Eastern Adoulin and\n report back."},
      [53] = {n="Grind to Sawdust",d="Client: Elmric (Frontier Station,\n Ceizak Battlegrounds)\nSummary:\n What good is colonization if you\n can't chop down trees? Participate in\n one Colonization Reive to prove your\n mettle and report back to learn about\n how to efficiently clear paths through\n the jungle."},
      [54] = {n="Breaking the Ice",d="Client: Traiffeaux (Frontier Station,\n Kamihr Drifts)\nSummary:\n Walls of sheer ice are impeding\n colonization in Kamihr Drifts. You\n need to find the weak spot in these\n walls--but your ears will freeze\n without a pair of earmuffs. Collect\n three rabbit hides and one raaz tusk\n and bring them to Traiffeaux."},
      [55] = {n="I'm on a Boat",d="Client: Choubollet (River Mouth,\n Foret de Hennetiel)\nSummary:\n The Zoldeff River is not safe for\n passage...unless you have a portable\n boat! Bring three squares of dhalmel\n leather, one twitherym scale, and one\n jar of umbril ooze to Choubollet so\n he can build you a nautical\n masterpiece."},
      [56] = {n="A Stone's Throw Away",d="Client: Apolliane (Frontier Station,\n Morimar Basalt Fields)\nSummary:\n Hardened magma forms crags that dot\n the landscape, hindering travel.\n Collect one marble nugget and\n bring it back to Apolliane in\n exchange for her teaching you the\n arts of destroying these obstacles."},
      [57] = {n="Hide and Go Peak",d="Client: Toppled Tree (Frontier Station,\n Marjami Ravine)\nSummary:\n Procuring Velkk hide is a necessary\n step in fashioning a set of gloves to\n scale the precarious cliffs and thorny\n vines in Eastern Ulbuka. Head for the\n Velkk encampment located to the\n southwest and steal some hide from\n their repository."},
      [58] = {n="The Whole Place Is Abuzz",d="Client: Rumin-Flumin (Frontier Bivouac,\n Yahse Hunting Grounds)\nSummary:\n Numbing blossoms have antidotal\n effects that inhibit the poisons of\n pungent fungi. Head to the dead end\n to the southwest and use the Land\n of Milk and Honey beehive to collect\n ten bees. Make sure you are resting\n quietly to collect them!"},
      [59] = {n="Orobon Appetit",d="Client: Nestroh (Central Frontier\n Bivouac, Foret de Hennetiel)\nSummary:\n A lone fisherman has his eyes on a\n rare delicacy--orobon meat. Fish\n 'em up, cut 'em up, and serve 'em up\n to satiate his hunger with the\n perfect cut of meat."},
      [60] = {n="Talk About Wrinkly Skin",d="Client: Orsa-Porsa (Frontier Station,\n Morimar Basalt Fields)\nSummary:\n A strange old man has taken a liking\n to the hot springs found in Morimar,\n which has Orsa-Porsa rather\n nonplussed. The Taru has tasked you\n with bringing him some Uleguerand milk,\n an apkallu egg, and a felicifruit so he\n can lure the old man out of hiding."},
      [61] = {n="No Love Lost",d="Client: Peppe-Aleppe (Frontier\n Station, Kamihr Drifts)\nSummary:\n Orsa-Porsa claims that Peppe-Aleppe\n was shipped off to Kamihr Drifts for\n making unwanted advances on a young\n woman. Bring Peppe-Aleppe one\n ruszor hide so he can invent\n something fabulous to win Amchuchu's\n favor."},
      [62] = {n="Did You Feel That?",d="Client: Udip Ferawoh (Frontier Station,\n Marjami Ravine)\nSummary:\n Velkk have been planting spinescent\n protuberances all throughout the\n ravine, and Udip Ferawoh is sick of\n it. She wants you to suffer five\n amnesic attacks from them before\n returning--but don't get in over your\n head."},
      [70] = {n="Don't Ever Leaf Me",d="Client: Audibert (Scouts' Coalition,\n Eastern Adoulin)\nSummary:\n The leafkin are mysterious yet\n adorable creatures, and one of their\n biggest fans wants to learn more\n about them. Assist him in unearthing\n information about their habitats and\n life cycles."},
      [71] = {n="Keep Your Bloomers On, Erisa",d="Client: Erisa (Order of Renaye\n Research Chamber, Eastern Adoulin)\nSummary:\n Though fruits and flowers have begun\n to sprout from a new type of plant\n brought to Erisa, they haven't gotten\n any larger over the past weeks. She\n wants to create some new fertilizer,\n but to do so she needs some\n Yahse humus."},
      [72] = {n="Scaredy-Cats",d="Client: Eamonn (Pioneers' Coalition,\n Western Adoulin)\nSummary:\n A couple of Pioneers' Coalition\n members have seen some fearsome\n sights in the forest, but their leader\n demands that they collect some soil\n samples there. Head to the Ceizak\n Battlegrounds and do their dirty work\n for them."},
      [73] = {n="Raptor Rapture",d="Client: Pagnelle (Mummers' Coalition,\n Western Adoulin)\nSummary:\n Vorahal, the Mummers' Coalition's\n most prized raptor, escaped his pen\n and evidently mauled a hapless citizen\n named Ilney. Go visit the victim and\n hear his side of the story."},
      [74] = {n="Exotic Delicacies",d="Client: Flapano (Restaurant, Western\n Adoulin)\nSummary:\n Just as a chef needs a pot, so too\n does he need ingredients. Specifically,\n he needs saffron, barnacles, and\n mussels to complete his dish."},
      [75] = {n="A Pioneer's Best (Imaginary) Friend",d="Client: Merleg (Adoulin Alleys,\n Western Adoulin)\nSummary:\n Some of the city's children won't let\n you into their exclusive club of\n justice defenders without showing\n the aura of a true pioneer. Seek out\n someone who can bestow it upon you,\n then impress the rascals with your\n newfound puissance."},
      [76] = {n="Hunger Strikes",d="Client: Westerly Breeze\n (Waterfront, Western Adoulin)\nSummary:\n All work and no food makes at least\n one Galkan courier a cranky boy.\n Introduce him to a certain soup from\n the Middle Lands and restore his zest\n for working life."},
      [77] = {n="The Old Man and the Harpoon",d="Client: Jorin (Waterfront,\n Western Adoulin)\nSummary:\n A lone fisherman will lose his battle\n with the big one unless you carry his\n trusty harpoon to the Inventors'\n Coalition for repair."},
      [78] = {n="A Certain Substitute Patrolman",d="Client: Rising Solstice\n (Jorius Yett, Western Adoulin)\nSummary:\n The soldier charged with making the\n rounds in Western Adoulin has fallen\n not ill, but asleep. Do the\n Peacekeepers' Coalition a \n service by filling in for him and \n following his assigned route\n to the letter."},
      [79] = {n="It Sets My Heart Aflutter",r=1,d="Client: Saldinor (Civic Arboretum, Rala\n Waterways)\nSummary:\n Some pests are more annoying than\n others. Collect two twitherym\n wings and bring them back."},
      [82] = {n="Transporting",d="Client: Vaulois (Road to\n the Waterfront, Western Adoulin)\nSummary:\n A mysterious package has been\n accidentally delivered to the wrong\n address. Take it with you to the\n warehouse on the Adoulin Waterfront\n so that it can be hauled to its\n proper recipient."},
      [84] = {n="The Starving",d="Client: Westerly Breeze\n (Waterfront, Western Adoulin)\nSummary:\n Everyone's favorite famished Galka\n once again hungers for the delicacies\n of the Middle Lands. This time\n however, he wants a certain drink that\n packs a punch in more ways than one."},
      [85] = {n="Fertile Ground",d="Client: Chalvava (Civic Arboretum, Rala\n Waterways)\nSummary:\n How can you grow plants in low\n quality dirt? With fertilizer, that's\n how! Go acquire some from the\n Inventors' Coalition to make the best\n of a fruitless situation."},
      [88] = {n="\"Always more,\" Quoth the Ravenous",d="Client: Westerly Breeze\n (Waterfront, Western Adoulin)\nSummary:\n The third time may be a charm for\n some things, but the infamous\n starving Couriers' Coalition member\n brings only bad tidings--this time in\n the form of a sparkling pink beverage.\n Will it be his last request ever?"},
      [89] = {n="Meg-alomaniac",d="Client: Sharuru (Peacekeepers'\n Coalition, Eastern Adoulin)\nSummary:\n Meg and all her \"sister\" waypoints in\n Western Adoulin have come down with\n some sort of virus. Check to make\n sure they are in the best of health by\n using a waypoint scanner kit."},
      [91] = {n="The Longest Way Round...",d="Client: Vastran (Big Bridge, Eastern\n Adoulin)\nSummary:\n Making the rounds is too tough for a\n certain soldier...but not for you! Make\n sure the area is safe and report back."},
      [93] = {n="A Good Pair of Crocs",r=1,d="Client: Felmsy (Wharf, Eastern Adoulin)\nSummary:\n Poor Felmsy is in a bit of a tizzy over\n his family's safety. Assuage his fears\n by bringing back a Velkk\n mask or necklace to prove you're\n dealing with the Velkk threat."},
      [94] = {n="Cafe...teria",r=1,d="Client: Yocile (Cafe des Larmes,\n Eastern Adoulin)\nSummary:\n How can Yocile bring out an\n intercontinental taste without Elshimo\n coconuts? Bring back two to help\n make an exquisite delight!"},
      [96] = {n="A Shot in the Dark",r=1,d="Client: Pudith (Residence, Eastern\n Adoulin)\nSummary:\n Listening to her husband's irrational\n ramblings about all manner of horrors\n in Ulbuka's uncharted lands has Pudith\n terrified, too! Go recover one jar of\n umbril ooze to calm her fears."},
      [100] = {n="Open the Floodgates",d="Client: Risen Hackles (Peacekeepers'\n Coalition, Eastern Adoulin)\nSummary:\n One of the Peacekeepers' Coalition's\n finest has challenged you to find the\n holy battlegrounds in the Rala\n Waterways. Head down and prove that\n you have what it takes to navigate\n the waters."},
      [102] = {n="No Laughing Matter",d="Client: Peladi Shalmohr (Mummers'\n Coalition, Western Adoulin)\nSummary:\n Find the Mummers' Coalition's newest\n bumbling duo, Tarutaru Sauce, and\n prevent them from sucking all the life\n out of the room."},
      [103] = {n="All the Way to the Bank",d="Client: Peladi Shalmohr (Mummers'\n Coalition, Western Adoulin)\nSummary:\n Peladi Shalmohr is about to burst at\n the seams from the tab Tarutaru\n Sauce has run up throughout the city,\n and has requested that you take care\n of it. The culprits are hiding\n somewhere in Western Adoulin..."},
      [104] = {n="To Laugh Is to Love",d="Client: Peladi Shalmohr (Mummers'\n Coalition, Western Adoulin)\nSummary:\n Tarutaru Sauce threatens to deplete\n the Mummers' Coalition's profits yet\n again, and Peladi Shalmohr would have\n you stop them before they dip into\n the red. Stop gawking and get at it!"},
      [105] = {n="A Barrel of Laughs",d="Client: Tuffle-Buffle (Near the\n warehouses, Western Adoulin)\nSummary:\n A mannequin of curious origins has\n been wrested from Tarutaru Sauce's\n control. The suspects are not\n altogether unknown, and the prize can't\n be far. Search the immediate area for\n traces of its whereabouts."},
      [108] = {n="Vegetable Vegetable Revolution",d="Client: Amchuchu (Inventors' Coalition,\n Western Adoulin)\nSummary:\n The recent population explosion in\n Adoulin has been causing food\n problems. Seek out Midras to assist\n him and Amchuchu in finding a new \n mineral ore in the Sih Gates so they\n can fabricate improved fertilizer."},
      [109] = {n="Vegetable Vegetable Evolution",d="Client: Amchuchu (Inventors' Coalition,\n Western Adoulin)\nSummary:\n Midras has headed off to Yorcia\n Weald for further research into\n potential fertilizer ingredients, and\n Amchuchu is worried sick about him.\n Venture into the forest and ensure\n that he is safe."},
      [110] = {n="Vegetable Vegetable Crisis",d="Client: Amchuchu (Inventors' Coalition,\n Western Adoulin)\nSummary:\n Amchuchu asks you deliver a missive\n to Cid proclaiming that Junior's plan\n fell through--but first, she wants you\n to bring back a midrium ingot, some\n urunday lumber, and a square of\n raaz leather."},
      [111] = {n="Vegetable Vegetable Frustration",d="Client�F Amchuchu\n(Inventors' Coalition, Western Adoulin)\nSummary:\n Hoping to lift Midras out of his\n melancholic state, Amchuchu has sent\n you to Bastok to find out what first\n inspired him to become an inventor."},
      [114] = {n="A Thirst for the Ages",d="Client: Roskin (Near Cafe des Larmes,\n Eastern Adoulin)\nSummary:\n Search Adoulin's bifurcated districts\n and beyond to find clues pertaining to\n the formation of its current political\n body. The riches you'll receive for\n this classified mission may just\n amount to more than you could ever\n imagine."},
      [115] = {n="A Thirst for the Eons",d="Client: Roskin (Near Cafe des Larmes,\n Eastern Adoulin)\nSummary:\n Search Adoulin's bifurcated districts\n and beyond to find clues pertaining to\n what engendered the Great Expedition.\n The riches you'll receive for\n this classified mission may just\n amount to more than you could ever\n imagine."},
      [116] = {n="A Thirst for Eternity",d="Client: Roskin (Near Cafe des Larmes,\n Eastern Adoulin)\nSummary:\n Find clues that will unravel the truth\n surrounding August and his generals.\n The riches you'll receive for\n this classified mission may just\n amount to more than you could ever\n imagine."},
      [117] = {n="A Thirst Before Time",d="Client: Roskin (Near Cafe des Larmes,\n Eastern Adoulin)\nSummary:\n Who--or what--has been behind the\n scenes and manipulating Roskin into\n solving various historical mysteries?\n There's no time like the present to\n reach into the past!"},
      [118] = {n="Dances with Luopans",d="Client: Sylvie (Adoulin Waterfront,\n Western Adoulin)\nSummary:\n The intricacies of a geomancer lie in\n the luopans--compatriots in the\n casting of advanced magics. To make\n one, you need one petrified log and\n a fistful of homeland soil. Now\n where could you find them...?"},
      [119] = {n="Children of the Rune",d="Client: Octavien (Sverdhried Hillock,\n Eastern Adoulin)\nSummary:\n Years of excruciating training and\n long hours of study await those who\n desire to master the runic arts. One\n may circumvent this laborious\n process, however, by engraving runes\n upon his body with ink from a Yahse\n wildflower petal."},
      [120] = {n="Flowers for Svenja",d="Client: Alianne (Order of Janniston\n Residence, Western Adoulin)\nSummary:\n Svenja has headed off to the Celennia\n Memorial Library to do some\n research...but to what purpose?"},
      [121] = {n="Thorn in the Side",d="Client: Nashu (Exorcist Priory,\n Eastern Adoulin)\nSummary:\n The Blackthorn Coven has been\n causing inordinate amounts of trouble\n for Adoulin with the traps they are\n setting. Trek to J-6 in Yorcia Weald\n to capture these mavens of mischief\n and set the sacred city at ease."},
      [122] = {n="Do Not Go Into the Light",d="Client: Alianne (Order of\n Janniston, Western Adoulin)\nSummary:\n The young man who benefitted from\n the Hennebloom leaf you gave to\n Svenja would like to thank you in\n person. Go to the infirmary and hear\n what he has to say."},
      [123] = {n="Velkkovert Operations",d="Client: Nashu (Exorcist Priory,\n Eastern Adoulin)\nSummary:\n The Blackthorn Coven has been\n conspiring with the Velkk, but to what\n end? Get to the bottom of this\n bewitching development before it is\n too late."},
      [124] = {n="Hypocritical Oath",d="Client: Alianne (Order of\n Janniston, Western Adoulin)\nSummary:\n How can Logan's plight be ignored\n when the order is in possession of a\n possible cure? Ask Margret what she\n can find out."},
      [125] = {n="The Good, the Bad, the Clement",d="Client: Nashu (Exorcist Priory,\n Eastern Adoulin)\nSummary:\n Nashu has gone to return the catalyst\n the Blackthorn Coven gave him and\n convince the trio to end their\n involvement with the Velkk.\n Accompany him to the showdown in\n Yorcia Weald."},
      [126] = {n="Lerene's Lament",d="Client: Lerene (Outer Ra'Kaznar)\nSummary:\n Lerene is fed up with her inability to\n break down magic-embossed doors in\n Outer Ra'Kaznar, but thinks that two\n squares of ancestral cloth from\n shadows would enable her to fashion a\n device to nullify the enchantment."},
      [127] = {n="The Secret to Success",d="Client: Erfimia (Exorcist Priory,\n Eastern Adoulin)\nSummary:\n Erfimia is convinced that there is no\n way a run-of-the-mill exorcist like\n Robertioux could pull off such an\n incredible feat without a clandestine\n training regime, and thus wants you to\n discover his secret."},
      [128] = {n="No Mercy for the Wicked",d="Client: Ingrid (Exorcist Priory,\n Eastern Adoulin)\nSummary:\n Hildebert's wife remains in a deep\n coma, and Ingrid is uncharacteristically\n concerned. Head to the Peacekeepers'\n Coalition to help her through these\n troubling times."},
      [129] = {n="Mistress of Ceremonies",d="Client: Marcellurin (Exorcist Priory,\n Eastern Adoulin)\nSummary:\n Hildebert's wife, Faustoise, has finally\n awakened, but she has led Ingrid deep\n into Yorcia Weald. Head after them\n and figure out what is going on."},
      [131] = {n="Saved by the Bell",d="Client: Nhili Uvolep (Order of\n Renaye, Eastern Adoulin)\nSummary:\n A fable recited by Nhili tells of a\n fearsome struggle that took place in\n the wilds many centuries past. Are the\n rumors true, and what do they have to\n do with the bell you found?"},
      [132] = {n="Quiescence",d="Client: Zurko-Bazurko (Watergarden\n Coliseum, Rala Waterways)\nSummary:\n [This is a challenge]\n You smell of rotten-wotten\n rolanberries. Now come fightaru me.\n�@\n�@\n�@\n�@�@�@�@�@�@�@�@�@�@�@�@�@Zurko-Bazurko"},
      [133] = {n="Sick and Tired",d="Client: Svenja (Order of Janniston\n Residence, Western Adoulin)\nSummary:\n An epidemic possibly originating in\n the Great Expedition has gripped\n Adoulin with fear. Meet up with\n Alianne at Yorcia Weald's frontier\n station to apprise her of the\n situation."},
      [134] = {n="Geomancerrific",d="Client: Nhili Uvolep (Order of\n Renaye, Eastern Adoulin)\nSummary:\n The Order of Renaye's geomancers\n have a storied history of training with\n particular weaponry to enhance their\n capabilities. Perhaps you, too, could\n glean new powers from the repeated\n use of Nhili's weapon."},
      [135] = {n="Rune Fencing the Night Away",d="Client: Gaddiux (Inventors' Coalition,\n Western Adoulin)\nSummary:\n You have been given a great sword\n that, for reasons unbeknownst to you,\n has been outfitted with a device that\n measures durability. Moreover,\n something astonishing is supposed to\n occur when it is used a certain\n number of times."},
      [136] = {n="The Weatherspoon Inquisition",d="Client: Nashu (Jorius Yett,\n Western Adoulin)\nSummary:\n Under the orders of Vortimere,\n Araustoix has led a contingent of\n exorcists on a witch hunt of the most\n literal kind. Head to Yorcia Weald\n with Nashu to warn the enigmatic\n Blackthorn Coven."},
      [137] = {n="Eye of the Beholder",d="Client: Erfimia (Exorcist Priory,\n Eastern Adoulin)\nSummary:\n Erfimia has gotten the courage to\n view the results of an exorcism\n firsthand thanks to her adoration of\n Robertioux, who performed such a\n ritual near coordinates J-8 in Yorcia\n Weald. Head there and meet up with the\n mildly trepidatious would-be exorcist."},
      [138] = {n="The Curious Case of Melvien",d="Client: Margret (Sverdhried Hillock,\n Eastern Adoulin)\nSummary:\n Margret postulated that Melvien's\n death was by human hands. Aid her in\n finding the truth."},
      [139] = {n="Not-So-Clean Bill",d="Client: Svenja (Order of Janniston\n Residence, Western Adoulin)\nSummary:\n Svenja's impudent patient, Logan, has\n absconded to the jungle in search of a\n particular beast. Head to the frontier\n station in Morimar Basalt Fields and\n enlist their aid in tracking down the\n errant young man."},
      [140] = {n="In the Land of the Blind",d="Client�FBehsa Alehgo (Exorcist Priory,\n Eastern Adoulin)\nSummary:\n Erfimia has been cooped up in the\n library for days. Head to Celennia\n Memorial Library and make sure she\n is alright."},
      [141] = {n="The Weatherspoon War",d="Client�F Nashu (Marjami Ravine)\nSummary:\n The Velkk, Mligni-Vorgut, has seized\n an artifact with the power to destroy\n Adoulin. The exorcists want you to help\n stop him at the Seat of Gramk-Droog."},
      [142] = {n="Treasures of the Earth",d="Client: Sylvie (Adoulin Waterfront,\n Western Adoulin)\nSummary:\n Sylvie still has lingering doubts about\n her father. Meet up with her in Morimar\n Basalt Fields for moral support."},
      [143] = {n="Epiphany",d="Client: Octavernost (Big Bridge,\n Western Adoulin)\nSummary:\n Octavernost has enlisted your aid in a\n secret project headed by Amchuchu\n herself."},
      [144] = {n="The Silent Forest",d="Client�F Arciela (Adoulin Castle,\n Eastern Adoulin)\nSummary:\n�@Living in harmony with the forest\n requires the assistance of the\n avatar Siren. Head to Escha - Ru'Aun\n and look for clues regarding her\n disappearance."},
      [145] = {n="Winds of Eternity",r=1,d="Client: Siren (Leafallia)\nSummary:\n Gather ergon power and revisit a\n familiar land in order to confirm\n your bond with Siren."},
    }},
