      [70] = {n="Preserve: Kamihr Drifts",r=1,d="Assignment:\n Head to Kamihr Drifts and destroy a\n monster lair located there. Participate\n in a successful Lair Reive and return \n to the Peacekeepers' Coalition to\n complete this assignment."},
      [71] = {n="Preserve: Cirdas Caverns",r=1,d="Assignment:\n Head to Cirdas Caverns and destroy a\n monster lair located there. Participate\n in a successful Lair Reive and return\n to the Peacekeepers' Coalition to\n complete this assignment."},
      [72] = {n="Preserve: Outer Ra'Kaznar",r=1,d="Assignment:\n Head to Outer Ra'Kaznar or Ra'Kaznar\n Inner Court and destroy a monster lair\n located there. Participate in a\n successful Lair Reive and return to\n the Peacekeepers' Coalition to\n complete this assignment."},
      [73] = {n="Patrol: Rala Waterways",r=1,d="Assignment:\n Head to Rala Waterways and vanquish\n monsters there. Defeat five toads\n and return to the Peacekeepers'\n Coalition to complete this assignment."},
      [74] = {n="Patrol: Sih Gates",r=1,d="Assignment:\n Head to Sih Gates and vanquish\n monsters there. Defeat five twitherym\n and return to the Peacekeepers'\n Coalition to complete this assignment."},
      [75] = {n="Patrol: Moh Gates",r=1,d="Assignment:\n Head to Moh Gates and vanquish\n monsters there. Defeat five raptors\n and return to the Peacekeers'\n Coalition to complete this assignment."},
      [76] = {n="Patrol: Cirdas Caverns",r=1,d="Assignment\n Head to Cirdas Caverns and vanquish\n monsters there. Defeat three maroliths\n and return to the Peacekeepers'\n Coalition to complete this assignment."},
      [77] = {n="Patrol: Dho Gates",r=1,d="Assignment:\n Head to Dho Gates and vanquish\n monsters there. Defeat three efts\n and return to the Peacekeepers'\n Coalition to complete this assignment."},
      [78] = {n="Patrol: Woh Gates",r=1,d="Assignment:\n Head to Woh Gates and vanquish\n monsters there. Defeat three acuexes\n and return to the Peacekeepers'\n Coalition to complete this\n assignment."},
      [79] = {n="Patrol: Outer Ra'Kaznar",r=1,d="Assignment:\n Head to Outer Ra'Kaznar and vanquish\n monsters there. Defeat three ironclads\n and return to the Peacekeepers'\n Coalition to complete this assignment."},
      [80] = {n="Recover: Ceizak Battlegrounds",r=1,d="Assignment:\n Head to Ceizak Battlegrounds or\n Yahse Hunting Grounds and search for\n an item a pioneer lost there. Find the\n item and return to the Mummers'\n Coalition to complete this assignment."},
      [81] = {n="Recover: Foret de Hennetiel",r=1,d="Assignment:\n Head to Foret de Hennetiel or Sih\n Gates and search for an item a\n pioneer lost there. Find the item and\n return to the Mummers' Coalition to\n complete this assignment."},
      [82] = {n="Recover: Morimar Basalt Fields",r=1,d="Assignment:\n Head to Morimar Basalt Fields or Moh\n Gates and search for an item a\n pioneer lost there. Find the item and\n return to the Mummers' Coalition to\n complete this assignment."},
      [83] = {n="Recover: Yorcia Weald",r=1,d="Assignment:\n Head to Yorcia Weald or Cirdas\n Caverns and search for an item a\n pioneer lost there. Find the item\n and return to the Mummers' Coalition\n to complete this assignment."},
      [84] = {n="Recover: Marjami Ravine",r=1,d="Assignment:\n Head to Marjami Ravine or Dho\n Gates and search for an item a\n pioneer lost there. Find the item and\n return to the Mummers' Coalition to\n complete this assignment."},
      [85] = {n="Recover: Kamihr Drifts",r=1,d="Assignment:\n Head to Kamihr Drifts or Woh\n Gates and search for an item a\n pioneer lost there. Find the item and\n return to the Mummers' Coalition to\n complete this assignment."},
      [86] = {n="Research: Rala Waterways",r=1,d="Assignment:\n Head to Rala Waterways and observe\n monsters located there. Become the\n victim of a particular special attack\n from a slug and return to the\n Mummers' Coalition to complete this\n assignment."},
      [87] = {n="Research: Ceizak Battlegrounds",r=1,d="Assignment:\n Head to Ceizak Battlegrounds or\n Yahse Hunting Grounds and observe\n monsters located there. Become the\n victim of a particular special attack\n from a chapuli and return to the\n Mummers' Coalition to complete this\n assignment."},
      [88] = {n="Research: Foret de Hennetiel",r=1,d="Assignment:\n Head to Foret de Hennetiel or Sih\n Gates and observe monsters located\n there. Become the victim of a\n particular special attack from a\n craklaw and return to the Mummers'\n Coalition to complete this assignment."},
      [89] = {n="Research: Morimar Basalt Fields",r=1,d="Assignment:\n Head to Morimar Basalt Fields or Moh\n Gates and observe monsters located\n there. Become the victim of a\n particular special attack from a\n matamata and return to the Mummers'\n Coalition to complete this assignment."},
      [90] = {n="Research: Yorcia Weald",r=1,d="Assignment:\n Head to Yorcia Weald and observe\n monsters located there. Become the\n victim of a particular special\n attack from a snapweed and return\n to the Mummers' Coalition to complete\n this assignment."},
      [91] = {n="Research: Marjami Ravine",r=1,d="Assignment:\n Head to Marjami Ravine and observe\n monsters located there. Become the\n victim of a particular special attack\n from a tulfaire and return to the\n Mummers' Coalition to complete\n this assignment."},
      [92] = {n="Research: Kamihr Drifts",r=1,d="Assignment:\n Head to Kamihr Drifts and observe\n monsters located there. Become the\n victim of a particular special attack\n from a raaz and return to the\n Mummers' Coalition to complete this\n assignment."},
      [93] = {n="Boost: Foret de Hennetiel",r=1,d="Assignment:\n Head to the frontier station in Foret\n de Hennetiel or Morimar Basalt Fields,\n cheer up the workers there, and return\n to the Mummers' Coalition to\n complete this assignment."},
      [94] = {n="Boost: Marjami Ravine",r=1,d="Assignment:\n Head to the frontier station in Marjami\n Ravine or Yorcia Weald, cheer up the\n workers there, and return to the\n Mummers' Coalition to complete this\n assignment."},
      [95] = {n="Boost: Kamihr Drifts",r=1,d="Assignment:\n Head to the frontier station in\n Kamihr Drifts, cheer up the workers\n there, and return to the\n Mummers' Coalition to complete this\n assignment."},
    }},
  },
  mission_lines = {
    sandoria = { name = "San d'Oria", ids = {
      [0] = {n="Smash the Orcish Scouts",d="Mission Orders:\n Hunt Orcs lurking outside San d'Oria\n and bring back one of their axes."},
      [1] = {n="Bat Hunt",d="Mission Orders:\n Exterminate bats from King\n Ranperre's Tomb, and bring back\n proof of your deeds."},
      [2] = {n="Save the Children",d="Mission Orders:\n Rescue the children held captive in the\n Orcish camp in Ghelsba Outpost."},
      [3] = {n="The Rescue Drill",d="Mission Orders:\n Participate in the Temple Knights'\n rescue drill out on La Theine\n Plateau."},
      [4] = {n="The Davoi Report",d="Mission Orders:\n Retrieve the latest scouting report\n from the Temple Knight scout\n somewhere in Davoi."},
      [5] = {n="Journey Abroad",d="Mission Orders:\n Visit the faraway nations of Bastok\n and Windurst and receive official\n recognition as an adventurer."},
      [6] = {n="Journey to Bastok",d="Mission Orders:\n Survey Bastokan mining technology,\n and bring some mythril sand out of\n Palborough Mines. An official named\n Pius will instruct you further."},
      [7] = {n="Journey to Windurst",d="Mission Orders:\n Bring an offering (a shield) from\n Heavens Tower in Windurst to the\n Yagudo treasure room in Giddeus.\n To uphold the honor of San d'Oria,\n claim two of the same shields from\n the Yagudo on your return."},
      [8] = {n="Journey to Bastok",d="Mission Orders:\n Reports indicate that the Quadav\n who inhabit the deepest levels of\n Palborough Mines are up to\n something. An official named Pius\n will instruct you further."},
      [9] = {n="Journey to Windurst",d="Mission Orders:\n Oust the giant monster that dwells\n deep inside the Yagudo realm of\n Giddeus."},
      [10] = {n="Infiltrate Davoi",d="Mission Orders:\n The scout in Davoi needs the help\n of an adventurer."},
      [11] = {n="The Crystal Spring",d="Mission Orders:\n Catch a crystal bass from Crystwater\n Spring, located on the eastern edge\n of Jugner Forest."},
      [12] = {n="Appointment to Jeuno",d="Mission Orders:\n Head to the Embassy of San d'Oria\n in Jeuno to fill your appointed post."},
      [13] = {n="Magicite",d="Mission Orders:\n Seize the three types of magicite\n from Davoi, Beadeaux, and Castle\n Oztroja to prevent the Shadow\n Lord's return."},
      [14] = {n="The Ruins of Fei'Yin",d="Mission Orders:\n This mission involves traveling to\n Fei'Yin, located on the Beaucedine\n Glacier. Visit Chateau\n d'Oraguille to learn more."},
      [15] = {n="The Shadow Lord",d="Mission Orders:\n Head to Castle Zvahl in Xarcabard.\n Visit Chateau d'Oraguille to learn\n more."},
      [16] = {n="Leaute's Last Wishes",d="Mission Orders:\n This mission involves the late Queen\n Leaute. Visit Monarlais Halver in\n Chateau d'Oraguille to learn more."},
      [17] = {n="Ranperre's Final Rest",d="Mission Orders:\n Prince Trion seeks an adventurer.\n Find the prince in his chamber to\n learn more."},
      [18] = {n="Prestige of the Papsque",d="Mission Orders:\n The papsque has requested an\n adventurer of renown. Speak to His\n Holiness in the cathedral. His\n chambers lie upstairs."},
      [19] = {n="The Secret Weapon",d="Mission Orders:\n Reports from Ghelsba indicate that\n the Orcs in Yughott Grotto are up\n to something. Investigate, but speak\n of this to no one."},
      [20] = {n="Coming of Age",d="Mission Orders:\n Princess Claidie will soon celebrate\n her coming-of-age, and the court in\n d'Oraguille needs help with the\n ceremonies. Speak to Monarlais\n Halver and offer your assistance."},
      [21] = {n="Lightbringer",d="Mission Orders:\n Royaulais Destin himself has\n summoned you for a vital mission.\n Seek audience with His Majesty in\n Chateau d'Oraguille immediately."},
      [22] = {n="Breaking Barriers",d="Mission Orders:\n Darkness looms over San d'Oria.\n Report to the Audience Chamber in\n Chateau d'Oraguille for further details."},
      [23] = {n="The Heir to the Light",d="Mission Orders:\n The Rites of Succession will be held\n at the cathedral in Northern San\n d'Oria. You are to report there\n for guard duty."},
    }},
    bastok = { name = "Bastok", ids = {
      [0] = {n="The Zeruhn Report",d="Mission Orders:\n Collect Overseer Makarim's report\n from the Zeruhn Mines, in the\n western section of the Bastok\n Mines District.\n Deliver said report to Sir Naji,\n a Musketeer stationed near the\n President's Office."},
      [1] = {n="A Geological Survey",d="Mission Orders:\n Assist Chief Engineer Cid in\n conducting an analysis of the\n gaseous emissions in the Dangruf\n Wadi. Meet with Cid for a\n more detailed explanation."},
      [2] = {n="Fetichism",d="Mission Orders:\n Hunt the Quadav in the\n Palborough Mines and collect the\n four parts of a Quadav fetich."},
      [3] = {n="The Crystal Line",d="Mission Orders:\n Find a section of the strange\n structure on the Konschtat\n Highlands that drains the energy\n from crystals.\n Bring a faded crystal back to\n Chief Engineer Cid for analysis."},
      [4] = {n="Wading Beasts",d="Mission Orders:\n Procure a lizard egg from monsters\n in the Dangruf Wadi.\n Deliver the egg to Senator Alois\n in the President's Office."},
      [5] = {n="The Emissary",d="Mission Orders:\n Gather information on San d'Oria\n and Windurst.\n The Bastokan consulates in those\n two countries will provide you\n with a detailed briefing."},
      [6] = {n="The Emissary (San d'Oria)",d="Mission Orders:\n Go to the highest camp\n in the Ghelsba Outpost\n and defeat Warchief Vatgit."},
      [7] = {n="The Emissary (Windurst)",d="Mission Orders:\n Go to Heavens Tower and acquire\n the magic sword to be offered to\n the Yagudo.\n Switch weapons at the consulate\n before taking it to the treasure\n chamber in Giddeus."},
      [8] = {n="The Emissary (San d'Oria)",d="Mission Orders:\n Investigate the Yughott Grotto\n deep inside the Ghelsba Outpost."},
      [9] = {n="The Emissary (Windurst)",d="Mission Orders:\n Go to the deepest level of Giddeus\n and destroy the horrible beast\n terrorizing the Yagudo."},
      [10] = {n="The Four Musketeers",d="Mission Orders:\n You are to join a surprise attack\n on the Quadav stronghold in\n Beadeaux.\n See Iron Eater in the President's\n Office for details."},
      [11] = {n="To the Forsaken Mines",d="Mission Orders:\n Bring back a rare ore from the\n Gusgen Mines on the Konschtat\n Highlands.\n First ask Davyad, an adventurer\n residing in the Mines District, how\n he acquired his load of the ore."},
      [12] = {n="Jeuno",d="Mission Orders:\n You are to be sent to work for\n the Embassy of Bastok in Jeuno.\n First obtain a letter of\n recommendation from the\n Presidential Aide, Sir Lucius."},
      [13] = {n="Magicite",d="Mission Orders:\n Capture the three magicites\n in Davoi, Beadeaux, and Castle\n Oztroja to prevent the Shadow\n Lord's return."},
      [14] = {n="Darkness Rising",d="Mission Orders:\n You are to head north to a place\n called Fei'Yin on the Beaucedine\n Glacier.\n Go to the President's Office for a\n full briefing. Naji will show you in."},
      [15] = {n="Xarcabard, Land of Truths",d="Mission Orders:\n You must go to Castle Zvahl in\n Xarcabard.\n The President himself will brief\n you in his office."},
      [16] = {n="Return of the Talekeeper",d="Mission Orders:\n A new Talekeeper is rumored to have\n appeared among the Galka.\n Speak to Medicine Eagle, the Mines\n District guard on post near the\n entrance to Ore Street, for further\n details."},
      [17] = {n="The Pirates' Cove",d="Mission Orders:\n You are being sent to Norg as an\n emissary of Bastok.\n Meet Sir Naji in front of the\n President's Office for a full briefing."},
      [18] = {n="The Final Image",d="Mission Orders:\n You are to investigate the Zilart\n ruins of Ro'Maeve.\n Chief Engineer Cid has more details."},
      [19] = {n="On My Way",d="Mission Orders:\n A search has begun for information\n regarding the whereabouts of the\n missing Galkan elder, Werei.\n The president will brief you on the\n details of this mission."},
      [20] = {n="The Chains That Bind Us",d="Mission Orders:\n The president has ordered a\n full-scale investigation of Zepwell\n Island. You are to travel to the\n Quicksand Caves located beneath\n the Altepa Desert.\n Report to Iron Eater for a briefing."},
      [21] = {n="Enter the Talekeeper",d="Mission Orders:\n You are to investigate the Kuftal\n Tunnel which connects Zepwell\n Island with Cape Teriggan.\n Zeruhn Mines guard Drake Fang will\n provide you with further details."},
      [22] = {n="The Salt of the Earth",d="Mission Orders:\n You have been assigned to an\n investigation in the Vollbow Region.\n Speak with senator Alois for\n further details."},
      [23] = {n="Where Two Paths Converge",d="Mission Orders:\n An adventurer has been attacked\n while on an investigation to\n Xarcabard--and the attacker is\n said to be none other than the\n Dark Knight, Zeid! Report to the\n President's Office for a briefing\n on the situation at hand."},
    }},
    windurst = { name = "Windurst", ids = {
      [0] = {n="The Horutoto Ruins Experiment",d="Mission Orders:\n The Minister of the Orastery\n is conducting an experiment in\n the eastern magic tower of the\n Horutoto Ruins, located in East\n Sarutabaruta.\n Inquire at the Orastery first,\n then go assist him."},
      [1] = {n="The Heart of the Matter",d="Mission Orders:\n Assist the Manustery in the creation\n of Cardians. You must go to the\n southeastern magic tower of the\n Horutoto Ruins in East Sarutabaruta,\n and energize the Mana Orbs that\n serve as the hearts of the Cardians.\n Inquire at the Manustery first for\n details."},
      [2] = {n="The Price of Peace",d="Mission Orders:\n Receive two bags of food offerings\n from the Rhinostery, and deliver\n one bag to each of the Yagudo who\n stand by the altars of offerings in\n Giddeus.\n Don't forget to report back to the\n Rhinostery after completing the\n mission."},
      [3] = {n="Lost for Words",d="Mission Orders:\n There are reports that the Cat\n Burglar has her paws on a \"Book\n of the Gods,\" a restricted book\n that was lost twenty years ago.\n Assist the Optistery in investigating\n the reports, and attempt to retrieve\n the priceless, but dangerous, tome."},
      [4] = {n="A Testing Time",d="Mission Orders:\n Assist the Aurastery's School of\n Magic in the selection of the venue\n for their next skills test.\n They want to record the number of\n monsters you can hunt at a specific\n area, in a set number of days, to\n fairly standardize their skills test."},
      [5] = {n="The Three Kingdoms",d="Mission Orders:\n Determine the state of affairs in\n San d'Oria and Bastok, and render\n assistance on behalf of\n Heavens Tower.\n Inquire at our consulate in each\n country for more information.\n Traveling by ship from Mhaura to\n Selbina is recommended."},
      [6] = {n="The Three Kingdoms (San d'Oria)",d="Mission Orders:\n Go to the highest camp\n in the Ghelsba Outpost\n and defeat Warchief Vatgit."},
      [7] = {n="The Three Kingdoms (Bastok)",d="Mission Orders:\n Survey Bastokan mining technology,\n and retrieve some mythril sand\n from the Palborough Mines.\n An official named Pius will give\n you more detailed orders."},
      [8] = {n="The Three Kingdoms (San d'Oria)",d="Mission Orders:\n Investigate the Yughott Grotto\n deep inside the Ghelsba Outpost."},
      [9] = {n="The Three Kingdoms (Bastok)",d="Mission Orders:\n Something strange is afoot in the\n deepest levels of the Quadav-held\n Palborough Mines.\n Investigate and report.\n An official named Pius will give\n you more detailed orders."},
      [10] = {n="To Each His Own Right",d="Mission Orders:\n On the command of Semih Lafihna,\n captain of the Sibyl Guards, you\n are requested to track down the\n Minister of the Orastery, Ajido-\n Marujido, and discover his true\n intentions.\n Inquire at the Orastery if you lose\n track of him."},
      [11] = {n="Written in the Stars",d="Mission Orders:\n On the command of Zubaba, the head\n lady-in-waiting, you are to journey\n beneath the central magic tower of\n the Horutoto Ruins. There, you are\n to report to the facility managed by\n Heavens Tower, which protects the\n talisman that seals Castle Zvahl.\n Render whatever assistance is\n necessary."},
      [12] = {n="A New Journey",d="Mission Orders:\n As requested by the Star Sibyl,\n you are to render service at the\n Embassy of Windurst in Jeuno.\n Great responsibility and tact are\n required."},
      [13] = {n="Magicite",d="Mission Orders:\n Confiscate the three kinds of\n magicite in Davoi, Beadeaux, and\n Castle Oztroja to prevent the\n resurrection of the Shadow Lord."},
      [14] = {n="The Final Seal",d="Mission Orders:\n On the Star Sibyl's command,\n you are to head north to the\n ruins of Fei'Yin, somewhere on\n the Beaucedine Glacier. There,\n you are to confirm whether\n the final seal is doing its job."},
      [15] = {n="The Shadow Awaits",d="Mission Orders:\n As written in the stars and\n interpreted by the Star Sibyl, you\n are destined to journey to Castle\n Zvahl, which towers over Xarcabard,\n the end of the known lands. There,\n you are to witness what fate has in\n store for our world."},
      [16] = {n="Full Moon Fountain",d="Mission Orders:\n At the request of the Orastery,\n you are to go to the southwestern\n magic tower of the Horutoto Ruins,\n located in West Sarutabaruta. \n Deep within you will find a\n laboratory, where you are ordered\n to switch on the magical gizmo."},
      [17] = {n="Saintly Invitation",d="Mission Orders:\n A mission issued by Heavens\n Tower.\n In reply to the Yagudo Holy One's\n invitation, you are to compete and\n triumph at the contest held at\n Balga's Dais deep within Giddeus."},
      [18] = {n="The Sixth Ministry",d="Mission Orders:\n At the request of the Optistery,\n you are to find former minister\n Karaha-Baruha's laboratory in\n Toraimarai Canal, and delve deeper\n into the mystery of the Book of\n the Gods."},
      [19] = {n="Awakening of the Gods",d="Mission Orders:\n Rhinostery minister Rukususu has\n traveled to Elshimo to investigate\n the facts concerning Iru-Kuiru,\n a researcher from thirty years past.\n The Rhinostery has asked you to\n bring Minister Rukususu back for\n her own safety."},
      [20] = {n="Vain",d="Mission Orders:\n At the request of the Aurastery,\n you are to discover the\n whereabouts of their former\n minister who fled from his duties\n several years ago."},
      [21] = {n="The Jester Who'd Be King",d="Mission Orders:\n The time for the Dark Dungeon\n jailbreak is at hand! At the request\n of the Manustery, you are to\n collect the ministry rings from all\n five ministers."},
      [22] = {n="Doll of the Dead",d="Mission Orders:\n The Orastery Minister has awoken and\n the Bearer of Darkness once again\n terrorizes Heavens Tower. At the\n request of the Manustery you are to\n speak with a person imprisoned within\n the Boyahda Tree and discover the\n truth behind the doll of the dead."},
      [23] = {n="Moon Reading",d="Mission Orders:\n To lure the Bearer of Darkness to the\n Full Moon Fountain, you must collect\n the three verses of the ancient\n people. As her guiding star, the Star\n Sibyl is counting on you to help her\n decide the path for Windurst's future.\n The fate of Windurst rests upon your\n shoulders!"},
    }},
    zilart = { name = "Rise of the Zilart", ids = {
      [0] = {n="The New Frontier",d="Mission Orders:\n Vana'diel is expanding day by day.\n What adventures await you in the\n Outlands?"},
      [2] = {n="The Outlands",d="Mission Orders:\n When parting with Lion after your\n battle at Castle Zvahl, she left you\n with these words:\n \"I hear they'll start flights to the\n  Outlands soon. When they do,\n  come see me in Norg sometime.\""},
      [4] = {n="Welcome t'Norg",d="Mission Orders:\n Lion has someone she wants you to\n meet. She will be waiting for you at\n the room at the end of the hallway \n on the second floor of Norg."},
      [6] = {n="Kazham's Chieftainess",d="Mission Orders:\n Before you travel to the Temple of\n Uggalepih, you are to meet with the\n Kazham chieftainess, Jakoh\n Wahcondalo."},
      [8] = {n="The Temple of Uggalepih",d="Mission Orders:\n The Temple of Uggalepih is an\n ancient place where it is said that\n evil deities were once worshipped.\n Gilgamesh has ordered you to travel\n there and search out a strange, old\n hermit."},
      [10] = {n="Headstone Pilgrimage",d="Mission Orders:\n Somewhere on the island of Zepwell\n lie the remains of an ancient temple."},
      [12] = {n="Through the Quicksand Caves",d="Mission Orders:\n You must hurry to Zepwell Island's\n ancient temple."},
      [14] = {n="The Chamber of Oracles",d="Mission Orders:\n The Chamber of Oracles is said\n to be located in the deepest area\n of the Quicksand Caves."},
      [16] = {n="Return to Delkfutt's Tower",d="Mission Orders:\n Hurry to Delkfutt's Tower and\n stop the Zilartian princes from\n completing their plan to open\n the Gate of the Gods."},
      [18] = {n="Ro'Maeve",d="Mission Orders:\n The Gate of the Gods, Tu'Lia, has\n been restored by Eald'narche. What\n do his words \"Ro'Maeve\" and\n \"blessed by the light\" mean?\n What is Lion's next move?"},
      [20] = {n="The Temple of Desolation",d="Mission Orders:\n On the northernmost point of\n Mindartia and deep within the\n wilderness known as the Sanctuary\n of Zi'Tah lies a body of ruins\n feared by many:\n Ro'Maeve, the Temple of Desolation."},
      [22] = {n="The Hall of the Gods",d="Mission Orders:\n A strange grate prohibits you from\n journeying deeper into the Hall of\n the Gods. The depression in the\n center may be the key to getting\n through. You should probably report\n this find to Gilgamesh."},
      [23] = {n="The Mithra and the Crystal",d="Mission Orders:\n According to Gilgamesh, a Mithra\n carrying a mysterious crystal she\n found in Zi'Tah was recently in Norg.\n Her name was something like Mary\n or Maroo or Maree..."},
      [24] = {n="The Gate of the Gods",d="Mission Orders:\n The path to Tu'Lia has opened!"},
      [26] = {n="Ark Angels",d="Mission Orders:\n Apathy, arrogance, cowardice, envy,\n rage--the darkness that lurks within\n us all..."},
      [27] = {n="The Sealed Shrine",d="Mission Orders:\n The door deep within the Shrine\n of Ru'Avitau is sealed with some\n form of supernatural power. Could\n this be the work of Eald'narche?"},
      [28] = {n="The Celestial Nexus",d="Mission Orders:\n The fate of Vana'diel awaits you\n in the Celestial Nexus!"},
      [30] = {n="Awakening",d="Mission Orders:\n And so ends another chapter in\n the neverending tale of Vana'diel.\n However, as long as there are those\n who are lured by the thoughts of\n Paradise, the wheels of destiny will\n continue to turn."},
      [31] = {n="The Last Verse",d="�@"},
      [1000] = {n="To Commence RotZ",d="Examine the Tales' Beginning\n in Norg (H-9)."},
    }},
    cop = { name = "Chains of Promathia", ids = {
      [101] = {n="Ancient Flames Beckon"},
      [110] = {n="The Rites of Life",d="Mission Orders:\n Brilliant lights, fearsome beasts,\n a mysterious laboratory... What\n do all these have to do with the\n strange boy brought back to\n Doctor Monberaux's clinic\n in Upper Jeuno?",s={"The Rites of Life"}},
      [118] = {n="Below the Arks",d="Mission Orders:\n Something is afoot. Travel to\n the Grand Duke Palace to learn\n details of recent events.",s={"Below the Arks"}},
      [128] = {n="The Mothercrystals",d="Mission Orders:\n The first mothercrystal has been\n tainted with Emptiness. Hurry to\n the remaining crags to find out\n if any other stones have met the\n same fate.",s={"The Mothercrystals"}},
      [137] = {n="The Isle of Forgotten Saints"},
      [138] = {n="An Invitation West",d="Mission Orders:\n You have woken up in some\n unknown land, only to find your\n amulet has been stolen by a\n group of three Tarutaru. You\n think they may have run off\n somewhere to the west.",s={"An Invitation West"}},
      [218] = {n="The Lost City",d="Mission Orders:\n According to its inhabitants, the\n Tavnazian Safehold was carved\n out of solid rock by survivors of\n the Great War. Speak with the\n city's inhabitants to learn more\n of their grave situation.",s={"The Lost City"}},
      [228] = {n="Distant Beliefs",d="Mission Orders:\n You have volunteered to journey\n into the Phomiuna Aqueducts to\n defeat the minotaur.\n It appears that Nag'molada has\n set off ahead of you.",s={"Distant Beliefs"}},
      [238] = {n="An Eternal Melody",d="Mission Orders:\n You must meet with the young\n Elvaan leader of the Tavnazian\n Patrol and have her return your\n amulet. You must also try to find\n a woman named Ulmia...",s={"An Eternal Melody"}},
      [248] = {n="Ancient Vows",d="Mission Orders:\n Follow Prishe to Cape Riverne on\n the Misareaux Coast. It is\n rumored a wyrm nests there...",s={"Ancient Vows"}},
      [257] = {n="A Transient Dream"},
      [258] = {n="The Call of the Wyrmking",d="Mission Orders:\n Not moments after arriving in\n Bastok, Prishe begins her search\n for the father of airships, Cid.",s={"The Call of the Wyrmking"}},
      [318] = {n="A Vessel Without a Captain",d="Mission Orders:\n Prishe has left for the\n Tenshodo in Jeuno to find\n her acquaintance, Grezzo.\n A visit to the Grand Duke\n Palace may also be necessary...",s={"A Vessel Without a Captain"}},
      [325] = {n="The Road Forks",d="Mission Orders:\n To capture the mysterious boy,\n you must first locate the fourth\n mothercrystal. To do this, you\n have been ordered to travel to\n the nations of Bastok, Windurst,\n and San d'Oria to learn of the\n Multinational Expedition that was\n held nearly thirty years ago.",s={"The Road Forks"}},
      [330] = {n="Emerald Waters",d="Mission Orders:\n You must try to find information\n regarding the San d'Orian\n representative on the\n Multinational Expedition,\n Francmage M Mistalle.",s={"Emerald Waters"}},
      [331] = {n="Vicissitudes",d="Mission Orders:\n Ulmia has set off for the\n San d'Orian Cathedral.\n Try and catch up with her.",s={"Vicissitudes"}},
      [335] = {n="Descendants of a Line Lost",d="Mission Orders:\n You have learned that Francmage\n M Mistalle was the head of the\n Knights Mistalle, who own the\n land surrounding Carpenters'\n Landing.",s={"Descendants of a Line Lost"}},
      [339] = {n="Louverance",d="Mission Orders:\n According to the Royal Knight\n known as Louverance, Countess\n Hinaree, living in Southern\n San d'Oria, knows much of the\n Knights Mistalle.",s={"Louverance"}},
      [340] = {n="Memories of a Maiden",d="Mission Orders:\n You must try to find information\n regarding the Windurstian\n representative on the\n Multinational Expedition, former\n Rhinostery minister Iru-Kuiru.",s={"Memories of a Maiden"}},
      [341] = {n="Comedy of Errors, Act I",d="Mission Orders:\n While you are searching for\n answers to the mysteries\n surrounding the Multinational\n Expedition, the Chebukki\n brothers are searching for their\n father. If you wish to learn of\n the former Rhinostery minister,\n you should probably go to the\n Rhinostery.",s={"Comedy of Errors, Act I"}},
      [345] = {n="Comedy of Errors, Act II",d="Mission Orders:\n Thanks to the Chebukkis, Yoran-\n Oran has begun going insane.\n It looks like their next victim is\n someone very rich...",s={"Comedy of Errors, Act II"}},
      [349] = {n="Exit Stage Left",d="Mission Orders:\n Yoran-Oran has begun his repairs\n on the Mimeo Mirror. Use this\n time to try and find where the\n Chebukki brothers have run off\n to.",s={"Exit Stage Left"}},
      [350] = {n="Tending Aged Wounds",d="Mission Orders:\n You have learned that the\n Multinational Expedition was\n originally organized by the\n Republic of Bastok. Perhaps\n Cid knows something more...",s={"Tending Aged Wounds"}},
      [358] = {n="Darkness Named",d="Mission Orders:\n Prishe has been taken to Doctor\n Monberaux's clinic! What ails her\n fragile body and what, if\n anything, can save her!?",s={"Darkness Named"}},
      [367] = {n="The Cradles of Children Lost"},
      [368] = {n="Sheltering Doubt",d="Mission Orders:\n Prishe has returned to Tavnazia,\n and it would be wise to follow.\n The winds of twenty years past\n have once again begun to swirl\n about the islands. What evils do\n these winds carry?",s={"Sheltering Doubt"}},
      [418] = {n="The Savage",d="Mission Orders:\n Ulmia is determined to know the\n truth, and is ready to revisit\n Bahamut to learn it. Enlist the\n aid of Tenzen and Justinius to\n help you find Ulmia before\n something terrible occurs.",s={"The Savage"}},
      [428] = {n="The Secrets of Worship",d="Mission Orders:\n Now that you have learned the\n Wyrmking's plan, you must travel\n to the fourth mothercrystal.\n Nag'molada has informed you\n where the stone lies. However,\n you will need the amulet you lent\n to Prishe before you are to make\n your way there.",s={"The Secrets of Worship"}},
      [438] = {n="Slanderous Utterings",d="Mission Orders:\n Appalled that Prishe would even\n think of laying her hands on the\n statue of Promathia, the elder,\n Despachiaire, has called her to\n his quarters for punishment. If\n Prishe is banished from the\n safehold, you may be unable to\n retrieve the amulet you need to\n find the fourth mothercrystal.",s={"Slanderous Utterings"}},
      [447] = {n="The Return Home"},
      [448] = {n="The Enduring Tumult of War",d="Mission Orders:\n The airship piloted by\n Louverance did not arrive\n in San d'Oria, but Port Bastok.\n How much longer will Nag'molada\n wait for your arrival at the\n northwestern tower of Pso'Xja?",s={"The Enduring Tumult of War"}},
      [518] = {n="Desires of Emptiness",d="Mission Orders:\n The Emptiness has trapped you\n and your companions. You must\n find them before you are able to\n continue your journey into the\n depths of Promyvion.",s={"Desires of Emptiness"}},
      [530] = {n="Three Paths",d="Mission Orders:\n To break the Wyrmking's pact, you\n must locate the Keeper of the\n Apocalypse as quickly as possible.\n To do that you must first learn\n more of Al'Taieu, as well as find\n Prishe and the mysterious boy.",s={"Three Paths"}},
      [540] = {n="Past Sins",d="Mission Orders:\n Louverance has set off on his\n investigation into the celestial\n capital of Al'Taieu.",s={"Past Sins"}},
      [542] = {n="Southern Legend",d="Mission Orders:\n The painting of Al'Taieu that is\n kept in the Sacrarium actually\n once belonged to the Mithra.\n To learn more of the relic's\n history, you must travel to\n Windurst and speak with the\n chieftainness, Perih Vashai.",s={"Southern Legend"}},
      [543] = {n="Partners Without Fame",d="Mission Orders:\n According to Honoi-Gomoi,\n Louverance has left to meet\n someone on a small island\n located to the southeast of\n Mhaura. Who is this person he\n seeks out, and what relation\n does he have with Al'Taieu?",s={"Partners Without Fame"}},
      [546] = {n="A Century of Hardship",d="Mission Orders:\n A path to the celestial capital\n that only opens once every one\n hundred years... Where is this\n path, and can Louverance find it?",s={"A Century of Hardship"}},
      [549] = {n="Departures",d="Mission Orders:\n You were able to enlist the aid\n of the Galka who has been living\n in Movalpolos for the past\n hundred years; however, it was\n not long before the Moblins came\n to take him back to their city.\n Could it truly be that people and\n beastmen are destined for an\n eternity of strife?",s={"Departures"}},
      [550] = {n="The Pursuit of Paradise",d="Mission Orders:\n Tenzen left for the La Theine\n Plateau to seek out the\n terrestrial avatar Carbuncle,\n and request his assistance in\n your battle with the Emptiness.",s={"The Pursuit of Paradise"}},
      [552] = {n="Spiral",d="Mission Orders:\n With the aid of Carbuncle, the\n power of the Phoenix Blade will\n supposedly increase dramatically.\n However, you must first travel to\n Pso'Xja.",s={"Spiral"}},
      [553] = {n="Branded",d="Mission Orders:\n Currently, ducal officials are\n busy with preparations to battle\n the Wyrmking, Bahamut. Return\n to Jeuno in order to track down\n the mysterious boy.",s={"Branded"}},
      [556] = {n="Pride and Honor",d="Mission Orders:\n Will Captain Wolfgang read the\n letter from Doctor Monberaux?\n Will he sympathize with your\n cause and provide you with the\n key to the laboratory below\n Delkfutt's Tower?",s={"Pride and Honor"}},
      [559] = {n="And the Compass Guides",d="Mission Orders:\n Though the words of Nag'molada\n have reinstated fear and despair\n into the heart of Tenzen, he is\n determined to continue his\n journey to Pso'Xja and find the\n guardian of the moon, Fenrir.",s={"And the Compass Guides"}},
      [560] = {n="Where Messengers Gather",d="Mission Orders:\n Ulmia has journeyed to San d'Oria\n to search for any word on the\n whereabouts of Prishe.",s={"Where Messengers Gather"}},
      [562] = {n="Entanglement",d="Mission Orders:\n Lady Hinaree has informed you\n that High Priest Chasalvige has\n an important message for Ulmia\n regarding Prishe. Hurry to Port\n San d'Oria and accompany Ulmia\n back to the cathedral.",s={"Entanglement"}},
      [564] = {n="Head Wind",d="Mission Orders:\n Clues to help you on your\n journey may be found in\n Windurst's Rhinostery. Could\n Prishe be nearby? And what\n of the dangerous figures that\n track her? Is a battle between\n them inevitable?",s={"Head Wind"}},
      [568] = {n="Flames for the Dead",d="Mission Orders:\n Prishe has run off to the\n Uleguerand Range. Why has she\n gone to this desolate place?\n What truths does she seek?",s={"Flames for the Dead"}},
      [577] = {n="Echoes of Time"},
      [578] = {n="For Whom the Verse Is Sung",d="Mission Orders:\n Prishe has been spotted in\n Jeuno! Journey to the Grand\n Duke Palace to learn more of her\n whereabouts--before Ulmia is\n overcome by worry for her\n long-time friend.",s={"For Whom the Verse Is Sung"}},
      [618] = {n="A Place to Return",d="Mission Orders:\n Cardinal Mildaurion is somewhere\n in Jeuno, and Ulmia is desperate\n to find out where she may be\n hiding. Perhaps the three\n \"high-ranking\" Tarutaru\n \"officials\" know something...",s={"A Place to Return"}},
      [628] = {n="More Questions Than Answers",d="Mission Orders:\n Esha'ntarl has returned to the\n Grand Duke Palace and is\n preparing the Jeuno Armada for\n its attack on Bahamut. At the\n same time, Prishe and Ulmia have\n finally solved the mystery that\n has been haunting them for the\n past twenty years.",s={"More Questions Than Answers"}},
      [638] = {n="One to Be Feared",d="Mission Orders:\n The fifth verse of \"Memoria de la\n S^tona\" has been discovered.\n Now, with the help of Cid, you\n must fly beyond the sea of\n clouds and face Bahamut for\n what may be the final time...",s={"One to Be Feared"}},
      [647] = {n="In the Light of the Crystal"},
      [648] = {n="Chains and Bonds",d="Mission Orders:\n You have escaped the wrath of\n Bahamut, but what of your\n companions? Could they already\n be back within the safehold?",s={"Chains and Bonds"}},
      [718] = {n="Flames in the Darkness",d="Mission Orders:\n Tenzen is nowhere to be found.\n You must locate him before\n returning to Jeuno to meet with\n Esha'ntarl.",s={"Flames in the Darkness"}},
      [728] = {n="Fire in the Eyes of Men",d="Mission Orders:\n Travel to the Moblin city of\n Movalpolos to find a path to the\n fifth and final mothercrystal.",s={"Fire in the Eyes of Men"}},
      [738] = {n="Calm Before the Storm",d="Mission Orders:\n The crystal propulsion unit of Cid's\n airship has been damaged. You are\n to call Louverance back from\n Carpenters' Landing, and Shikaree Z\n from Bibiki Bay. You must also find\n the Chebukki siblings in Tavnazia\n and retrieve the vessel of light.",s={"Calm Before the Storm"}},
      [748] = {n="The Warrior's Path",d="Mission Orders:\n Board the newly repaired airship\n and head for the fifth mothercrystal.\n Will your path be intercepted by\n Nag'molada? The dreadful wyrms?\n Or a completely unexpected\n opponent...?",s={"The Warrior's Path"}},
      [758] = {n="Emptiness Bleeds"},
      [800] = {n="Garden of Antiquity",d="Mission Orders:\n The celestial capital of Al'Taieu\n truly exists. Though vastly altered\n during the ten thousand-year span\n of their seclusion, the ancients\n remain alive in the city. Nag'molada\n heads for the palace, while you and\n your companions follow in his wake...",s={"Garden of Antiquity"}},
      [818] = {n="A Fate Decided",d="Mission Orders:\n Nag'molada has descended into the\n depths of the palace in search of\n the Chamber of Eventide.\n Join Prishe in her pursuit of the\n Kuluu diplomat.",s={"A Fate Decided"}},
      [828] = {n="When Angels Fall",d="Mission Orders:\n The Gate of the Gods--the portal\n leading to the highest level of the\n palace--has opened. While your\n companions scramble to reach the\n audience chamber, you must find\n which of the five towers will return\n you into the light...",s={"When Angels Fall"}},
      [840] = {n="Dawn",d="Mission Orders:\n Revelations of truth accompany the\n awakening of Promathia. The world\n and its people stand in the twilight\n of the apocalypse.\n Dawn Goddess Altana, grant us\n victory!",s={"Dawn"}},
      [850] = {n="The Last Verse",s={"The Last Verse"}},
      [1000] = {n="To Begin CoP...",d="Examine the Tales' Beginning\n in Lower Delkfutt's Tower\n (H-10)."},
    }},
    assault = { name = "Assault", ids = {
      [1] = {n="Leujaoam Cleansing",d="Area: Leujaoam Sanctum\nObjective: Remove all threats\nRecruitment: Lv.50, 1-6 mercenaries\nMission Orders:\n General Afkaam is to inspect\n Leujaoam Sanctum. Destroy all\n creatures in the area that may\n pose a threat to the general."},
      [2] = {n="Orichalcum Survey",d="Area: Leujaoam Sanctum\nObjective: Discover orichalcum ore\nRecruitment: Lv.50, 1-6 mercenaries\nMission Orders:\n There is a rumor that orichalcum\n ore has been discovered in\n Leujaoam Sanctum. Find the ore\n vein before the beastmen do."},
      [3] = {n="Escort Professor Chanoix",d="Area: Leujaoam Sanctum\nObjective: Protect the professor\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n A longhaired marid has been\n found frozen in the eternal ice\n of Leujaoam Sanctum. Escort\n Professor Clavauert B Chanoix\n to the site of the discovery."},
      [4] = {n="Shanarha Grass Conservation",d="Area: Leujaoam Sanctum\nObjective: Protect the vegetation\nRecruitment: Lv.50, 1-6 mercenaries\nMission Orders:\n Rabbits are sending shanarha grass,\n unique to the Leujaoam Sanctum,\n to the verge of extinction. Drive\n away the rabbits and protect the\n vegetation."},
      [5] = {n="Counting Sheep",d="Area: Leujaoam Sanctum\nObjective: Buy black sheep\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n The Imperial Army on the eastern\n front is being hit by a peculiar cold\n wave, and warm uniforms are in\n short supply. Buy as many sheep as\n you can from the markets in\n Leujaoam and save the troops."},
      [6] = {n="Supplies Recovery",d="Area: Leujaoam Sanctum\nObjective: Retrieve the supplies\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n A logistics unit headed to the front\n lines of the war with the Far East\n was attacked and their supplies were\n stolen. The enemy then fled toward\n Leujaoam Sanctum. An Immortals\n unit will also join in the recovery."},
      [7] = {n="Azure Experiments",d="Area: Leujaoam Sanctum\nObjective: Become a test subject\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n The Imperial alchemists have\n developed various tissues to graft\n onto and strengthen the bodies of\n the Immortals, but they need test\n subjects for clinical experiments.\n Go lend your assistance."},
      [8] = {n="Imperial Code",d="Area: Leujaoam Sanctum\nObjective: Retrieve the OGMA\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n The Empire's mercury cipher (OGMA)\n has been stolen by a group of Far\n Eastern spies. With it, our enemies\n will be able to decrypt top-secret\n military orders, thus severely\n compromising Imperial safety.\n You are to intercept the enemy\n as they transport the device."},
      [9] = {n="Red Versus Blue",d="Area: Leujaoam Sanctum\nObjective: Defeat Raubahn\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n Joint battle exercises are to be\n carried out between the Immortals\n (blue) and the Inexorables (red).\n You have been assigned to assist\n the red team. The first side to\n defeat the leader of the other will\n be declared victor."},
      [10] = {n="Bloody Rondo",d="Area: Leujaoam Sanctum\nObjective: Defeat the count\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n After years of quietly defying\n Imperial rule, the recluse Count\n Dracula has recently begun\n preparations for an assault on\n Al Zahbi. Infiltrate the Leujaoam\n Sanctum, locate the count, and\n slay him before he can execute\n his plans."},
      [11] = {n="Imperial Agent Rescue",d="Area: Mamool Ja Training Grounds\nObjective: Rescue the agent\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n An agent sent to spy on the\n secret training grounds of the\n Mamool Ja has been captured.\n Rescue him before he is\n interrogated for Imperial secrets."},
      [12] = {n="Preemptive Strike",d="Area: Mamool Ja Training Grounds\nObjective: Destroy the assassins\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n A unit of Mamool Ja soldiers is\n training in assassination techniques.\n Destroy them before they can\n become a threat to the Empress."},
      [13] = {n="Sagelord Elimination",d="Area: Mamool Ja Training Grounds\nObjective: Defeat Sagelord Molaal Ja\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n Sagelord Molaal Ja is visiting the\n training grounds to oversee the\n progress of the soldiers. His\n elimination would sow chaos and\n confusion in the Mamool Ja ranks."},
      [14] = {n="Breaking Morale",d="Area: Mamool Ja Training Grounds\nObjective: Steal the supplies\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n Scouts report that the new Mamool\n Ja soldiers have received supplies\n from their families. Destroy Mamool\n Ja morale by stealing these supplies\n while being careful to remain\n undetected."},
      [15] = {n="The Double Agent",d="Area: Mamool Ja Training Grounds\nObjective: Apprehend the spy\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n There is a double agent among the\n Imperial Qiqirn spies in the\n Mamool Ja Training Grounds.\n Find him before he puts the other\n spies in danger."},
      [16] = {n="Imperial Treasure Retrieval",d="Area: Mamool Ja Training Grounds\nObjective: Recover the treasure\nRecruitment: Lv.50, 1-6 mercenaries\nMission Orders:\n A puk recently stole a treasure box\n containing enchanted gems from the\n royal treasury. The gems were then\n given to Mamool Ja officers as a\n reward for duty. Find and retrieve\n the treasure."},
      [17] = {n="Blitzkrieg",d="Area: Mamool Ja Training Grounds\nObjective: Annihilate the enemy\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n After shedding their skins, the\n Mamool Ja gather for a festival\n to celebrate their new scales and\n dance until exhausted. This is a\n prime opportunity to catch them off\n guard!"},
      [18] = {n="Marids in the Mist",d="Area: Mamool Ja Training Grounds\nObjective: Neutralize the marids\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n Our agents have informed us that\n the Mamool Ja have been training\n marids to use during sieges on the\n Empire. You are to locate these\n deadly beasts and capture or\n eliminate them before it's too late."},
      [19] = {n="Azure Ailments",d="Area: Mamool Ja Training Grounds\nObjective: Gather pathological data\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n To protect against an outbreak of\n the dreaded kraken flu, data is\n required on the effects of the\n disease. Healthy volunteers are\n wanted to travel to the Mamool Ja\n Training Grounds and collect\n important samples."},
      [20] = {n="The Susanoo Shuffle",d="Area: Mamool Ja Training Grounds\nObjective: Defeat Orochi\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n In an attempt to strengthen their\n bonds with the Mamool Ja, an\n eastern nation has provided the\n beastmen with a new biologically\n engineered hydra hybrid known as\n Orochi. You are to infiltrate the\n training grounds and eliminate the\n new threat."},
      [21] = {n="Excavation Duty",d="Area: Lebros Cavern\nObjective: Remove the obstructions\nRecruitment: Lv.50, 1-6 mercenaries\nMission Orders:\n The Imperial Army plans to traverse\n Lebros Cavern as part of their\n attack on Halvung, however the\n tunnels are blocked with rocks.\n You must remove the obstructions."},
      [22] = {n="Lebros Supplies",d="Area: Lebros Cavern\nObjective: Deliver the provisions\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n An advance unit sent into Lebros\n Cavern has met heavy resistance\n and is in need of reprovisioning.\n Your mission is to deliver rations to\n each member of the advance unit."},
      [23] = {n="Troll Fugitives",d="Area: Lebros Cavern\nObjective: Destroy the Troll fugitives\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n The remnants of a Troll army that\n clashed with Imperial forces has\n taken refuge within Lebros Cavern.\n Hunt down the fugitives and\n prevent them from regrouping."},
      [24] = {n="Evade and Escape",d="Area: Lebros Cavern\nObjective: Discover alternate route\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n The unit deployed within Lebros\n Cavern is in danger of being\n overwhelmed by the well-positioned\n enemy. Discover an alternate route\n so they can retreat in safety."},
      [25] = {n="Siegemaster Assassination",d="Area: Lebros Cavern\nObjective: Assassinate Borgerlur\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n The Trolls have recruited Borgerlur,\n a siege specialist from central\n Aradjiah. The Empire cannot allow\n him to take control of the Troll\n army. Find and eliminate Borgerlur\n as he travels through Lebros Cavern."},
      [26] = {n="Apkallu Breeding",d="Area: Lebros Cavern\nObjective: Match the apkallu\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n Due to their intelligence and ability\n to travel through both water and on\n land, the rare Lebros Apkallu is\n prized by the navy as a messenger\n bird. Help increase their numbers\n by pairing them up."},
      [27] = {n="Wamoura Farm Raid",d="Area: Lebros Cavern\nObjective: Remove the threat\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n The enemy has begun raising\n swarms of wamoura in the Lebros\n Cavern. If they reach adulthood,\n they would present a formidable\n threat. Infiltrate the Lebros Cavern\n and destroy them."},
      [28] = {n="Egg Conservation",d="Area: Lebros Cavern\nObjective: Drive out the hunters\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n There have been reports that Qiqirn\n hunters have been collecting the\n eggs of our army's messenger\n apkallus. You are to join forces\n with the male apkallus in the area\n and eliminate the invading Qiqirn\n while protecting the females and\n their eggs."},
      [29] = {n="Operation: Black Pearl",d="Area: Lebros Cavern\nObjective: Rescue Princess Kadjaya\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n A ship carrying Princess Kadjaya of\n the Imperial family back from a\n diplomatic mission to the West has\n run aground near the Lebros\n Cavern. You are to find the\n survivors and escort them to safety."},
      [30] = {n="Better than One",d="Area: Lebros Cavern\nObjective: Defeat Black Shuck\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n Recently there have been multiple\n reports of a three-headed beast\n attacking traders en route to Al\n Zahbi. You are to travel to its\n rumored lair in the Lebros Cavern\n and slay the monster."},
      [31] = {n="Seagull Grounded",d="Area: Periqia\nObjective: Escort the prisoner\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n The Immortals have captured a\n member of the Seagull Phratrie, a\n rebel organization. You are to\n escort the prisoner safely to a\n holding area."},
      [32] = {n="Requiem",d="Area: Periqia\nObjective: Destroy the undead\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n An Immortal has reported the\n existence of a large force of\n undead soldiers. Destroy these\n undead minions before they can\n organize an attack on the Empire."},
      [33] = {n="Saving Private Ryaaf",d="Area: Periqia\nObjective: Find the survivors\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n A squad sent in to search for the\n Seagull Phratrie hideout has failed\n to report. Find any survivors,\n especially one Private Ryaaf, a\n relative of the Galeserpent General."},
      [34] = {n="Shooting Down the Baron",d="Area: Periqia\nObjective: Eliminate the Black Baron\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n An imp known as the Black Baron\n has hit Periqia like a meteor strike,\n single-handedly defeating 79\n Imperial soldiers. The Empire cannot\n suffer any more losses. It is time\n for the Baron to meet his end."},
      [35] = {n="Building Bridges",d="Area: Periqia\nObjective: Activate the bridge\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n Thanks to the enemy destroying a\n bridge along the path of their\n attack, the unit assaulting Periqia\n is at an impasse. Find and activate\n the backup bridge mechanism\n rumored to be hidden in the area."},
      [36] = {n="Stop the Bloodshed",d="Area: Periqia\nObjective: Exterminate the chigoes\nRecruitment: Lv.50, 1-6 mercenaries\nMission Orders:\n The Lamiae are preparing to release\n swarms of chigoes in Al Zahbi to\n collect blood samples. Destroy the\n chigoes and thwart their plan."},
      [37] = {n="Defuse the Threat",d="Area: Periqia\nObjective: Clear the mine fields\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n The Lamiae have hired Qiqirn\n demolition experts to set land mines\n in Periqia. You must eliminate this\n hazard for the soldiers."},
      [38] = {n="Operation: Snake Eyes",d="Area: Periqia\nObjective: Locate the generals\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n Generals Karazahm and Umarid of\n the Imperial Army's Arrapago\n division have disappeared from\n camp headquarters while on a\n mission on Sharug Isle. There is a\n high possibility that the two have\n been kidnapped by members of the\n Undead Swarm."},
      [39] = {n="Wake the Puppet",d="Area: Periqia\nObjective: Retrieve the Mark-IIs\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n During a previous mission to\n eradicate the Undead Swarm\n presence from Periqia, the Imperial\n forces were forced to abandon\n several Mark-II automatons upon\n their retreat. You are to infiltrate\n the area, locate the machines, and\n aid in their return to Al Zahbi."},
      [40] = {n="The Price Is Right",d="Area: Periqia\nObjective: Assassinate King Goldemar\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n Intelligence reports that the dvergr\n king, Goldemar, is planning the sale\n of forbidden magicked weapons to\n the area's beastmen factions. You\n are to locate the king and eliminate\n him before the deal is made."},
      [41] = {n="Golden Salvage",d="Area: Ilrusi Atoll\nObjective: Recover the figurehead\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n Rumor has it that the golden\n figurehead from the Black Coffin,\n the ship of the pirate Luzaf, can\n be found somewhere within Ilrusi\n Atoll."},
      [42] = {n="Lamia No.13",d="Area: Ilrusi Atoll\nObjective: Eliminate Lamia No.13\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n Your mission is to hunt down\n Lamia No.13, a fearsome creature\n known to have performed vile\n experiments on the countless\n corpses of her enemies."},
      [43] = {n="Extermination",d="Area: Ilrusi Atoll\nObjective: Exterminate all monsters\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n The vermin feasting on the corpses\n left behind by the Lamiae have\n multiplied to unnatural numbers.\n Destroy this threat to the\n surrounding ecology."},
      [44] = {n="Demolition Duty",d="Area: Ilrusi Atoll\nObjective: Demolish the shipwrecks\nRecruitment: Lv.50, 1-6 mercenaries\nMission Orders:\n A confidential report states that\n corsairs are secretly collecting the\n remains of shipwrecks on the Ilrusi\n Atoll. Use the automaton issued to\n you by the on-site engineer to\n demolish these shipwrecks."},
      [45] = {n="Searat Salvation",d="Area: Ilrusi Atoll\nObjective: Save the Qiqirn divers\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n Qiqirn divers assigned the duty of\n demolishing wrecks on the Ilrusi\n Atoll have run into a problem with\n the local wildlife. Lead them back\n to safety before they decide to\n abandon their work."},
      [46] = {n="Apkallu Seizure",d="Area: Ilrusi Atoll\nObjective: Capture the apkallu\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n Famous zoologist Professor\n Chanoix is researching apkallu\n on Ilrusi Atoll. The more discoveries\n he makes in Aht Urhgan, the more\n likely he is to join the Empire.\n Assist him by capturing apkallu."},
      [47] = {n="Lost and Found",d="Area: Ilrusi Atoll\nObjective: Find the ring\nRecruitment: Lv.60, 1-6 mercenaries\nMission Orders:\n The Empress's uncle Bashalab\n visited Ilrusi Atoll in secret and\n lost his ring, the \"Eye of Zahak.\"\n Escort the royal family's hired agent\n through Ilrusi Atoll and find his\n lost ring."},
      [48] = {n="Deserter",d="Area: Ilrusi Atoll\nObjective: Locate the agents\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n Agents of our Anti-Corsair Task\n Force have gone AWOL and are hiding\n somewhere in Ilrusi. Your mission is\n to swiftly disarm the deviants and\n take them into custody.\n All information on these criminals is\n highly classified and any disclosure\n of their identity is strictly prohibited."},
      [49] = {n="Desperately Seeking Cephalopods",d="Area: Ilrusi Atoll\nObjective: Collect ahtapot\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n To increase production of special\n nighttime camouflage, the Imperial\n marines require large quantities of\n a secretion from a rare cephalopod\n known as the ahtapot, found in\n the Ilrusi Atoll."},
      [50] = {n="Bellerophon's Bliss",d="Area: Ilrusi Atoll\nObjective: Defeat Khimaira 14X\nRecruitment: Lv.70, 1-6 mercenaries\nMission Orders:\n Troll mercenary leader Martial\n Maestro Megomak has completed\n his newest creation, the Khimaira\n 14X, and taken it to the Ilrusi Atoll\n for combat testing.\n You are to locate the abomination\n and exterminate it."},
      [51] = {n="Nyzul Isle Investigation",d="Area: Nyzul Isle\nObjective: Complete on-site objectives\nRecruitment: Lv.75, 1-6 mercenaries\nMission Orders:\n You are to scout out the remnants\n before the A.A.R.I. sends an official\n research team. No rewards are\n offered for these unofficial missions."},
      [52] = {n="Nyzul Isle Uncharted Area Survey",d="Area: Nyzul Isle\nObjective: Complete on-site objectives\nRecruitment: Lv.99, 1-6 mercenaries\nMission Orders:\n You are to scout unexplored regions\n in preparation for the arrival of the\n A.A.R.I. research team. No rewards are\n offered for this classified operation."},
    }},
    toau = { name = "Treasures of Aht Urhgan", ids = {
      [0] = {n="Land of Sacred Serpents",d="Mission Orders:\n A land of new adventures lies to the\n east of Mindartia. What splendors and\n terrors await the curious...?"},
      [1] = {n="Immortal Sentries",d="Mission Orders:\n Deliver a package to one of the\n Immortals found at the staging points\n and Naja will consider you for a\n mercenary contract."},
      [2] = {n="President Salaheem",d="Mission Orders:\n You have become an employee of\n Salaheem's Sentinels. Becoming a\n mercenary is not quite what you\n expected..."},
      [3] = {n="Knight of Gold",d="Mission Orders:\n Bring Raillefal back to Salaheem's\n Sentinels and help teach him the\n proper attitude for a mercenary."},
      [4] = {n="Confessions of Royalty",d="Mission Orders:\n Deliver Raillefal's letter to\n Halver in the Chateau d'Oraguille."},
      [5] = {n="Easterly Winds",d="Mission Orders:\n An international summit is to be held\n in Jeuno. You have been called upon\n to speak of what you have witnessed\n in the Empire of Aht Urhgan."},
      [6] = {n="Westerly Winds",d="Mission Orders:\n You have been assigned the task of\n infiltrating the inner political circle\n of the Empire as an agent of the\n allied forces. Report to Raillefal."},
      [7] = {n="A Mercenary Life",d="Mission Orders:\n President Naja is all fired up and\n eager to see you complete as many\n missions as you can..."},
      [8] = {n="Undersea Scouting",d="Mission Orders:\n You have been requested to enter\n the Alzadaal Undersea Ruins from\n Bhaflau Thickets and patrol the\n interior."},
      [9] = {n="Astral Waves",d="Mission Orders:\n Ghatsad has entrusted you with a\n device capable of detecting astral\n waves. Return to Salaheem's\n Sentinels and report your progress."},
      [10] = {n="Imperial Schemes",d="Mission Orders:\n The reward from the A.A.R.I. has\n been confiscated by President Naja\n to cover your \"fines.\"\n The mercenary life is no picnic..."},
      [11] = {n="Royal Puppeteer",d="Mission Orders:\n Under the command of the court\n puppetmaster, you are to uncover\n the truth behind the ghost ship,\n the Ashu Talif.\n Investigate the Arrapago Islands."},
      [12] = {n="Lost Kingdom",d="Mission Orders:\n Pyopyoroon of Nashmau has\n advised you to head west to a\n place with many \"stooones\" to find\n a special \"ghooost.\"\n Perhaps it will lead you to the\n ghost ship..."},
      [13] = {n="The Dolphin Crest",d="Mission Orders:\n In a cemetery on Azouph Isle, you\n have found an ancient coin bearing\n an unfamiliar crest. Report your\n meeting with the ghost to President\n Naja."},
      [14] = {n="The Black Coffin",d="Mission Orders:\n A mercenary colleague has reported\n feeling an ominous presence to the\n west of Dvucca Isle..."},
      [15] = {n="Ghosts of the Past",d="Mission Orders:\n You have uncovered the truth\n behind the Ashu Talif and its\n ghostly crew. Report your findings\n to President Naja."},
      [16] = {n="Guests of the Empire",d="Mission Orders: You have received\n an invitation to the palace from\n the Grand Vizier. President Naja\n has offered to help you find\n appropriate clothing for the\n occasion."},
      [17] = {n="Passing Glory",d="Mission Orders:\n Your reward from the Empress has\n been confiscated by President Naja.\n Earn the right to wear it by\n becoming the best mercenary you\n can be."},
      [18] = {n="Sweets for the Soul",d="Mission Orders:\n Ambassador Karababa has arrived\n from the Federation of Windurst.\n The planned festivities turn into\n puppet rivalry, and the insulted\n ambassador bypasses the palace\n in favor of a visit to the Shararat\n Teahouse."},
      [19] = {n="Teahouse Tumult",d="Mission Orders:\n You have been asked to guide Lady\n Karababa to the Olduum ruins found\n in the tunnels of the Aydeewa\n Subterrane. How will Naja react to\n your freelancing? And what are\n Aphmau and friends planning...?"},
      [20] = {n="Finders Keepers",d="Mission Orders:\n After snatching the Olduum artifact,\n Lady Karababa has left for\n Salaheem's Sentinels.\n What business could she possibly\n have with a mercenary company?"},
      [21] = {n="Shield of Diplomacy",d="Mission Orders:\n You are once again in the employ\n of Lady Karababa. This time, your\n role is to protect the ambassador\n within the ominous Navukgo\n Execution Chamber. Will you be\n able to redeem your reputation with\n President Naja...?"},
      [22] = {n="Social Graces",d="Mission Orders:\n You have successfully protected\n Lady Karababa from harm and\n earned high praise. Perhaps you can\n expect a bonus from the president\n when you return to Salaheem's\n Sentinels...?"},
      [23] = {n="Foiled Ambition",d="Mission Orders:\n You have been caught in a conflict\n between Lady Karababa and\n President Naja. Probably best if\n you let President Naja cool down\n for a while..."},
      [24] = {n="Playing the Part",d="Mission Orders:\n You have obtained your reward\n from Lady Karababa, but have been\n reminded of the burden of your\n duty. Is the Astral Candescence\n truly so dangerous? Keep improving\n your reputation with the palace and\n dig deeper into the mystery..."},
      [25] = {n="Seal of the Serpent",d="Mission Orders:\n The Grand Vizier has summoned you\n to the palace.\n You are required to divest yourself\n of all weapons before passing through\n the Imperial Whitegate."},
      [26] = {n="Misplaced Nobility",d="Mission Orders:\n The Grand Vizier has ordered you to\n search for Lady Aphmau.\n First, locate the Immortal, Rishfee,\n within the Aydeewa Subterrane."},
      [27] = {n="Bastion of Knowledge",d="Mission Orders:\n After failing to find Aphmau in\n Aydeewa, Rishfee suggests you hurry\n back to the capital and look for her\n in Walahra Temple."},
      [28] = {n="Puppet in Peril",d="Mission Orders:\n You are to escort Aphmau to Mamook\n on her mission to recover Ovjang.\n Will you find the automaton in the\n land of the savage Mamool Ja?"},
      [29] = {n="Prevalence of Pirates",d="Mission Orders:\n Aphmau and her puppets have been\n taken by the mysterious Luzaf.\n Track down the corsair and his\n captives, and repay Rishfee's noble\n sacrifice."},
      [30] = {n="Shades of Vengeance",d="Mission Orders:\n You have been ordered to participate\n in the search for Aphmau by the\n Immortal, Amnaf.\n You are to begin in Periqia, ancestral\n land of the corsairs."},
      [31] = {n="In the Blood",d="Mission Orders:\n The true identity of the court\n puppetmaster has been revealed.\n However, the Grand Vizier has\n ordered you to return to Al Zahbi\n and report the completion of your\n mission to President Naja."},
      [32] = {n="Sentinels' Honor",d="Mission Orders:\n A villain by the name of \"Duzaf the\n Blackbelly\" is rumored to have made\n an attempt on the life of the Empress.\n President Naja has vowed to claim the\n bounty on his head in the name of\n Salaheem's Sentinels."},
      [33] = {n="Testing the Waters",d="Mission Orders:\n A bounty has been placed on the\n head of Duzaf the Blackbelly...or is\n it really Luzaf the Blackheart?\n Seek out the Black Coffin once\n more and confirm President Naja's\n suspicions."},
      [34] = {n="Legacy of the Lost",d="Mission Orders:\n You have been ordered to guard\n the treasury of Ephramad. But first\n you must find the hidden treasury,\n concealed somewhere inside\n Talacca Cove..."},
      [35] = {n="Gaze of the Saboteur",d="Mission Orders:\n Gessho believes Nashmeira's life\n may be in danger. Hurry to the\n Hazhalm Testing Grounds to protect\n her from the conniving Flit."},
      [36] = {n="Path of Blood",d="Mission Orders:\n You have returned unharmed from\n your close encounter with the\n underworld, but were unable to\n rescue Nashmeira. Follow her last\n orders and deliver her message to\n President Naja."},
      [37] = {n="Stirrings of War",d="Mission Orders:\n After delivering Nashmeira's\n \"message\" to President Naja, you\n learn of an allied forces military\n council to be convened in the near\n future..."},
      [38] = {n="Allied Rumblings",d="Mission Orders:\n You have been summoned to the\n Allied Military Council being held in\n the Grand Duke Palace. Report on\n the current state of affairs in the\n Empire of Aht Urhgan."},
      [39] = {n="Unraveling Reason",d="Mission Orders:\n You have been asked to participate\n in the Wajaom Infiltration Operation.\n A high-speed airship is being\n prepared for the mission. Speak\n with Pherimociel when you are\n ready to depart."},
      [40] = {n="Light of Judgment",d="Mission Orders:\n The Endymion has been blasted out\n of the sky by an intense beam of\n light... However, the mission must\n continue. Make your way to Aht\n Urhgan Whitegate and rendezvous\n with Rodin-Comidin."},
      [41] = {n="Path of Darkness",d="Mission Orders:\n Using the map given to you by\n Rodin-Comidin, find a route\n through Nyzul Isle and rescue the\n captured Luzaf!"},
      [42] = {n="Fangs of the Lion",d="Mission Orders:\n You have failed in your attempt to\n rescue Luzaf. Return to the offices\n of Salaheem's Sentinels and regroup\n with President Naja."},
      [43] = {n="Nashmeira's Plea",d="Mission Orders:\n Escort Nashmeira as she sets out\n to convince Razfahd to halt his\n radical plan. Head to Nyzul Isle and\n show your true mercenary mettle!"},
      [44] = {n="Ragnarok",d="Mission Orders:\n The second coming of Ragnarok\n has been averted. Return to Al\n Zahbi and report to President Naja."},
      [45] = {n="Imperial Coronation",d="Mission Orders:\n You have been chosen to\n accompany President Naja to the\n Empress's coronation. Once you are\n properly attired, make your way to\n the palace."},
      [46] = {n="The Empress Crowned",d="Mission Orders:\n You have been bestowed with the\n honor of crowning Empress\n Nashmeira II. There can be no\n higher acknowledgment of your\n achievements as a mercenary.\n Perhaps now President Naja will\n return your rightful reward..."},
      [47] = {n="Eternal Mercenary",d="Mission Orders:\n The glory crown has finally been\n returned to you. However, President\n Naja's iron grip is not so easily\n broken. It appears your repayments\n to Salaheem's Sentinels will\n continue into the forseeable\n future..."},
    }},
    wotg = { name = "Wings of the Goddess", ids = {
      [0] = {n="Cavernous Maws",d="Mission Orders:\n Are the hideous statues scattered\n across Quon and Mindartia the\n portals to a new chapter of\n adventure...?"},
      [1] = {n="Back to the Beginning",d="Mission Orders:\n Hideous statues. Monstrous beasts.\n The otherworld that lies in between.\n Could this war-torn land you have\n been thrust into truly be the\n outskirts of Jeuno...?"},
      [2] = {n="Cait Sith",d="Mission Orders:\n Beyond the cavernous maws lies\n the age of the Crystal War.\n You have agreed to aid Cait Sith in\n her attempt to lessen the pain\n inflicted in this time of strife."},
      [3] = {n="The Queen of the Dance",d="Mission Orders:\n The famous Troupe Mayakov is set\n to put on a public show at the Lion\n Springs Tavern in Southern San d'Oria.\n If only you had a ticket..."},
      [4] = {n="While the Cat Is Away",d="Mission Orders:\n Summoned by his troops, Sir Ragelise,\n leader of the Knights of the Ironcrest\n Hawk, has headed for the castle with\n the ever-flamboyant Alexei Mayakov.\n In an intriguing aside, a most curious\n presence watches their every move,\n concealed in the nearby shadows..."},
      [5] = {n="A Timeswept Butterfly",d="Mission Orders:\n Still on the trail of the elusive Cait\n Sith, the unyielding Lilisette continues\n to claim she knows what the future\n holds in store. Amidst her crazed\n rantings, she has requested that you\n accompany her to La Vaule."},
      [6] = {n="Purple, The New Black",d="Mission Orders:\n The Dark Kindred have begun a\n relentless assault of La Vaule.\n Assist Sir Haudrale and the Knights\n of the Madder Falcon in evacuating\n the helpless villagers to safety."},
      [7] = {n="In the Name of the Father",d="Mission Orders:\n More motivated than ever, Lilisette\n continues to pursue Cait Sith, now\n in hopes of saving her father from a\n seemingly unavoidable end. To lure\n the regal feline, aid her in relieving\n the tears shed in the name of the\n Crystal War."},
      [8] = {n="Dancers in Distress",d="Mission Orders:\n Alexei Mayakov is displeased\n with his two dancers, Lilisette\n and Portia, who are suspected\n to have once again skipped\n rehearsal to attend Sir Ragelise\n at Chateau d'Oraguille."},
      [9] = {n="Daughter of a Knight",d="Mission Orders:\n Could the mystery object the Cait\n Siths were discussing be related in\n any way to the medicine Sir Ragelise\n used to take? The answer lies with\n Amaura, a resident of present-day\n Southern San d'Oria."},
      [10] = {n="A Spoonful of Sugar",d="Mission Orders:\n Using the key ingredient you and\n Lilisette have laboriously acquired,\n Amaura was finally able to concoct\n the same medicine that Sir Ragelise\n used all those years ago. Deliver\n it to the ailing knight at the\n Chateau d'Oraguille without delay."},
      [11] = {n="Affairs of State",d="Mission Orders:\n Jeunoan Ambassador, Nag'molada,\n has delivered unsettling news of\n the duchy's plan to surrender to\n the besieging beastman force.\n Accompany Count Borel and\n Lilisette in their mission to\n entreat the aid of the other two\n nations."},
      [12] = {n="Borne by the Wind",d="Mission Orders:\n Bastok and Windurst have both\n pledged reinforcements for Jeuno.\n Make all haste and deliver Count\n Borel's letter to the duchy before\n the unthinkable comes to pass."},
      [13] = {n="A Nation on the Brink",d="Mission Orders:\n Despite Lilisette's repeated\n protests and the imminent arrival\n of reinforcements from the three\n nations, the surrender ceremony\n is set to take place in the depths\n of Jeuno's underground. Will this\n be the end of the four-nation\n alliance...?"},
      [14] = {n="Crossroads of Time",d="Mission Orders:\n Amidst scenes of horrendous\n devastation, Archduke Kam'lanaut\n makes an inspired victory declaration\n before all. Meanwhile, shrouded\n figures intently observe the\n unfolding of events from a\n vantage point..."},
      [15] = {n="Sandswept Memories",d="Mission Orders:\n A distraught Lilisette has darted\n off to the Lion Springs Tavern.\n Follow her and discover the reason\n behind her consternation."},
      [16] = {n="Northland Exposure",d="Mission Orders:\n Ever the reliable source of\n information, Alexei Mayakov has\n revealed that suspicious individuals\n donning distinct purple livery have\n been sighted out in Valdeaunia. Keen\n to allay her anxiety over recent\n occurrences, Lilisette has resolved\n to pursue this new lead."},
      [17] = {n="Traitor in the Midst",d="Mission Orders:\n Cait Sith Naoi is convinced a\n traitor walks among her kin.\n Unmasking the turncoat requires\n that you attach a \"shadow bug\" to\n each of the Cait Siths scattered\n throughout the Beaucedine Glacier."},
      [18] = {n="Betrayal at Beaucedine",d="Mission Orders:\n A cait is on the move! What could\n the suspected traitor's intended\n destination be? There is only one\n way to find out!"},
      [19] = {n="On Thin Ice",d="Mission Orders:\n In a dire turn of events, both\n Lilisette and Portia have fallen\n into the hands of the enemy.\n Take word of this unanticipated\n development to the convalescing\n Sir Ragelise at Chateau d'Oraguille."},
      [20] = {n="Proof of Valor",d="Mission Orders:\n In order to join Vestillet and\n Noillurie's units on their mission\n to Valdeaunia, you must gather\n support in writing from Kingdom\n troops stationed within the city."},
      [21] = {n="A Sanguinary Prelude",d="Mission Orders:\n You have been granted permission\n to accompany the Madder Falcons\n and the Red Roses to the Northlands.\n Take advantage of this opportunity\n to unearth clues that may lead to the\n recovery of Lilisette and Portia."},
      [22] = {n="Dungeons and Dancers",d="Mission Orders:\n Lilisette and Portia are being\n detained in a subterranean location\n somewhere beneath the Beaucedine\n Glacier. Your rescue effort begins\n with a search for the entrance\n underground."},
      [23] = {n="Distorter of Time",d="Mission Orders:\n What shocking truth lies behind\n Cait Sith Ceithir's bold declaration\n that Atomos will choose the future?\n The answer must wait! Use the\n combined power of the surviving\n Cait Siths to stop the rampant\n Atomos!"},
      [24] = {n="The Will of the World",d="Mission Orders:\n Your victory over Cait Sith Ceithir\n and Atomos is soured as Portia\n remains in the hands of the\n portentous Lady Lilith and her\n Spitewardens. Once again, the\n unsavory task of breaking the news\n to Sir Ragelise has fallen to you\n and Lilisette."},
      [25] = {n="Fate in Haze",d="Mission Orders:\n With each memory devoured, the\n seed of a potential future is\n forever lost. What does fate\n hold in store for Vana'diel and\n its denizens?"},
      [26] = {n="The Scent of Battle",d="Mission Orders:\n Sir Ragelise has entrusted to you\n and Lilisette a role of great import\n in the Battle of Xarcabard.\n Attend the strategy meeting in\n Jeuno to learn the full details of\n your duty."},
      [27] = {n="Another World",d="Mission Orders:\n In order to gain an advantage in\n the looming battle, Lilisette has\n proposed that you speak with\n someone who was directly\n involved in the campaign."},
      [28] = {n="A Hawk in Repose",d="Mission Orders:\n Word has it that an unknown\n individual is often seen paying\n tribute to Sir Ragelise's grave\n out in Batallia Downs. Could it\n be that this man possesses the\n information you seek?"},
      [29] = {n="The Battle of Xarcabard",d="Mission Orders:\n Retired Allied Forces soldier\n Larzos has shared with you the\n strange incident that occurred\n during the storming of Castle\n Zvahl. Armed with this knowledge,\n make haste for Xarcabard!"},
      [30] = {n="Prelude to a Storm",d="Mission Orders:\n Operation Snowstorm has commenced!\n Sir Ragelise has given you orders\n to deliver word to the other two\n nations' encampments; first Windurst,\n followed by Bastok."},
      [31] = {n="Storm's Crescendo",d="Mission Orders:\n With your assistance, the Federation\n has successfully carried out the\n operation's preliminary phase.\n You must now head to where the\n Republican army lies in wait."},
      [32] = {n="Into the Beast's Maw",d="Mission Orders:\n With Bastok's strategic blasting of\n the caverns, the groundwork has\n been set for Operation Snowstorm\n to commence in earnest. Hasten\n back to the San d'Orian encampment\n as they make ready to besiege\n Castle Zvahl."},
      [33] = {n="The Hunter Ensnared",d="Mission Orders:\n Portia has been returned to safety,\n but the cost may prove to be dear.\n Unforeseen events have caused the\n operation to go awry. You must\n regroup with Kingdom forces that\n remain outside the keep."},
      [34] = {n="Flight of the Lion",d="Mission Orders:\n Operation Snowstorm has ended in\n failure, the Allied Forces nigh\n annihilated by those they sought\n to smite. The surviving troops have\n been ordered to withdraw to the\n Duchy."},
      [35] = {n="Fall of the Hawk",d="Mission Orders:\n Cast out of both Kingdom and\n Alliance in disgrace, Sir Ragelise\n has disappeared with Portia in\n tow...but not before making known\n his trepidation at the ominous\n vortex that appeared above Castle\n Zvahl."},
      [36] = {n="Darkness Descends",d="Mission Orders:\n Your pursuit of Sir Ragelise and\n Portia has brought you back to\n the enemy stronghold. Seek them\n out before the unthinkable comes\n to pass!"},
      [37] = {n="Adieu, Lilisette",d="Mission Orders:\n Has the world made its choice?\n Is this the end of the future you\n have fought tooth and nail to\n preserve?"},
      [38] = {n="By the Fading Light",d="Mission Orders:\n The brighter future continues to fade\n even as the Crystal War rages on,\n the warring factions oblivious to the\n greater scheme of things. With a path\n ahead unapparent, Cait Sith proposes\n that you head to Xarcabard to\n observe how the struggle unfolds."},
      [39] = {n="Edge of Existence",d="Mission Orders:\n The future heavily favors the world\n of strife, and nothing short of a\n miracle will help to turn the tide.\n Slim chance though it may be,\n reviving Lilisette is the only avenue\n that remains. First you must seek the\n counsel of Atomos, the Devourer of\n Memories."},
      [40] = {n="Her Memories",d="Mission Orders:\n Fragments of Lilisette's memories lie\n scattered across the land. In retracing\n the footsteps of her past, the way\n may be revealed to you."},
      [41] = {n="Forget Me Not",d="Mission Orders:\n Following an extended pilgrimage,\n you have managed to gather all of\n Lilisette's memory fragments. Make\n haste to the Walk of Echoes, where\n Cait Sith awaits."},
      [42] = {n="Pillar of Hope",d="Mission Orders:\n Having absorbed Lilisette's memories,\n Atomos unleashed a blinding pillar of\n light in the direction of Grauberg.\n Head there without delay and\n ascertain the nature of this\n phenomenon."},
      [43] = {n="Glimmer of Life",d="Mission Orders:\n The scattered fragments of Lilisette's\n memory have melded together, paving\n a path towards the brighter future.\n But will this be enough to stay the\n encroaching darkness...?"},
      [44] = {n="Time Slips Away",d="Mission Orders:\n A distraught Cait Sith has enlisted\n your help to recover the punch bug,\n an indispensable little critter that\n escaped her grasp in a moment of\n distraction. Your best bet is to\n search for it in dark, damp places.\n Cramped, moist environs."},
      [45] = {n="When Wills Collide",d="Mission Orders:\n To regain a foothold in the struggle\n and ensure Lilisette's rebirth, you\n must confront whatever darkness lies\n in wait at the Walk of Echoes."},
      [46] = {n="Whispers of Dawn",d="Mission Orders:\n In prevailing over Lady Lilith's\n Spitewardens, you have earned a\n reprieve for your future. Use this\n opportunity to return to Witchfire\n Glen and check on Lilisette."},
      [47] = {n="A Dreamy Interlude",d="Mission Orders:\n Newly reborn and disoriented, Lilisette\n must convalesce for a time in order to\n regain her strength."},
      [48] = {n="Cait in the Woods",d="Mission Orders:\n According to Lilisette, Cait Sith has\n business in Ronfaure."},
      [49] = {n="Fork in the Road",d="Mission Orders:\n The future that was, and the future\n that might have been... In revisiting\n the paths you walked hand in hand\n with Lilisette and Cait Sith, you will\n acquire the power needed to fulfill\n the will of the Goddess."},
      [50] = {n="Maiden of the Dusk",d="Mission Orders:\n The hour of reckoning is nigh. Seek\n Lady Lilith at her throne within the\n Walk of Echoes, where the decisive\n battle between realities will be waged."},
      [51] = {n="Where It All Began",d="Mission Orders:\n With the encroachment between\n realities ended, certain disaster has\n been averted. How do the others fare\n in the wake of balance restored?\n Perhaps a visit to the Lion Springs\n Tavern in Southern San d'Oria is in\n order."},
      [52] = {n="A Token of Troth",d="Mission Orders:\n You have received a cordial invitation\n to attend the wedding of Sir Ragelise\n and Portia. Make your way to the\n Temple of the Goddess in Upper\n Jeuno, where the ceremony is to\n be held."},
      [53] = {n="Lest We Forget",d="Mission Orders:\n So it was that Altana's grief was\n ended, tears marring Her divine\n countenance no more.\n Yet the Crystal War rages on. Ever\n must you carry on the fight, in honor\n of she who sacrificed all, that others\n might know peace..."},
    }},
    campaign = { name = "Campaign Ops", ids = {
      [1] = {n="Smokescreen I (S)",d="Objective:\n The Kingdom has set plans in motion\n to carry out attacks on Beastman\n Confederate strongholds in a series\n of strategic Campaign battles. Assist\n the Knights of the Iron Ram in the\n siege of these key tactical positions.\n\nUnit Requirement: 1 member"},
      [2] = {n="Smokescreen II (S)",d="Objective:\n The Kingdom has set plans in motion\n to carry out attacks on Beastman\n Confederate strongholds in a series\n of strategic Campaign battles. Assist\n the Knights of the Iron Ram in the\n siege of these key tactical positions.\n\nUnit Requirement: 1 member"},
      [3] = {n="Smokescreen III (S)",d="Objective:\n The Kingdom has set plans in motion\n to carry out attacks on Beastman\n Confederate strongholds in a series\n of strategic Campaign battles. Assist\n the Knights of the Iron Ram in the\n siege of these key tactical positions.\n\nUnit Requirement: 1 member"},
      [4] = {n="Smokescreen IV (S)",d="Objective:\n The Kingdom has set plans in motion\n to carry out attacks on Beastman\n Confederate strongholds in a series\n of strategic Campaign battles. Assist\n the Knights of the Iron Ram in the\n siege of these key tactical positions.\n\nUnit Requirement: 1 member"},
      [5] = {n="Smokescreen V (S)",d="Objective:\n The Kingdom will be conducting a\n series of attacks on northern\n Confederate strongholds as part of\n the Allied war effort. Assist the\n Knights of the Iron Ram in the siege\n of these key tactical positions.\n\nUnit Requirement: 1 member"},
      [6] = {n="Splitting Heirs (S)",d="Objective:\n In response to our reclaiming of\n regions surrounding the capital,\n Darkheir Grradhod has organized his\n surviving hordes to launch a mass\n counter-offensive from La Vaule.\n You are to neutralize this threat by\n eliminating the Orc leader.\n\nUnit Requirement: 1�`6 members"},
      [7] = {n="Kinslayer: Baileys (S)",d="Objective:\n Allied forces have breached the gates\n of Castle Zvahl, only to be thwarted\n by the formidable enemy contingent\n within. Join the Knights of the Iron\n Ram in a strategic assault on the\n castle baileys to remove the Kindred\n commanders and deal a serious blow\n to enemy morale.\n\nUnit requirement: 1�`6 members"},
      [8] = {n="Kinslayer: Keep (S)",d="Objective:\n Allied forces have breached the gates\n of Castle Zvahl, only to be thwarted\n by the formidable enemy contingent\n within. Join the Knights of the Iron\n Ram in a strategic assault on the\n castle keep to remove the Kindred\n commanders and deal a serious blow\n to enemy morale.\n\nUnit requirement: 1�`6 members"},
      [9] = {n="Fiat Lux (S)",d="Objective:\n Their stronghold surrounded, our\n enemy prepares to launch a desperate,\n deadly counteroffensive. This is where\n the battle will be won. For the future\n of Vana'diel, you must storm Castle\n Zvahl and remove the Shadow Lord\n from his false throne.\n Altana's blessing be with you!\n\nUnit requirement: 1�`6 members"},
      [10] = {n="Campaign Operation",d="Objective:\n Be all that you can be!\n\nUnit Requirement: 1 member"},
      [11] = {n="Pit Spider I (S)",d="Objective:\n A report has been received regarding\n the location of an Orcish supply train.\n You are to travel with the Knights of\n the Iron Ram to Everbloom Hollow via\n the Vunkerl Inlet (J-7), intercept the\n caravan, and destroy it.\n\nUnit Requirement: 1�`6 members"},
