    acp = { name = "A Crystalline Prophecy", ids = {
      [0] = {n="A Crystalline Prophecy",d="For what purpose has the ancient\n crystal returned?\n A new adventure to unearth the\n secrets of Vana'diel's past begins!"},
      [1] = {n="The Echo Awakens",d="Mission Orders:\n The primordial crystal appeared over\n Jeuno, its otherworldly light raining\n down from the heavens upon the\n forests, marshlands, and mountains.\n A mysterious young boy would have\n you recover that light and bring it to\n Qufim Island. Will you heed the call?"},
      [2] = {n="Gatherer of Light (I)",d="Mission Orders:\n When the echo runs amok, the key to\n Vana'diel's salvation lies with three\n unusual stones that have found their\n way into the hands of some overly\n curious Goblins..."},
      [3] = {n="Gatherer of Light (II)",d="Mission Orders:\n Was it all truly decided before the\n dawn of time...?\n When the crystal sends forth its dark\n minions, only you can put a stop to\n them!"},
      [4] = {n="Those Who Lurk in Shadows (I)",d="Mission Orders:\n In the darkness of the ruined city\n Fei'Yin, beastmen in the thrall of the\n crystal devise their nefarious plot..."},
      [5] = {n="Those Who Lurk in Shadows (II)",d="Mission Orders:\n Your quest takes you to Qu'Bia Arena,\n but the otherworldly force of the\n crystal bars your path.\n Only by harnessing its power for\n yourself may you gain entry!"},
      [6] = {n="Those Who Lurk in Shadows (III)",d="Mission Orders:\n The beastman thralls of the Seed\n Crystal are threatening to commence\n their dark ritual. They must be\n stopped before it is too late!"},
      [7] = {n="Remember Me in Your Dreams",d="Mission Orders:\n In the Hall of the Gods, the\n beginning of the end draws nigh.\n Will you succeed in changing the\n course of fate?"},
      [8] = {n="Born of Her Nightmares",d="Mission Orders:\n The mysterious child Aldo claims that\n the answer to the mystery sleeps\n within Delkfutt's Tower. Have you the\n courage to face the truth?"},
      [9] = {n="Banishing the Echo",d="Mission Orders:\n To reach your final destination, you\n must recover the twelve remaining\n fragments of the mysterious crystal..."},
      [10] = {n="Ode of Life Bestowing",d="Mission Orders:\n The final confrontation awaits you\n within the Stellar Fulcrum..."},
      [11] = {n="A Crystalline Prophecy (Fin.)",d="�@"},
      [1000] = {n="To commence ACP",d="Examine the Tales' Beginning\n in Lower Jeuno (G-9)."},
    }},
    mkd = { name = "A Moogle Kupo d'Etat", ids = {
      [0] = {n="A Moogle Kupo d'Etat",d="It all began with a raindrop, or so\n the legend says... Little did anyone\n suspect that this would prove to be\n only the beginning of a harrowing\n nightmare unheard of in the annals\n of mooglekind."},
      [1] = {n="Drenched! It Began with a Raindrop",d="Mission Orders:\n With the ramshackle roof of your\n Mog House unable to withstand the\n elements, your moogle cohort entreats\n you to find three materials required\n for some much-needed renovations:\n an Orcish armor plate, a Quadav\n backscale, and a block of Yagudo\n caulk."},
      [2] = {n="Hasten! In a Jam in Jeuno?",d="Word has it that the Rent-a-Room in\n Jeuno is also showing signs of\n spoilage. Unable to resist your moogle\n companion's earnest plea, you\n reluctantly agree to investigate the\n premises..."},
      [3] = {n="Welcome! To My Decrepit Domicile",d="Mission Orders:\n Rotting roofboards, crumbling walls...\n Yes, this Rent-a-Room is a mess.\n Your moogle associate has the\n handyman skills; all he needs are a\n few essential items to make the\n requisite repairs."},
      [4] = {n="Curses! A Horrifically Harrowing Hex",d="Mission Orders:\n When a missive from Boss Kupeliaure\n unexpectedly unleashes a calamitous\n curse, our hard-luck heroes seek out\n the aid of the esteemed yet eccentric\n exorcist Professor Shantotto."},
      [5] = {n="An Errand! The Professor's Price",d="Mission Orders:\n The Professor consents to lend you\n her aid, but as expected, there's a\n price to be paid. Within a Cardian in\n the Outer Horutoto Ruins lies the\n reagent she does seek; return it to\n her, that you might avert a fate most\n bleak!"},
      [6] = {n="Shock! Arrant Abuse of Authority",d="Mission Orders:\n When the linguistically challenged\n toady Toto Kupeliaure demands a\n ridiculous sum in unpaid rent, your\n moogle comrade chooses to make the\n ultimate sacrifice. Venture forth and\n unearth the moggy bank that contains\n his hard-earned wedding funds!"},
      [7] = {n="Lender Beware! Read the Fine Print",d="Oh, woe! Having exhausted all other\n options, your star-crossed moogle\n associate is forced to seek aid from\n the shadiest of scoundrels. You have\n an appointment with the underworld\n moneylender Riko Kupenreich at his\n office in Sea Serpent Grotto."},
      [8] = {n="Rescue! A Moogle's Labor of Love",d="Mission Orders:\n A dire development! Your moogle\n partner's betrothed, the fair Kupiruru,\n has been kidnapped by Toto's band\n of hoodlums! Make haste for the\n Chamber of Oracles to save the\n moogle maiden from a frightening\n fate!"},
      [9] = {n="Roar! A Cat Burglar Bares Her Fangs",d="Mission Orders:\n What's this!? Toto has enlisted the\n services of the formidable feline\n filcher Nanaa Mihgo to guard his\n prize catch! Can you declaw the Cat\n Burglar, or will you end up as cat\n food?"},
      [10] = {n="Relief! A Triumphant Return",d="Mission Orders:\n The battle won and the fair maiden\n rescued, all is well for our plucky\n protagonists. What better time to\n return to the newly renovated\n Rent-a-Room for some much-deserved\n rest and relaxation...?"},
      [11] = {n="Joy! Summoned to a Fabulous Fete",d="Mission Orders:\n What a thrilling turn of events!\n Toto has cleaned up his act and, as a\n sign of his newfound sincerity, has\n invited you and your bat-winged\n buddy to a magnificent Moogle\n Festival at Castle Zvahl!"},
      [12] = {n="A Challenge! You Could Be a Winner",d="Mission Orders:\n A series of heart-stirring festival\n games, culminating in the purportedly\n profitable \"Mega Mog\n Bonanza-Rama-Palooza\"! Will our\n hero go home a champ, or a chump!?"},
      [13] = {n="Smash! A Malevolent Menace",d="Mission Orders:\n Lying in wait in the castle's innermost\n chambers was not a generous jackpot,\n but a chilling confrontation! With a\n malevolent moogle poised to unravel\n not merely Mog House tradition but\n the very fabric of the universe, only\n our heroes can stand in his way!"},
      [14] = {n="A Moogle Kupo d'Etat (Fin.)",d="�@"},
    }},
    asa = { name = "A Shantotto Ascension", ids = {
      [0] = {n="A Shantotto Ascension",d="Doctor Shantotto returned to\n Windurst one day after a mysterious,\n unexplained absence, shocking her\n colleagues by proclaiming herself\n ruler of her own empire. What could\n have possibly triggered this\n intensification of her inimical\n urges? The shocking truth awaits\n adventurers who would seek it!"},
      [1] = {n="Burgeoning Dread",d="Mission Orders:\n Does this feeling of disquiet\n welling up within portend the\n coming of catastrophe, or is it\n simply something to be ignored?\n You can only hope that it is all\n in your mind..."},
      [2] = {n="That Which Curdles Blood",d="Mission Orders:\n You have been served what appears\n to be a draft card inducting you\n into the Shantotto Empire as a\n special operative. Report to\n provisional headquarters located\n on Qufim Island with extreme\n haste...and the specified gifts\n of tribute in hand."},
      [3] = {n="Sugar-coated Directive",d="Mission Orders:\n Your inaugural mission as special\n operative of the Shantotto Empire\n requires you to attach enchanted\n seals to the protocrystals scattered\n across Vana'diel. Your new empress\n has stressed that she takes failure\n poorly."},
      [4] = {n="Enemy of the Empire (I)",d="Mission Orders:\n Seeking to usurp the Tenshodo as the\n underworld's foremost supplier of\n contraband, Domina Shantotto requires\n that you remove its leader, Aldo,\n from the picture. A clandestine\n meeting between you and the target\n has been arranged in the Gustav\n Tunnel. All that is needed to initiate\n contact is a black book, acquirable\n from Andrause in Norg."},
      [5] = {n="Enemy of the Empire (II)",d="Mission Orders:\n The overzealous young Tenshodo\n agents are not interested in\n listening to reason. In the name\n of your empress, you have no choice\n but to flex your adventurer\n muscles and pound some sense\n into them."},
      [6] = {n="Sugar-coated Subterfuge",d="Mission Orders:\n A candid conversation has cleared\n things up between you and Aldo.\n He bids you come to Tenshodo\n Headquarters in Jeuno in order\n to further discuss Shantotto's\n diabolical designs."},
      [7] = {n="Shantotto in Chains",d="Mission Orders:\n You have learned that the original\n Doctor Shantotto is being held\n captive somewhere in Ro'Maeve.\n Realizing that only Shantotto\n can stand against Shantotto,\n Professor Yoran-Oran has proposed\n a rescue mission."},
      [8] = {n="Fountain of Trouble",d="Mission Orders:\n Original Shantotto has revealed\n that her corrupted counterpart\n concocts her plan for world\n domination from her Full Moon\n Fountain lair. In the defense of\n Vana'diel, make your way there\n without delay."},
      [9] = {n="Battaru Royale",d="Mission Orders:\n Determined to enact her odious plot\n to conquer all of Vana'diel, Domina\n Shantotto has unleashed her army\n of clones upon you. Defeat them\n all lest you and your companions\n be reduced to bones!"},
      [10] = {n="Romancing the Clone",d="Mission Orders:\n To your dismay but not complete\n surprise, Original Shantotto has\n chosen to side with her heinous\n alter ego. Best you return at once\n to Tenshodo Headquarters to plan\n your next move."},
      [11] = {n="Sisters in Arms",d="Mission Orders:\n The two Shantottos have relocated\n their base of operation to the\n Sacrificial Chamber within the\n Temple of Uggalepih. Accompany\n Aldo and Professor Yoran-Oran\n there and put an end to this\n menace once and for all!"},
      [12] = {n="Project: Shantottofication",d="Mission Orders:\n The inimitably fiendish\n Shantottofication curse, if\n allowed to wreak havoc on the\n land, would spell the end of\n the world as we know it. Only\n you can prevent an unimaginable\n fate from befalling Vana'diel!"},
      [13] = {n="An Uneasy Peace",d="Mission Orders:\n Disaster has been averted thanks\n to your relentless efforts, each\n denizen of Vana'diel returning to\n the life they used to know. But\n how long can this period of\n tranquility be expected to endure?\n Professor Yoran-Oran cannot help\n but be pessimistic..."},
      [14] = {n="A Shantotto Ascension (Fin)"},
      [1000] = {n="To Begin ASA...",d="Examine the Tales' Beginning\n in Windurst Walls (C-6)."},
    }},
    soa = { name = "Seekers of Adoulin", ids = {
      [110] = {n="The Sacred City of Adoulin",d="Mission Orders:\n Word around the Middle Lands is that\n a pioneering initiative has begun in\n the land of the setting sun. The\n Jeuno Chamber of Commerce and\n Industry is looking for potential\n pioneers to assist in the projects.\n They have prepared a test of skill.",s={"Rumors from the West"}},
      [112] = {n="The Geomagnetron",d="Mission Orders:\n Bring the geomagnetron Darcia has\n entrusted you with to one of the\n dungeons she mentioned, find the\n applicable area located therein, and\n record the energies there onto the\n mysterious device.",s={"The Geomagnetron"}},
      [116] = {n="Onward to Adoulin",d="Mission Orders:\n Depart for the frontier city of\n Adoulin via a waypoint and begin a\n whole new saga of adventure!",s={"Onward to Adoulin"}},
      [120] = {n="Heartwings and the Kindhearted",d="Mission Orders:\n You learn from Arciela, the maiden\n whom you met in the Ceizak\n Battlegrounds, that the Sacred City of\n Adoulin lies to the north.",s={"Heartwings and the Kindhearted"}},
      [122] = {n="Pioneer Registration",d="Mission Orders:\n Before embarking on a trek to\n colonize Ulbuka, you'll first need to\n register with the Pioneers' Coalition.\n Look for a sign painted with a shovel\n and you can't miss it!",s={"Pioneer Registration"}},
      [124] = {n="Life on the Frontier",d="Mission Orders:\n With pioneer registration under\n your belt, you can now undertake\n assignments from the various\n coalitions scattered around the city.\n Take on as many as you can and help\n the colonization effort succeed!",s={"Life on the Frontier"}},
      [126] = {n="Meeting of the Minds",d="Mission Orders:\n You have been invited to dine with\n the city's political leaders at\n Castle Adoulin. Head to the eastern\n district and present your missive to\n the guard at the castle gates.",s={"Meeting of the Minds"}},
      [128] = {n="Arciela Appears Again",d="Mission Orders:\n By reuniting with--and learning the\n identity of--Arciela V. Adoulin, you\n have set the wheel of fate in\n motion...",s={"Arciela Appears Again"}},
      [132] = {n="The Ancient Pact",d="Mission Orders:\n Rumors abound of a queen that rules\n over the precocious leafkin. Find out\n more about this mysterious creature\n by asking around Adoulin. Perhaps the\n well-trafficked Mummers' Coalition\n would be a good place to start.",s={"Budding Prospects"}},
      [134] = {n="The Light Shining in Your Eyes",d="Mission Orders:\n The black-clad statesman Teodor has\n informed you that the dark blade\n wielded by Arciela is the only thing\n that will prove your worth to the\n leafkin. Report back to Levil with\n your findings.",s={"The Light Shining in Your Eyes"}},
      [136] = {n="The Heirloom",d="Mission Orders:\n Arciela's blade was bestowed upon her\n by Ygnas, and she never lets it leave\n her side. The best place to find her is\n likely Castle Adoulin.",s={"The Heirloom"}},
      [138] = {n="An Aimless Journey",d="Mission Orders:\n Arciela was nowhere to be found at\n the castle, but one of her servants\n let slip that she was off to\n investigate an ergon locus in Cirdas\n Caverns. Has she really traveled out\n there alone...?",s={"An Aimless Journey"}},
      [140] = {n="Ortharsyne",d="Mission Orders:\n Having reunited with Arciela in Cirdas\n Caverns, you learned that she will not\n let you have the sword, but instead\n will go with you to Yorcia Weald. The\n entrance to Yorcia Weald lies in I-7\n of Cirdas Caverns.",s={"Ortharsyne"}},
      [142] = {n="In the Presence of Royalty",d="Mission Orders:\n Fate saw you meet with Rosulatia, the\n mother seed of the leafkin. She has\n asked you to find a Yorcia's tear to\n learn about the abnormalities in\n Eastern Ulbuka. Find one and head to\n the sole pure font of water within the\n weald.",s={"In the Presence of Royalty"}},
      [144] = {n="The Twin World Trees",d="Mission Orders:\n You and Arciela have witnessed the\n inexorably connected World Trees of\n Rhazowa and Ulbuka. What is the dark\n disease that threatens to consume\n Yggdrasil? How can the World Tree be\n saved? Rosulatia fluttered away with\n naught more than a cryptic hint...",s={"The Twin World Trees"}},
      [146] = {n="Honor and Audacity",d="Mission Orders:\n A fight has broken out and\n Gratzigg, the Peacekeepers'\n Coalition leader, has ordered it be\n moved to an official venue. Head\n to the Watergarden Coliseum to\n witness the spectacle.",s={"Honor and Audacity"}},
      [148] = {n="The Watergarden Coliseum",d="Mission Orders:\n Seeing an official duel apparently\n requires permission. However,\n during yet another chance\n encounter with Arciela, the princess\n tells you that as long as you are\n her escort, the guards will have to\n let you into the coliseum.",s={"The Watergarden Coliseum"}},
      [150] = {n="Friction and Fissures",d="Mission Orders:\n The rift between those in support of\n the colonization movement and those\n in opposition to it is quickly\n deepening. The matter weighs heavily\n on everyone, but upon the princess\n most of all.",s={"Friction and Fissures"}},
      [152] = {n="The Celennia Memorial Library",d="Mission Orders:\n Though this most recent upheaval\n may have been quelled, it is but\n one symptom of a much larger\n problem that plagues Adoulin.\n Head to the Celennia Memorial\n Library to learn more about this\n pandemic of discord.",s={"The Celennia Memorial Library"}},
      [156] = {n="For Whom Do We Toil?",d="Mission Orders:\n The only thing on Adoulinians' lips\n these days seems to be that the\n city's youth are using the Rala\n Waterways without permission.\n Descend underground once more to\n see if this is actually the case.",s={"For Whom Do We Toil?"}},
      [162] = {n="Aiming for Ygnas",d="Mission Orders:\n A certain faction composed of\n young revolutionaries is intent on\n deposing the chancellor.\n Make haste to Castle Adoulin\n before their vision becomes reality.",s={"Aiming for Ygnas"}},
      [164] = {n="Calamity in the Kitchen",d="Mission Orders:\n Conspiracies and assassinations are\n not in a guard's jurisdiction, you have\n discovered. Meanwhile, the castle\n cooks bewail the lack of provisions\n normally sent by the Civic Arboretum.",s={"Calamity in the Kitchen"}},
      [168] = {n="Arciela's Promise",d="Mission Orders:\n By some strange set of coincidences,\n you have been tasked with bringing\n Arciela the fruits of her labors she\n sowed long ago. Perhaps these\n Adoulinian tomatoes are just the\n thing to get you into the castle...",s={"Arciela's Promise"}},
      [170] = {n="Predators and Prey",d="Mission Orders:\n The attempt on Ygnas's life ended\n without any casualties, but the\n offenders have escaped! They did,\n however, leave behind a clue.\n Use it to pursue and bring the\n hammer of justice down upon them!",s={"Predators and Prey"}},
      [172] = {n="Behind the Sluices",d="Mission Orders:\n An antiquated sluice gate sits in\n the heart of the assassins'\n Rala Waterways lair. According to\n Arciela, you should be able to\n operate it once you have a\n waterway facility crank in your\n possession.",s={"Behind the Sluices"}},
      [178] = {n="The Leafkin Monarch",d="Mission Orders:\n Now that justice has been properly\n served to those upstart\n insurgents, it is time to head\n back to the castle and find out\n just what has Arciela so worried.",s={"The Leafkin Monarch"}},
      [180] = {n="Yggdrasil",d="Mission Orders:\n Arciela's elder brother, Ygnas, has\n fallen victim to a curse and\n transformed into a leafkin. Though\n unable to communicate with anyone\n but his sister and you, he tells of\n the World Tree Yggdrasil and the\n dangers facing Ulbuka.",s={"Yggdrasil"}},
      [184] = {n="Shadows Upon Adoulin",d="Mission Orders:\n Ingrid, the most storied exorcist in\n the land, is due to arrive back in\n Adoulin from a mission to the Middle\n Lands. Meet her at the airship docks.",s={"Return of the Exorcist"}},
      [186] = {n="The Merciless One",d="Mission Orders:\n Ingrid has declared that it falls to her\n to break the curse surrounding Ygnas\n so that colonization may proceed\n unimpeded. Accompany her to the\n castle and serve as a conduit of\n knowledge between her and the\n newly transformed leafkin.",s={"The Merciless One"}},
      [188] = {n="A Curse from the Past",d="Mission Orders:\n The curse upon the grand chancellor\n is more powerful than anyone\n expected. Ingrid has demanded that\n you retrieve four items for her: a\n piece of a stone wall, a vial of\n holy water, an eternal flame, and the\n wings of a weather vane.",s={"A Curse from the Past"}},
      [190] = {n="The Purgation",d="Mission Orders:\n Return to Castle Adoulin with the four\n items Ingrid requested.",s={"The Purgation"}},
      [192] = {n="The Key",d="Mission Orders:\n Though the purgation ritual ended in\n failure, Ygnas lifted a tiny arm\n and pointed at Arciela, calling her\n \"the key.\" The houses are divided:\n should colonization continue or\n cease?",s={"The Key"}},
      [194] = {n="The Princess's Dilemma",d="Mission Orders:\n Arciela has been disheartend of late,\n and you have been tasked with finding\n out what has been bothering her.\n Witnesses have reported sightings of\n her going to the Celennia Memorial\n Library.",s={"The Princess's Dilemma"}},
      [196] = {n="Dark Clouds Ahead",d="Mission Orders:\n Arciela cannot make heads or tails of\n what her brother wants from her.\n Emotional though she may have been,\n your presence seems to have cheered\n her up slightly.",s={"Dark Clouds Ahead"}},
      [198] = {n="The Smallest of Favors",d="Mission Orders:\n Tiana seemed overjoyed now that her\n grandfather has received his medicine\n and is well again. If only Arciela were\n as exuberant as the small child she \n saved...",s={"The Smallest of Favors"}},
      [200] = {n="Summoned by Spirits",d="Mission Orders:\n According to Teodor, the girl found\n maundering the Ceizak Battlegrounds\n left her home because she was\n \"summoned by spirits.\" Perhaps\n Arciela has some knowledge to\n impart regarding those who supposedly\n did this summoning.",s={"Summoned by Spirits"}},
      [202] = {n="Evil Entities",d="Mission Orders:\n The girl Arciela describes, who is\n allegedly possessed by evil spirits,\n resembles the girl you discovered in\n the battlegrounds to an exceptional\n degree. Return to the\n Ceizak Battlegrounds to see\n what became of her.",s={"Evil Entities"}},
      [204] = {n="Adoulin Calling",d="Mission Orders:\n The mysterious girl exhibiting ghoulish\n symptoms is named Nyline, and she\n lives in a boarding house on the way\n to the Statue of the Goddess. Head\n there with Arciela as soon as\n possible.",s={"Adoulin Calling"}},
      [206] = {n="The Disappearance of Nyline",d="Mission Orders:\n Nyline wandered from her home while\n her father was explaining the details\n of her condition. She purportedly\n carries a cryptic stone on her\n journeys, but could that truly be the\n culprit? The answer may very well lie\n deep within the jungle.",s={"The Disappearance of Nyline"}},
      [208] = {n="Shared Consciousness",d="Mission Orders:\n Now that Nyline has regained lucidity,\n it is time to return to her residence.\n However, what was this epiphany that\n seemed to strike Arciela?",s={"Shared Consciousness"}},
      [210] = {n="Clear Skies",d="Mission Orders:\n After hearing that your idea sprung\n first from Teodor, Arciela decided to\n approach him about her brother's\n condition. The smile she wore as she\n left was the brightest you'd seen on\n her in weeks.",s={"Clear Skies"}},
      [212] = {n="The Man in Black",d="Mission Orders:\n Rumor has it that Teodor can be\n found at the Mummers' Coalition's\n gaming tables. Head there for a brief\n chat and to let off some steam.",s={"The Man in Black"}},
      [214] = {n="To the Victor...",d="Mission Orders:\n Teodor has challenged you to a game\n of chance. Win a best-of-five to hear\n his opinion on the Ygnas incident.",s={"To the Victor..."}},
      [216] = {n="An Extraordinary Gentleman",d="Mission Orders:\n Teodor thinks that Ygnas was pointing\n at Ortharsyne, not Arciela. See what\n you can learn about the blade.",s={"An Extraordinary Gentleman"}},
      [220] = {n="The Order's Treasures",d="Mission Orders:\n Celennia Memorial Library may hold\n more information about Ortharsyne.",s={"The Order's Treasures"}},
      [222] = {n="August's Heirloom",d="Mission Orders:\n Teodor left you with a cryptic riddle\n on hearing about your investigations.\n Could Arciela be familiar with the\n tale?",s={"August's Heirloom"}},
      [224] = {n="Beauty and the Beast",d="Mission Orders:\n Arciela has been abducted by a\n denizen of Ulbuka! Hurry to the jungle\n and find her!",s={"Beauty and the Beast"}},
      [226] = {n="Wildcat with a Gold Pelt",d="Mission Orders:\n After stumbling upon Ingrid in the\n jungle, the exorcist reports that\n Arciela has been abducted by an\n aureate wildcat of gigantic\n proportions. Learn how alliance\n officials will take the news by\n returning to Castle Adoulin.",s={"Wildcat with a Gold Pelt"}},
      [228] = {n="In Search of Arciela",d="Mission Orders:\n The priory has declared it will\n dispatch a search party to look for\n Arciela. While most are impressed by\n Vortimere's largesse, Rosulatia's pome\n glows a cautionary shade of red. Head\n to the Pioneers' Coalition to find out\n if there truly is cause for concern.",s={"In Search of Arciela"}},
      [232] = {n="Looking For Leads",d="Mission Orders:\n The Scouts' Coalition apparently picks\n up the chaff from the jungle rumor\n mill. Make for this veritable gossip\n dredging service before time runs\n out for Arciela.",s={"Looking For Leads"}},
      [234] = {n="Drifting Northwest",d="Mission Orders:\n Margret proffers that Kumhau, the\n beast regent of Eastern Ulbuka, is\n likely to know the most about any\n mountainous felines prowling the\n wilds. Make the trek to Kamihr Drifts\n and parlay with him.",s={"Drifting Northwest"}},
      [236] = {n="Kumhau, the Flashfrost Naakual",d="Mission Orders:\n You survived the treacherous meeting\n with Kumhau, who intimates that there\n must be a reason behind the\n princess's abduction. This reason is\n likely to be found in the tiger's den,\n in the southwest of Kamihr Drifts.",s={"Kumhau, the Flashfrost Naakual"}},
      [242] = {n="Soul Siphon",d="Mission Orders:\n The princess may not have suffered a\n scratch, but it turns out that Ingrid--\n not the wildcat--is the one who\n wanted to get her paws on Arciela\n all along!",s={"Soul Siphon"}},
      [244] = {n="Stonewalled",d="Mission Orders:\n Ingrid made off with Arciela's soul,\n but ran into a horde of towering\n statues from ages past. Bore through\n these colossi with your martial\n prowess and leave them in the dust.",s={"Stonewalled"}},
      [248] = {n="Salvation",d="Mission Orders:\n Now that Ingrid has admitted defeat\n and handed over the soul siphon, it is\n time to return this animus to Arciela.",s={"Salvation"}},
      [250] = {n="Glimmer of Portent",d="Mission Orders:\n By raising Ortharsyne high, Arciela\n unwittingly called forth the \"Scourge\n of the Land.\" Is this alabaster\n wyvern an omen of destruction or a\n savior sent by the Goddess?\n Whichever it is, Arciela has resolved\n to make contact with the dragon.",s={"Glimmer of Portent"}},
      [252] = {n="The Serpentine Labyrinth",d="Mission Orders:\n Just when things were settling down,\n a problem has arisen at the Couriers'\n Coalition. Head over there and figure\n out what is going on, as per Lhe\n Lhangavo's orders.",s={"...Into the Fire"}},
      [254] = {n="Melvien de Malecroix",d="Mission Orders:\n The minister of finance is normally\n impeccable with documents, but\n recent slipups have caused chaos to\n descend upon the Couriers' Coalition.\n They desperately need help filling a\n certain order from the Middle Lands.",s={"Melvien de Malecroix"}},
      [256] = {n="Courier Catastrophe",d="Mission Orders:\n The Couriers' Coalition has asked for\n the materials used in crafting bison\n jackets. Collect the required articles\n and deliver them safely to the\n warehouse on the waterfront.",s={"Courier Catastrophe"}},
      [258] = {n="Done and Delivered",d="Mission Orders:\n Now that the warehouse finally has\n enough materials to fill its order,\n make for the Couriers' Coalition\n building and spread the word.",s={"Done and Delivered"}},
      [260] = {n="Ministerial Whispers",d="Mission Orders:\n Melvien de Malecroix's ministerial\n dereliction has finally been verified.\n Return to the Pioneers' Coalition to\n make your official report.",s={"Ministerial Whispers"}},
      [262] = {n="A Day in the Life of a Pioneer",d="Mission Orders:\n Everything seems to be running\n smoothly once more, and the\n Pioneers' Coalition has returned to\n normal. Yet, what has become of\n Minister Melvien?",s={"A Day in the Life of a Pioneer"}},
      [264] = {n="Lighting the Way",d="Mission Orders:\n Arciela is certain that Ortharsyne has\n shown her the way, and that it leads\n to the summit of Mount Kamihr. Find\n the path amidst the snowbanks in\n Kamihr Drifts so that you two can\n climb the mountain.",s={"Lighting the Way"}},
      [266] = {n="Sajj'aka",d="Mission Orders:\n Awaiting you at the peak of\n Mount Kamihr was Sajj'aka, a serpent\n with a reputation for heralding\n realm-wide upheaval and a stubborn\n demeanor. Head back to Adoulin to\n research more on Ulbukan history so\n that he will be more receptive.",s={"Sajj'aka"}},
      [268] = {n="Studying Up",d="Mission Orders:\n You have learned all you can at\n Celennia Memorial Library. Return to\n Mount Kamihr and seek another\n audience with Sajj'aka.",s={"Studying Up"}},
      [270] = {n="A Vow of Truth",d="Mission Orders:\n Sajj'aka has revealed that the doors\n to the labyrinth are beginning to\n open, and Hades' revival is imminent.\n Unless Sajj'aka returns to fighting\n form, there is no chance of staving\n off these sinister forces. Yet where\n could the holy dragon's scales be...?",s={"A Vow of Truth"}},
      [272] = {n="Darrcuiln",d="Mission Orders:\n You have once again met with\n Darrcuiln, this time in Woh Gates.\n Follow his lead.",s={"Darrcuiln"}},
      [274] = {n="The Gates",d="Mission Orders:\n Chasing after Darrcuiln, you stumbled\n upon hordes of umbrils fighting\n leafkins. Who is the strange man\n fighting alongside the woodland\n creatures? Assist them in battle and\n find out the truth.",s={"The Gates"}},
      [278] = {n="Morimar",d="Mission Orders:\n The man calls himself Morimar--one of\n the generals who fought alongside the\n founder king. He has an inkling as to\n where Sajj'aka's scales may lie.\n Return to Mount Kamihr with him and\n seek yet another audience.",s={"Morimar"}},
      [280] = {n="A New Force Arises",d="Mission Orders:\n Morimar proffers that Sajj'aka's\n scales have been sealed deep within\n the labyrinth. Employ the holy\n dragon's protection to access areas\n of Ra'Kaznar previously sealed off,\n and find his scales.",s={"A New Force Arises"}},
      [282] = {n="The Sacred Sapling",d="Mission Orders:\n Sajj'aka has provided you with a\n sapling that can be used to heal the\n World Tree by utilizing its roots. But\n how...? The only way is to ask the\n World Tree itself...and the answer may\n lie in Castle Adoulin.",s={"The Sacred Sapling"}},
      [284] = {n="Tree Grafting",d="Mission Orders:\n Ygnas indicated that the best way to\n heal the World Tree would be by\n grafting the sapling Sajj'aka gave you\n onto it, left you with a vision of a\n strange wooded area, and fell into a\n deep slumber. The Pioneers' Coalition\n may be able to provide some insight.",s={"Tree Grafting"}},
      [286] = {n="A Shrouded Canopy",d="Mission Orders:\n Levil at the Pioneers' Coalition has\n shared an unusual rumor with you: a\n strange forest is said to lie within the\n innermost recesses of Kamihr Drifts.\n Head there to confirm his story.",s={"A Shrouded Canopy"}},
      [288] = {n="Leafallia",d="Mission Orders:\n As the sacred home of the leafkin,\n Leafallia is the place where the World\n Tree was first planted in Ulbuka.\n Explore the area while you wait for\n Arciela to arrive.",s={"Leafallia"}},
      [290] = {n="Rosulatia's Promise",d="Mission Orders:\n The leafkin queen, not content to be\n a bystander, has been watching you\n and Arciela the whole time...and has\n chosen to believe that your intentions\n are good. Report back to Morimar\n when you have finished exploring\n Leafallia.",s={"Rosulatia's Promise"}},
      [292] = {n="The Lightsland",d="Mission Orders:\n Melvien's sudden betrayal has shocked\n Arciela, and Morimar was forced to\n put him down before all was lost.\n Despite this, Rosulatia's ritual was\n successful. Return to Adoulin and\n explain Melvien's fate.",s={"The Lightsland"}},
      [294] = {n="The Light of Dawn Comes...",d="Mission Orders:\n Arciela and Ygnas have bestowed a\n favor on you for your service to the\n city. They will surely be counting on\n you in the months ahead.",s={"The Light of Dawn Comes..."}},
      [296] = {n="Cries from the Deep",d="Mission Orders:\n The Twelve Orders are in utter\n disarray, owing to Melvien's untimely\n demise. Check to see how Arciela is\n holding up.",s={"Cries from the Deep"}},
      [298] = {n="Seeds of Doubt",d="Mission Orders:\n Arciela would certainly be cheered up\n with a gift of tomatoes freshly\n picked from the Rala Waterways.",s={"Seeds of Doubt"}},
      [300] = {n="The Tomatoes of Wrath",d="Mission Orders:\n Fremilla has passed on a message that\n Arciela has something to share with\n you. Meet her back at Castle Adoulin.",s={"The Tomatoes of Wrath"}},
      [302] = {n="A Grave Mistake",d="Mission Orders:\n Rala Waterways, site of the founder\n king's grave, serves as a magical seal\n sheltering Adoulin from evil--yet the\n seal has begun to falter. Head to the\n waterways to assess what has\n transpired.",s={"A Grave Mistake"}},
      [306] = {n="An Emergency Convocation",d="Mission Orders:\n The ward protecting the city has not\n just weakened, but instead now\n beckons evil to the city. Arciela has\n called a meeting of the Twelve Orders\n to discuss the situation. Return to\n the castle after the ministers and\n maesters have had time to assemble.",s={"An Emergency Convocation"}},
      [308] = {n="Balamor, the Deathborne Xol",d="Mission Orders:\n An eccentric jester named Balamor\n threw the assembly into an uproar\n with his appearance, then vanished.\n Though the hearing was immediately\n recessed, the castle should open its\n gates again after the situation has\n stabilized.",s={"Balamor, the Deathborne Xol"}},
      [310] = {n="Anagnorisis",d="Mission Orders:\n The shock of what resulted from\n Balamor's emergence has caused\n Arciela to lock herself away in her\n chambers. Meanwhile, Ygnas has asked\n that his family's heirloom necklace be\n returned, to which Ploh Trishbahk has\n agreed to act as liaison.",s={"Anagnorisis"}},
      [312] = {n="Just the Thing",d="Mission Orders:\n The necklace returned, it is now time\n to procure a gift sure to raise\n Arciela's spirits, as per Ingrid's\n advice.",s={"Just the Thing"}},
      [314] = {n="Sugarcoated Salvation",d="Mission Orders:\n Deliver to Arciela the book she has\n often been spotted reading in the\n Celennia Memorial Library posthaste.",s={"Sugarcoated Salvation"}},
      [316] = {n="Arciela's Resolve",d="Mission Orders:\n Your kind words have instilled\n confidence in the princess once more.\n In thanks, Ygnas has bequeathed to\n you an item used in accessing the\n founder king's tomb in\n Rala Waterways, where he says\n Balamor resides.",s={"Arciela's Resolve"}},
      [318] = {n="Balamor's Ruse",d="Mission Orders:\n Ygnas was correct, and the evil clown\n was hiding in that tomb. A true\n enigma, Balamor has hidden statue\n segments in the monsters that roam\n the waterways and implores you to\n find them.",s={"Balamor's Ruse"}},
      [320] = {n="The Charlatan",d="Mission Orders:\n Balamor reveals that Hades is the\n ringleader behind this foul plot, and\n that defeating him will remove the\n curse afflicting so many Adoulinians.\n Before marching into his throne room\n in Ra'Kaznar Turris, however, it might\n be best to visit Castle Adoulin.",s={"The Charlatan"}},
      [324] = {n="Royal Blessings",d="Mission Orders:\n Hopefully the newly empowered\n heirloom Ygnas supplied proves of\n some worth, now that the\n final confrontation is nigh.",s={"Royal Blessings"}},
      [326] = {n="Hades",d="Mission Orders:\n The flood of ill tidings from the\n front lines shows no signs of\n relenting, and Arciela has not\n stopped by the coalition in weeks.\n Head to the castle and find her.",s={"Arboreal Rumors"}},
      [328] = {n="Arciela's Missive",d="Mission Orders:\n Although Ploh Trishbahk shooed\n you away from the castle gates,\n she secretly provided you with a\n note from Arciela. Perhaps you\n should take a look at it.",s={"Arciela's Missive"}},
      [330] = {n="Heroes, Unite!",d="Mission Orders:\n Arciela postulates that the other\n two members of the Xol Triumvirate\n have resurrected. Find the ancient\n heroes who once struggled against\n them.",s={"Heroes, Unite!"}},
      [332] = {n="A Portent Most Ominous",d="Mission Orders:\n Morimar and Sajj'aka are convinced\n that the ill omens herald the return\n of the triumvirate. Make haste to\n Leafallia to learn more about\n Ashrakk and Dhokmak.",s={"A Portent Most Ominous"}},
      [334] = {n="Yggdrasil Beckons",d="Mission Orders:\n Rosulatia has bequeathed upon you\n the ability to conquer Dhokmak and\n Ashrakk. Head with Morimar and\n Darrcuiln to Cirdas Caverns and\n Yorcia Weald to do just that.",s={"Yggdrasil Beckons"}},
      [336] = {n="Returning to the Trees",d="Mission Orders:\n The two members of the triumvirate\n have been toppled at last, removing\n all threats to the World Tree...but\n what will Arciela think when she\n finds out you tricked her? Head\n back to Leafallia to find out.",s={"Returning to the Trees"}},
      [338] = {n="The Key to the Turris",d="Missions Orders:\n Balamor provided an unexpected\n message during a surprise visit: the\n blood sigils are keys to entering\n Ra'Kaznar Turris, where Hades\n awaits. End his destruction of\n Ulbuka.",s={"The Key to the Turris"}},
      [342] = {n="Teodor's Summons",d="Mission Orders:\n Your entourage fled Hades' trap,\n only to find Teodor waiting. He\n provides a few words before\n departing for Mount Kamihr, where\n he bids you to join him.",s={"Teodor's Summons"}},
      [344] = {n="The Seventh Guardian",d="Mission Orders:\n Teodor reveals that he was the\n previous Deathborne Xol, and a new\n blood sigil has been inscribed onto\n his soul. Head to Watergarden\n Coliseum to sever the sigil and end\n his torment.",s={"The Seventh Guardian"}},
      [346] = {n="Watery Grave",d="Mission Orders:\n Teodor's past is now an open book,\n one riddled with cryptic passages.\n Can you overcome him to earn the\n right to challenge Hades?",s={"Watery Grave"}},
      [350] = {n="Blood for Blood",d="Mission Orders:\n With the final blood sigil removed,\n Hades is vulnerable. Ra'Kaznar\n Turris awaits.",s={"Blood for Blood"}},
      [352] = {n="Reckoning",d="Mission Orders:\n Morimar and Darrcuiln have fallen\n trembling before Hades. Do not let\n their sacrifices be in vain.",s={"Reckoning"}},
      [356] = {n="Abomination",d="Mission Orders:\n Hades has shed every last vestige\n of his humanity and reawakened as\n a higher power. End him, once\n and for all.",s={"Abomination"}},
      [360] = {n="Undying Light",d="Mission Orders:\n Yggdrasil smiles down upon all of\n Eastern Ulbuka. Triumphantly return\n to Adoulin.",s={"Undying Light"}},
      [368] = {n="The Light Within",d="Mission Orders:\n Arciela's smile lights up the city,\n the twelve orders are united, and\n peace has been brought to Adoulin\n at last. Adoulin's future is bright\n with a new queen to guide them.",s={"The Light Within"}},
      [999] = {n="fin",s={"fin"}},
      [1000] = {n="To begin SoA...",d="Examine the Tales' Beginning in\n Northern San d'Oria (J-10),\n Bastok Markets (I-8), or\n Windurst Woods (J-10)."},
    }},
    rov = { name = "Rhapsodies of Vana'diel", ids = {
      [0] = {n="Rhapsodies of Vana'diel",d="�@Even the slightest ripple can cause an\n�@unstoppable cascade..."},
      [110] = {n="Chapter One: Creation and Rebirth",d="Mission Orders:\n A cryptic vision from the crystal has\n played in your mind. A strange woman\n bathed in light descended from the\n mothercrystal in search of someone.\n What is the land of which she spoke?\n Perhaps someone in Selbina or Mhaura\n could provide clues.",s={"Resonance"}},
      [111] = {n="Emissary from the Seas",d="Mission Orders:\n You have been encouraged to meet\n with the town's leader. Make haste.",s={"Emissary from the Seas"}},
      [112] = {n="Set Free",d="Mission Orders:\n The town's leader has informed you\n that Gilgamesh is looking for a\n particular adventurer and that he\n wants some goods. Mhaura: three\n mandragora dewdrops from pygmaioi.\n Selbina: three clumps of bee pollen\n from huge wasps.",s={"Set Free"}},
      [114] = {n="The Beginning",d="Mission Orders:\n Gilgamesh claims that he chanced\n upon a young woman while sailing the\n stormy western seas, and wants you\n to meet her in Norg. Speak to his\n crew when you are ready to leave, but\n those with Gilgamesh's letter of\n introduction should use it first.",s={"The Beginning"}},
      [118] = {n="Flames of Prayer",d="Mission Orders:\n You have met Iroha, a priestess of\n Reisenjima Sanctorium. She has\n somehow descended from the future,\n and claims that the world will be\n consumed if it continues on its current\n path. Yet she vanished without a trace\n --ask Gilgamesh what to do next.",s={"Flames of Prayer"}},
      [120] = {n="The Path Untraveled",d="Mission Orders:\n Gilgamesh's daughter, Lion, may be\n able to find something out. Complete\n your home nation's missions up through\n rank 2 first. If you already have, follow\n the orb's guidance and seek her out\n by the Crag of Holla, Dem, or Mea.",s={"The Path Untraveled"}},
      [126] = {n="At the Heavens' Door",d="Mission Orders:\n You have succeeded in meeting Lion\n before the mothercrystal. She, too,\n has seen visions, but hers have\n implored her to go to Qufim Island.",s={"At the Heavens' Door"}},
      [128] = {n="The Lion's Roar",d="Mission Orders:\n A dark vortex has surfaced in Qufim\n Island, with a strange beast emerging\n from the depths. Vanquish it to\n proceed in your journey.",s={"The Lion's Roar"}},
      [130] = {n="Eddies of Despair",d="Mission Orders:\n Brave the horrors of the vortex and\n see what lies beyond.",s={"Eddies of Despair"}},
      [134] = {n="A Land After Time",d="Mission Orders:\n Beyond the vortex a strange world\n unfurls--and it looks not unlike\n Zi'Tah. The place may be what is\n called Escha. Follow the crystal's call\n to Holla, Dem, or Mea.",s={"A Land After Time"}},
      [136] = {n="Fate's Call",d="Mission Orders:\n Lion has seen another vision. The orb\n you received must be filled with\n sufficient light to stop the\n encroaching darkness. Vanquish the\n Shadow Lord before the reckoning\n comes. If you have already done so,\n report to Gilgamesh in Norg.",s={"Fate's Call"}},
      [138] = {n="What Lies Beyond",d="Mission Orders:\n The visions do not cease, with Iroha's\n voice emanating from the orb. Head\n to Norg.",s={"What Lies Beyond"}},
      [140] = {n="The Ties That Bind",d="Mission Orders:\n Ill tidings abound. Something is\n causing sailors to take leave of their\n senses, with a strange ringing\n reminding you of what occurred in\n Escha - Zi'Tah. See what is happening\n in Sea Serpent Grotto.",s={"The Ties That Bind"}},
      [142] = {n="Impurity",d="Mission Orders:\n The great Siren is the cause of the\n recent disturbances plaguing Norg, and\n she claims that Iroha was not the only\n one who came to the present time from\n the future. The masked man\n attacked Iroha, who faded into\n nothingness. Chase after him.",s={"Impurity"}},
      [144] = {n="The Lost Avatar",d="Mission Orders:\n Siren and the masked man attempted\n to conjure forth another vortex in\n Yuhtunga Jungle in a bid to cause\n Escha to spread further. Fight the\n winged beast and stop her before it's\n too late.",s={"The Lost Avatar"}},
      [148] = {n="Volto Oscuro",d="Mission Orders:\n Siren has regained her senses and\n shared with you what the future\n holds. Volto Oscuro's power is\n immense, and it will stop at nothing\n to fulfill its goals. Report what you\n learned to Gilgamesh back in Norg.",s={"Volto Oscuro"}},
      [150] = {n="Ring My Bell",d="Mission Orders:\n Gilgamesh and his compatriot have\n decided to search for a man from the\n Far East by the name of Tenzen.\n Explore Escha - Zi'Tah while they\n look for clues.",s={"Ring My Bell"}},
      [152] = {n="Chapter Two: Revitalization",d="Mission Orders:\n A samurai from the Far East, Tenzen,\n has made landfall in Norg, claiming\n the orb can provide guidance to those\n who wield it. This time, a vision bids\n you to head for Delkfutt's Tower.",s={"Spirits Awoken"}},
      [154] = {n="Crashing Waves",d="Mission Orders:\n Having heard about Tenzen, Iroha has\n headed toward Ru'Lude Gardens in\n Jeuno. However, she warns that you\n must pass the trials posed to you by\n the chains of Promathia to move\n forward. Perhaps a fateful\n meeting awaits you along the way.",s={"Crashing Waves"}},
      [156] = {n="Call to Serve",d="Mission Orders:\n Tenzen learned about the darkness\n that the future holds and insists that\n it can be changed. Your bonds with\n him caused the orb to flare up and\n open a new path before you. The next\n step is to meet with Prishe in Port\n Jeuno.",s={"Call to Serve"}},
      [158] = {n="Numbering Days",d="Mission Orders:\n Your bonds with Prishe have helped\n the orb shine a little bit brighter than\n before--yet Iroha is nowhere to be\n seen. Work together with your\n companions to find her.",s={"Numbering Days"}},
      [160] = {n="Inescapable Binds",d="Mission Orders:�@\n Iroha was assaulted by the\n ambassador, who stole away the\n blessing of Phoenix. Prishe heard that\n he was off to Aht Urhgan to find the\n Astral Candescence, which could\n prove pivotal. The Tenshodo in Jeuno\n can provide transport to Aht Urhgan.",s={"Inescapable Binds"}},
      [162] = {n="Desert Winds",d="Mission Orders:\n Ships to Aht Urhgan regularly depart\n from Mhaura. It's time for you to\n make the journey.",s={"Desert Winds"}},
      [164] = {n="Ever Forward",d="Mission Orders:\n You successfully rendezvoused with\n Tenzen in Aht Urhgan, and have been\n tasked with infiltrating the palace, if\n possible, or searching out Gessho and\n joining Salaheem's Sentinels\n otherwise.",s={"Ever Forward"}},
      [168] = {n="The Endless Sky",d="Mission Orders:\n Gessho reported that the ambassador\n snuck into the palace. If you work\n hard at Salaheem's Sentinels, you may\n just be able to earn enough trust with\n the Empire to go in yourself...",s={"The Endless Sky"}},
      [170] = {n="Aphmau's Light",d="Mission Orders:\n You have passed the third challenge\n posed to you, and should make haste\n for the palace in Aht Urhgan. If\n something has happened to Aphmau,\n make sure she is safe before paying\n your respects.",s={"Aphmau's Light"}},
      [172] = {n="Reunited",d="Mission Orders:\n Aphmau revealed that the\n ambassador's underlings are after the\n Astral Candescence. She has offered\n her aid, and your orb has been filled\n with light once more. Head to Walahra\n Temple's Hall of Binding.",s={"Reunited"}},
      [174] = {n="Take Wing",d="Mission Orders:\n The Hall of Binding was attacked,\n with a masked woman assaulting the\n Candescence. Thankfully, Tenzen and\n Kagero were able to wrest back\n Phoenix's blessing, yet a number of\n Immortals were injured and the woman\n escaped. Return to Shararat Teahouse.",s={"Take Wing"}},
      [176] = {n="Prime Number",d="Mission Orders:\n The Astral Candescence was likely\n targeted due to Aht Urhgan's prime\n avatar. They hope to use its power to\n envelop not just the past, but also\n the present. Foil their plot by heading\n to the Alzadaal Undersea Ruins.",s={"Prime Number"}},
      [178] = {n="From the Ruins",d="Mission Orders:\n Alexander aided Phoenix in reviving\n Iroha. He knows much about the\n encroaching darkness, revealing that\n it's something far more sinister than\n the absence of light. Iroha has been\n brought back to Aht Urhgan to\n recover, where she and Aphmau await.",s={"From the Ruins"}},
      [180] = {n="Cauterize",d="Mission Orders:\n The world has rejected Iroha's\n presence, but Alexander believes Cait\n Sith might have an answer. Cavernous\n maws in either Batallia Downs,\n Rolanberry Fields, or Sauromugue\n Champaign may enable you to meet\n with the enigmatic feline.",s={"Cauterize"}},
      [186] = {n="Uncertain Destinations",d="Mission Orders:\n Cait Sith gave you a special item\n used to enter the Walk of Echoes\n after hearing your explanation about\n what may come to pass. Enter the\n Walk of Echoes from either Batallia\n Downs, Rolanberry Fields, or\n Sauromugue Champaign.",s={"Uncertain Destinations"}},
      [188] = {n="Ganged Up On",d="Mission Orders:\n Only Altana can make Vana'diel\n accept Iroha's presence in this world,\n and the first step to reaching her is\n to cull the threats that Vana'diel\n faces. Continue with the Wings of the\n Goddess missions if you have not met\n Lilisette.",s={"Ganged Up On"}},
      [191] = {n="Sacrifice",d="Mission Orders:\n Though you have met Lilisette, she\n has no idea how to meet Altana. On\n the bright side, your orb has been\n granted another spark of light. Cait\n Sith has beseeched you for aid,\n saying that the ambassador has\n infiltrated the Walk of Echoes.",s={"Sacrifice"}},
      [194] = {n="Somber Dreams",d="Mission Orders:\n The ambassador threatens to absorb\n dark energy from Atomos and must be\n stopped. His minion Cetus has\n swallowed you whole--vanquish him\n before proceeding.",s={"Somber Dreams"}},
      [200] = {n="Of Light and Darkness",d="Mission Orders:\n You have successfully vanquished\n Cetus, but the ambassador escaped,\n his plan partially successful. Meet\n with Iroha and discuss your next\n plans--but first, head back to Norg.",s={"Of Light and Darkness"}},
      [202] = {n="Temporary Farewells",d="Mission Orders:\n Gilgamesh seemed skittish about a\n new vortex to Escha that opened in\n Misareaux Coast. Iroha journeyed\n there alone, seemingly preferring to\n travel on her own. Head to Misareaux\n Coast and see what you can learn.",s={"Temporary Farewells"}},
      [204] = {n="Brushing Up",d="Mission Orders:\n Iroha has been off working on her\n inner self, and your recent discussions\n with her have encouraged her to ask\n you for training. Speak with her once\n more.",s={"Brushing Up"}},
      [206] = {n="Keep On Giving",d="Mission Orders:\n Give Iroha a little gift to help\n encourage her to stick to her training\n regimen. The gifts are as follows:\n strength training: a beef stewpot;\n endurance training: a serving of zaru\n soba; style training: 30 spicy\n crackers.",s={"Keep On Giving"}},
      [208] = {n="Past Imperfect",d="Mission Orders:\n Though satisfied with her training,\n Iroha's burden remains heavy, and she\n is poised to take on the ambassador\n alone. The two of you have decided\n to seek out the races of eld. Return\n to Norg to discuss things.",s={"Past Imperfect"}},
      [209] = {n="The Cursed Temple",d="Mission Orders:\n Gilgamesh has pointed you toward the\n Temple of Uggalepih, where you\n should be able to find clues.\n Depending on your current progress in\n Rise of the Zilart, there may be some\n things you must take care of first.",s={"The Cursed Temple"}},
      [211] = {n="Wisdom of Our Forefathers",d="Mission Orders:\n Grav'iton, one of the few surviving\n Kuluu, has offered to guide you.\n Examine the granite door to see what\n she has to say.",s={"Wisdom of Our Forefathers"}},
      [212] = {n="Where Divinities Collide",d="Mission Orders:\n Grav'iton decisively stated that you\n must pass through the crystals in\n order to reach Altana. The logical\n place to start would be in the Crags\n of Holla, Dem, and Mea.",s={"Where Divinities Collide"}},
      [214] = {n="Visions of Dread",d="Mission Orders:\n The crystals have shown you a vision\n of Selh'teus speaking with higher\n powers. Yet a shocking appearance by\n the ambassador jolted you awake\n without learning more. To where will\n these half-truths lead? Try to sort\n things out.",s={"Visions of Dread"}},
      [216] = {n="To the Skies",d="Mission Orders:\n You discussed the next step with\n Iroha and Tenzen, but ultimately were\n unable to figure out how to meet with\n Altana. Siren's decision to clash with\n the ambassador is of primary concern,\n so head back to Norg to draft your\n next plan of attack.",s={"To the Skies"}},
      [218] = {n="Escha - Ru'Aun",d="Mission Orders:\n There have been reports of two Sirens\n prowling Misareaux Coast and Escha -\n Ru'Aun. That seems as good a place\n as any to start.",s={"Escha - Ru'Aun"}},
      [222] = {n="The Decisive Heroine",d="Mission Orders:\n Siren awaited you in Escha - Ru'Aun,\n where she revealed a startling truth:\n not even Altana is able to stop the\n encroaching darkness and the cloud\n of nothingness. But don't lose heart--\n meeting with Iroha comes first.",s={"The Decisive Heroine"}},
      [224] = {n="Fall from Grace",d="Mission Orders:\n The Sirens and Iroha were able to\n capture the ambassador, claiming that\n only a communion can banish him\n (and subsequently Iroha and the\n future Siren), but Balamor intervened\n and whisked the ambassador away.\n Take Siren's gift to the crystals.",s={"Fall from Grace"}},
      [226] = {n="Banishing the Darkness",d="Mission Orders:\n Your best hope to meet Altana is to\n go to Reisenjima. Selh'teus has vowed\n to create a new crystal there to\n banish the Emptiness, and bids you\n seek one with dominion over magic to\n help. A friend in Norg may know\n someone who fits the bill.",s={"Banishing the Darkness"}},
      [228] = {n="Over the Rainbow",d="Mission Orders:\n Iroha claimed that a crystal exists in\n Reisenjima in her future, which should\n be no cause for alarm. Over in Norg,\n your allies have hesitantly encouraged\n you to visit Shantotto in Windurst\n Walls.",s={"Over the Rainbow"}},
      [230] = {n="Cacophonous Discord",d="Mission Orders:\n Shantotto, Koru-Moru, and Yoran-Oran\n discussed Koru-Moru's latest\n experiment, which reacts to the\n presence of darkness--a darkness\n which has settled in Escha - Ru'Aun.",s={"Cacophonous Discord"}},
      [232] = {n="Eddies of Despair",d="Mission Orders:\n Cid and his team have headed to\n Escha - Ru'Aun, where a vortex is\n sucking up the crystals' power. What\n lies beyond? Be on your guard as you\n proceed.",s={"Eddies of Despair"}},
      [234] = {n="Pretender to the Throne",d="Mission Orders:\n The dark jester Balamor was working\n to drain the crystals of power in an\n attempt to fashion a new world in his\n image. Fight Balamor to draw his\n attention away from Selh'teus while\n the Kuluu attempts to seal the\n vortex.",s={"Pretender to the Throne"}},
      [238] = {n="Banished",d="Mission Orders:\n Your victory over Balamor has\n protected the crystals and Selh'teus\n banished the fiend back into his own\n vortex. Return to Norg to check up\n on Iroha.",s={"Banished"}},
      [240] = {n="Call of the Void",d="Mission Orders:\n What happened to the ambassador\n after Balamor was culled? There is no\n time to rest--try to find a way to\n meet Altana while he is preoccupied\n by visiting either Holla, Dem, or Mea.",s={"Call of the Void"}},
      [244] = {n="Both Paths Taken",d="Mission Orders:\n The time has come for Selh'teus to\n create a new mothercrystal in\n Reisenjima. Just as the plan was to\n be set in motion, the ambassador\n appeared to challenge Iroha. Stop him\n in his tracks.",s={"Both Paths Taken"}},
      [250] = {n="The Man Behind the Mask",d="Mission Orders:\n Though victorious over the\n ambassador, you were banished to a\n land without time where you met your\n future self. Is Vana'diel working with\n you, or against you? Where is Iroha?\n Rendezvous with your allies in Norg.",s={"The Man Behind the Mask"}},
      [252] = {n="Uncertain Futures",d="Mission Orders:\n Gilgamesh and your allies from across\n Vana'diel have gathered in Norg to\n check on you, but Iroha is nowhere to\n be found. She must have been hurled\n back to Reisenjima in the struggle. If\n only you could secure passage there...",s={"Uncertain Futures"}},
      [254] = {n="Chapter 3: Reckoning",d="Mission Orders:\n The ambassador's plan is more\n sinister than imagined. He infused\n your soul with darkness in an attempt\n to hinder you. Yet you have been left\n with a tiny song of hope--what could\n it mean?",s={"Darkness Beckons"}},
      [258] = {n="The Brewing Storm",d="Mission Orders:\n You have set foot in Reisenjima at\n long last, reuniting with Iroha in the\n process. She spends each night\n staving off the threat posed by\n narakas in the area. Vanquish three of\n them to buy her some time.",s={"The Brewing Storm"}},
      [260] = {n="The River Runs Red",d="Mission Orders:\n With the narakas vanquished, all that\n remains at present is to report back\n to Iroha.",s={"The River Runs Red"}},
      [262] = {n="The Crucible",d="Mission Orders:\n Iroha's future provides clues about\n the ambassador. The only way to\n combat his darkness is to gather more\n light for your orb. Your next\n destination is Adoulin. If necessary,\n speak with Darcia in Lower Jeuno to\n start the Seekers of Adoulin missions.",s={"The Crucible"}},
      [263] = {n="Forward Thinking",d="Mission Orders:\n You have passed through Iroha's\n fourth gate. Head to Ceizak\n Battlegrounds to learn more.",s={"Forward Thinking"}},
      [264] = {n="Tears of the Generals",d="Mission Orders:\n Iroha clashed with the ambassador,\n who claimed that the Reckoning rests\n on the orb activating. Gather\n information about Balamor in Castle\n Adoulin and perhaps glean some clues\n about changing the outcome of the\n Reckoning.",s={"Tears of the Generals"}},
      [266] = {n="What He Left Behind",d="Mission Orders:\n Arciela has provided information on\n where to find Balamor. Head to Rala\n Waterways and seek out the black\n butterflies.",s={"What He Left Behind"}},
      [268] = {n="Gone but Not Forgotten",d="Mission Orders:\n According to Balamor, the orb Iroha\n gave you has something to do with\n the power of time. He will return what\n he took from you if you bring him a\n relic of the founder king. Look for it\n somewhere in Rala Waterways.",s={"Gone but Not Forgotten"}},
      [269] = {n="August Artifacts",d="Mission Orders:\n You have successfully procured the\n founder king's orb. Head back to\n speak with Balamor.",s={"August Artifacts"}},
      [270] = {n="Solemnity",d="Mission Orders:\n \"It all began with a stone...\" and what\n the stone's light purged was not the\n Emptiness, but rather the Cloud of\n Darkness. It has no consciousness, \n but is all-encompassing. What does\n Arciela have to say about Balamor's\n musings?",s={"Solemnity"}},
      [272] = {n="Eyes on You",d="Mission Orders:\n Arciela, who had been poring over\n tomes in Celennia Memorial Library,\n has an inkling that the Cloud of\n Darkness may be related to ruins\n located in the Middle Lands. Head to\n Li'Telor to investigate.",s={"Eyes on You"}},
      [274] = {n="Exploring the Ruins",d="Mission Orders:\n Deep within Ro'Maeve waited a\n representative of Jeuno--Esha'ntarl.\n She heard the rumors of the coming\n end and was looking to Iroha for\n answers. Follow her lead and head\n further into the ruins.",s={"Exploring the Ruins"}},
      [278] = {n="Become Something More",d="Mission Orders:\n Yve'noile claims that only a god can\n stand against the Cloud of Darkness.\n A human may be able to ascend, but\n the ambassador banished her before\n she could explain fully. Head to\n Reisenjima and consult with Selh'teus.",s={"Become Something More"}},
      [280] = {n="Unshakable Nightmares",d="Mission Orders:\n Part of Selh'teus's crystal must be\n cracked for you to become a god of\n light. What's more, you must also\n purge yourself of the ambassador's\n taint. Head to the Walk of Echoes to\n accomplish the latter task.",s={"Unshakable Nightmares"}},
      [282] = {n="What Remains of Hope",d="Mission Orders:\n Cait Sith used the dimensional\n compass to guide you to a fully\n empowered god of darkness, which\n may absorb all of your murk for its\n own ends. Steel yourself for battle\n and head further into the Walk of\n Echoes.",s={"What Remains of Hope"}},
      [286] = {n="Death Cares Not",d="Mission Orders:\n Cait Sith gave you one of her\n whiskers so that you would not lose\n your way. Progress even further in.",s={"Death Cares Not"}},
      [288] = {n="No Time like the Future",d="Mission Orders:\n The god of darkness is an all-\n encompassing entity in its otherwise\n desolate world. As you hoped,\n it absorbed all the darkness present\n within you--yet it used the opening\n to attack. Take it down.",s={"No Time like the Future"}},
      [292] = {n="Sin",d="Mission Orders:\n It seems the ambassador was\n controlled by the Cloud of Darkness,\n unable to complete its original\n mission. The god of darkness fused\n with it, awakening as an entirely new\n entity. It is beckoning you--go seek\n it out.",s={"Sin"}},
      [296] = {n="Penance",d="Mission Orders:\n The ambassador has become a dark\n god, showing you what the future\n holds. You split into two pure\n beings--one light, one dark. The dark\n entity became controlled by the\n cloud, bringing him to the present\n day.",s={"Penance"}},
      [298] = {n="Vessel of Light",d="Mission Orders:\n Having purged the darkness and\n learned the truth, you now have the\n potential to become a god of light.\n Return to Selh'teus.",s={"Vessel of Light"}},
      [300] = {n="The Lifestream of Reisenjima",d="Mission Orders:\n The god of light--you--and Altana are\n what led Iroha back to the past. To\n meet the Goddess of the Dawn, you\n must first set the disrupted lifestream\n in Reisenjima back on its proper\n course.",s={"The Lifestream of Reisenjima"}},
      [302] = {n="From West to East",d="Mission Orders:\n Three of your allies have assembled\n on Reisenjima to help you see things\n to their conclusion: Gilgamesh, Aldo,\n and Tenzen. Work with them to\n vanquish eleven of the panopts\n befouling the natural order.",s={"From West to East"}},
      [304] = {n="Good Things Come in Threes",d="Mission Orders:\n You have succeeded in vanquishing\n the panopts. Head back to the\n entrance of the Sanctorium to meet\n up with your compatriots.",s={"Good Things Come in Threes"}},
      [306] = {n="Tackling the Problem",d="Mission Orders:\n Your allies have also succeeded in\n culling their quarry. Return to the\n crystal and report your success to\n Selh'teus and Iroha.",s={"Tackling the Problem"}},
      [308] = {n="Way to Divinity",d="Mission Orders:\n Your returning the lifestream to its\n pure state has enabled Selh'teus to\n send you to Altana. What lies ahead\n is unclear--make sure you are\n prepared for the journey.",s={"Way to Divinity"}},
      [310] = {n="The Winds of Time",d="Mission Orders:\n You have shed the last vestiges of\n your humanity to become a god of\n light. Altana has revealed the key: the\n fledgling deities of light and darkness\n must engage in heated combat to\n brew up the \"winds of time.\" The\n Reckoning is at hand!",s={"The Winds of Time"}},
      [314] = {n="Calm After the Storm",d="Mission Orders:\n Your heroic efforts successfully\n dispersed the Cloud of Darkness, and\n what you have shed to become a god\n of light has returned to you, meaning\n you are mortal once more. Return to\n Reisenjima, where your allies await.",s={"Calm After the Storm"}},
      [318] = {n="Nary a Cloud in Sight",d="Mission Orders:\n The winds of time have cleansed\n every corner of the land, and what\n was once bleak is now bright.\n However, this also means Iroha will\n soon disappear from the world.\n Spend a few final moments with her\n outside.",s={"Nary a Cloud in Sight"}},
      [320] = {n="An Unending Song",d="Mission Orders:\n Though Iroha may be gone, peace has\n come to Vana'diel at last. Selh'teus's\n crystal continues to shine, and soon\n the Emptiness will be no more. But\n your adventures will never end so\n long as you continue unceasingly\n forward.",s={"An Unending Song"}},
      [324] = {n="A Deep Sleep",d="Mission Orders:\n You saw a vision of Iroha being\n overtaken by the Cloud of Darkness.\n Were all your efforts for naught? Is\n another struggle about to commence?\n Make haste for the crystal in\n Reisenjima.",s={"A Deep Sleep"}},
      [326] = {n="Guardians",d="Mission Orders:\n Fragments of the Cloud of Darkness\n remained in Reisenjima's crystal. The\n future is far from saved, and Iroha\n remains in this time. The avatars' help\n is paramount. Head to the stone circle\n in La Theine Plateau.",s={"Guardians"}},
      [328] = {n="Iroha in Distress",d="Mission Orders:\n Carbuncle and the other avatars have\n lent you their powers. With this, you\n should be able to enter the crystal in\n Reisenjima once more.",s={"Iroha in Distress"}},
      [330] = {n="Absolute Trust",d="Mission Orders:\n Alter egos of your most stalwart\n allies have given their all to stall for\n time in the struggle against the Cloud\n of Darkness. The time is at hand--\n steel yourself and enter the crystal!",s={"Absolute Trust"}},
      [332] = {n="The Orb's Radiance",d="Mission Orders:\n The avatars have succeeded in\n bringing Phoenix--and Iroha--to life\n once more. The time to stop the\n Cloud of Darkness is at hand! Should\n you falter, return to the stone circle\n in La Theine Plateau.",s={"The Orb's Radiance"}},
      [334] = {n="A Rhapsody for the Ages",d="Mission Orders:\n Having vanquished the Cloud of\n Darkness, you are certain that the\n future has been set on its proper\n course. Iroha has returned to her\n time, yet this is not the final\n goodbye. Someday, far in the future,\n you will be reunited once more.",s={"A Rhapsody for the Ages"}},
      [1000] = {n="To Start RoV...",d="�@Examine the Tales' Beginning in\n Southern San d'Oria (H-8),\n Northern San d'Oria (J-10),\n Port San d'Oria (H-9),\n Bastok Mines (I-9),\n Bastok Markets (I-8),\n Port Bastok (D-7),\n Windurst Waters (F-5),\n Windurst Walls (C-6),\n Port Windurst (B-5), or\n Windurst Woods (J-10)."},
    }},
    tvr = { name = "The Voracious Resurgence", ids = {
      [0] = {n="The Voracious Resurgence",d="As long-lost truths begin\n�@to come to life, it falls\n to you to uncover the source\n of what eats at Vana'diel\n from the inside."},
      [110] = {n="The Gloom Phantom's Approach",d="Mission Orders:\n�@According to Cornelia, a Galkan\n child was spotted wandering\n about the Zeruhn Mines\n in need of aid. Head to\n the Zeruhn Mines.",s={"The Gloom Phantom's Approach"}},
      [118] = {n="The Brygid Cup",d="Mission Orders:\n�@Raebrimm seems to be threatened\n by the black-clad Goblin. The\n plan to protect him: find\n the perfect disguise. Perhaps the\n stylist extraordinare, Brygid,\n can help you over in Bastok\n Markets.",s={"The Brygid Cup"}},
      [128] = {n="The Destiny Destroyers",d="Mission Orders: \n�@The black-clad Goblin seems\n�@to have given up on Raebrimm,\n�@but now's no time to rest on\n�@your laurels. The Mythril\n�@Musketeers are hot on the\n�@trail; head to Korroloka\n�@Tunnel to assist them.",s={"The Destiny Destroyers"}},
      [138] = {n="Kupipi's Dilemma",d="Mission Orders:\n A conflict between Shantotto \n and Kupipi is coming to a\n head. Shantotto asked Kupipi to\n fix an old outfit, but Kupipi\n doesn't recall such a request.\n Ask Sassa-Kotassa, Sheelala,\n and Habida-Jubida in Heavens Tower\n to find out who is right.",s={"Kupipi's Dilemma"}},
      [146] = {n="The Cardians' Duty",d="Mission Orders:\n Shantotto is lamenting that many\n seem to have memory issues of\n late. She thinks a sinister force\n is behind this. Aid Kupipi in\n getting to the bottom of it.",s={"The Cardians' Duty"}},
      [158] = {n="Zhuu Buxu's Gambit",d="Mission Orders:\n You have to retrieve the doll\n stolen from Heavens Tower\n with all due haste. A simple\n adventurer would attract little\n suspicion from the Yagudo.\n Your first task is to deliver\n a star-crested summons to\n Tosuka-Porika in the Optistery\n and receive further instructions.",s={"Zhuu Buxu's Gambit"}},
      [168] = {n="Star Onion Fortune",d="Mission Orders:\n The doll you retrieved from Giddeus\n is no more than a child's plaything.\n Return it to its owner near\n a warehouse near the waterfront in\n Windurst.",s={"Star Onion Fortune"}},
      [178] = {n="The Doll Whisperer",d="Mission Orders:\n Honoi-Gomoi is planning to parley\n with the Yagudo behind a magic\n tower in West Sarutabaruta.\n However, you have the egg that the\n Yagudo require. Disrupt their plans.",s={"The Doll Whisperer"}},
      [192] = {n="Dancing Prince",d="Mission Orders:\n A ball is set to take place at\n House Virgaut. You have been charged\n with helping ensure that Trion is fully\n prepared, including making sure there\n is no Orcish interference like last\n time. Rahal, leader of the Royal\n Knights, can tell you more.",s={"Dancing Prince"}},
      [202] = {n="Claidie's Concern",d="Mission Orders:\n Halver has another request on the eve\n of the ball. Trion once fell ill\n with a mysterious malady, and such\n a tragedy cannot be allowed to repeat.\n A special remedy is available, and you\n have been asked to procure it\n from Chalvatot.",s={"Claidie's Concern"}},
      [210] = {n="Curilla Unleashed",d="Mission Orders:\n Claidie, who was to be Trion's\n dance partner, is currently indisposed.\n Halver has recommended Altennia to\n be her replacement. Deliver his\n missive to her in Ranguemont\n Pass.",s={"Curilla Unleashed"}},
      [228] = {n="Run, Excenmille, Run!",d="Mission Orders:\n The ball was a rousing success.\n However, there have been reports\n of issues with a regiment\n dispatched to the north. Follow\n Prince Trion to where Rahal\n waits in the Royal Knights' Quarters.",s={"Run, Excenmille, Run!"}},
      [240] = {n="Of Knights and Orcs",d="Mission Orders:\n Slackjawed Mukdrom's forces have\n captured a contingent of the Carmine\n Swallows.\n The victims have doubtless been taken\n to Fei'Yin and require backup posthaste.\n Excenmille has chosen to examine the\n western half, so it falls to you to take\n the east side.",s={"Of Knights and Orcs"}},
      [256] = {n="Best Served Cold",d="Mission Orders:\n Gumbah has informed you that\n Raebrimm is in search of adventurers.\n Seek Drangord near the entrance\n in the Zeruhn Mines.",s={"Best Served Cold"}},
      [270] = {n="Cornelia's Call to Action",d="Mission Orders:\n Do'Bho Venomtail leads the Quadav\n assault, and an emergency\n meeting has been called in\n Bastok. War may well be on\n the horizon, and the Destiny\n Destroyers may be behind it all.\n Could it be related to the World\n Eater Egg? Head to Palborough Mines.",s={"Cornelia's Call to Action"}},
      [286] = {n="Naja the Ambitious",d="Mission Orders:\n The A.M.A.N. has asked Salaheem's\n Sentinels to investigate some\n goings-on. Defeat the monster that\n appears where slugs reside\n in Wajaom Woodlands and return with\n evidence of your kill.",s={"Naja the Ambitious"}},
      [298] = {n="Raubahn the Blue",d="Mission Orders:\n In the underground prison, Raubahn\n and his retinue shared quite a\n bevy of information with you, but\n you remain as vexed as ever.\n Now a soulflayer has taken residence\n nearby, with another strange seal\n appearing in Caedarva Mire. Convinced\n these incidents are connected, you\n head for Caedarva Mire to\n best the soulflayer.",s={"Raubahn the Blue"}},
      [310] = {n="Ghatsad's Quandary",d="Mission Orders:\n Ghatsad has been charged with\n finding additional information about\n Falak. The legends begin hundreds\n of years ago, and it appears\n that Goblins are the original\n source of the tales. Meet\n wtih Megomak in Mount Zhayolm\n and see what you can learn.",s={"Ghatsad's Quandary"}},
      [326] = {n="The Revelation",d="Mission Orders:\n Ghatsad's apprentices are concerned\n with his demeanor of late, as he\n is completely engrossed with\n learning more about Olduum.\n Head to Aydeewa Subterrane to\n assist with the investigation.\n The exact location: right\n past the area connecting the\n northern Wajaom Woodlands with\n Aydeewa Subterrane.",s={"The Revelation"}},
      [338] = {n="Tateeya's Worries",d="Mission Orders:\n Ghatsad's search continues apace,\n and he is on the verge of\n a breakthrough into the\n mysteries of Olduum.\n He has made a startling\n discovery and is a bit\n on edge. Ask his apprentices\n for more information.",s={"Tateeya's Worries"}},
      [352] = {n="The Seagull Phratrie",d="Mission Orders:\n Aznahf and Mutihb of the Seagull\n Phratrie are squabbling over Aznahf\n allegedly sinking a vessel that\n came into Mutihb's possession.\n Though a pteraketos may be at fault,\n none are sure if it's\n actually real. Survey the\n cliffs in the northwest of Arrapago\n Reef.",s={"The Seagull Phratrie"}},
      [362] = {n="The Sea Sage",d="Mission Orders:\n Bijoux, the apkallu elder,\n has provided you with a good\n deal of information. You must\n look for a breathing pearl\n to dive into the water and\n find the pteraketos. Bijoux\n notes that the Olduum civilization,\n once located in Wajaom Woodlands,\n may contain clues. Head\n for the designated location.",s={"The Sea Sage"}},
      [380] = {n="Sky, Moon, Incantrix",d="Mission Orders:\n Gessho and the Far Eastern Yagudo\n Reikuu believe that the World\n Eater Egg will give birth to an\n avatar that must be put down\n with extreme prejudice. They aim to\n reunite with their\n Middle Lands brethren and \n seek information on the black\n sword. You are to go procure\n it from the Goblin Incantrix.",s={"Sky, Moon, Incantrix"}},
      [392] = {n="Nii's Last Stand",d="Mission Orders:\n The black sword is a bit too\n inconvenient of a truth for\n some of the Yagudo. Reikuu has\n asked you to find out more about a\n 5,000-year-old incident that the\n Yagudo have forgotten about.\n Seek out Incantrix once more.",s={"Nii's Last Stand"}},
      [414] = {n="Dance of the Tengu",d="Mission Orders:\n Reikuu is angered that you assisted\n Nii Aquu in his training, evidently\n because sticking your nose in where\n it doesn't belong has threatened\n the burgeoning alliance between\n the Middle Lands Tengu and those\n of the traditional Tengu religion.\n Now Zhuu Buxu is here. Track him\n down near the waterfall in\n northwestern Reisenjima.",s={"Dance of the Tengu"}},
      [430] = {n="Raebrimm's Rebirth",d="Mission Orders:\n Gumbah and Cornelia are searching\n for Raebrimm. A simple look into\n the history of the Galka together\n with other information leads\n you to think he's headed for\n Zepwell Island. Ask Dancing\n Wolf in Rabao for help.",s={"Raebrimm's Rebirth"}},
      [440] = {n="Uran-Mafran of the Maelstrom",d="Mission Orders:\n Galka on their journey of rebirth\n are being targeted due to their\n knowledge of the Abyss.\n Gumbah and Oggbi have asked for\n your help in protecting the gates.\n Your first task is to head for\n Altepa Gate in the Western Altepa\n Desert and see what awaits you.",s={"Uran-Mafran of the Maelstrom"}},
      [452] = {n="Koru-Moru's Hypothesis",d="Mission Orders:\n Koru-Moru and Yoran-Oran take the\n stage, and they think they have\n an idea. Garazu-Horeizu's theory\n of the maelstrom has been made\n manifest. But to get to the\n bottom of things, you need\n a better-magicked doll. Procure\n a spectral goldenrod, spectral crimson,\n and luminicloth.",s={"Koru-Moru's Hypothesis"}},
      [460] = {n="Altennia Burns Bright",d="Mission Orders:\n The magicked doll reacted at\n Excenmille's presence when you went\n to see Prince Trion.\n The memories come flooding back, and\n Trion, fearing what may come next,\n has dispatched Altennia's regiment.\n Head to the Royal Knights' Quarters\n and give Rahal his orders.",s={"Altennia Burns Bright"}},
      [468] = {n="Maat on the Rampage",d="Mission Orders:\n Maat appears to be a tad more\n injury-prone of late. A woman who\n came to him for training may\n be involved. You have been\n asked to return a basket to her.\n Head to Lower Jeuno and speak\n with Muckvix to learn more\n about her.",s={"Maat on the Rampage"}},
      [484] = {n="Not Just a Pretty Face",d="Mission Orders:\n Maat appears to have been under the\n influence of the World Eater Egg.\n According to Muckvix, it appears to\n have been carried by monsters\n prowling around Delkfutt's Tower.\n The Gloom Phantom has headed to\n Qufim Island to learn more.\n Assist the troupe by heading\n to Delkfutt's Tower on Qufim\n Island.",s={"Not Just a Pretty Face"}},
      [494] = {n="Delkfutt the Great",d="Mission Orders:\n You heard about how Maat partook\n of the World Eater Egg from\n Shami and Shemo. According to\n Delkfutt, someone from San d'Oria\n cracked the egg twenty years ago.\n Perhaps you must travel to the past\n to learn more...",s={"Delkfutt the Great"}},
      [508] = {n="Oshasha Violation",d="Mission Orders:\n Oshasha of the Celennia Memorial\n Library has asked you to\n search for a tome known as\n the Liber Daemonium.\n The Velkk in Marjami Ravine appear\n to have taken possession of a book\n bearing resemblance to this tome.\n Head to Marjami Ravine.",s={"Oshasha Violation"}},
      [516] = {n="Phantasmic Heroes",d="Mission Orders:\n Translation of the Liber Daemonium\n has led you to learn of a\n demonic presence, Dvergr, in Leafallia.\n Oshasha and Valli are on the case,\n but Valli turned away for an instant\n and Oshasha was gone.\n Head to Leafallia and look for her.",s={"Phantasmic Heroes"}},
      [530] = {n="Skokkr Undrborn's Temptation",d="Mission Orders:\n Your invitation to the Silver\n Knife has arrived. The dvergr\n Skokkr Undrborn is supposedly there,\n potentially in the guise of a humanoid.\n Ask around for information.",s={"Skokkr Undrborn's Temptation"}},
      [542] = {n="The Prime Weapons",d="Mission Orders:\n Skokkr Undrborn has taken possession\n of the Liber Daemonium. The tome\n holds the secrets for manifesting\n the Prime Weapons once more.\n Stygian ash, occasionally carried\n by pixies, is needed to serve\n as a suitable vessel.\n The item is quite rare, so head to\n Celennia Memorial Library and do\n some research to aid you.",s={"The Prime Weapons"}},
      [552] = {n="To Movalpolos!",d="Mission Orders:\n According to Gumbah, a Galka\n has been sighted in a place\n known as Movalpolos.\n You have been asked to inform him\n that the gate has already been\n sealed. To Movalpolos!",s={"To Movalpolos!"}},
      [562] = {n="Magh Bihu on the Prowl",d="Mission Orders:\n You are destined for the Boyahda\n Tree in order to meet up with\n Jabbos once more.\n Magh Bihu is already en route.\n A friendly mandragora may be able to\n guide you to Magh Bihu's location\n if you give them a certain something.",s={"Magh Bihu on the Prowl"}},
      [574] = {n="101 Dazbogs",d="Mission Orders:\n When you went with Magh Bihu\n to see Dazbog, you were asked\n to bring a suitable tribute\n to the lord.\n Bring the lord six hunks of fat\n worm meat.",s={"101 Dazbogs"}},
      [580] = {n="Kipdrix the Faithful",d="Mission Orders:\n According to your allies,\n Magh Bihu and Dazbog have\n already arrived in Movalpolos.\n They certainly seem to\n want you to meet the Gloom\n Phantom. Head to Mine Shaft #2716.",s={"Kipdrix the Faithful"}},
      [592] = {n="Duke Alloces's Decision",d="Mission Orders:\n The demons, too, seem to have\n a traitor in their midst.\n Odin has permitted you to wield\n a Prime Weapon and has bid\n you defeat Chaos and Garazu-Horeizu.\n Prepare for the battle and\n head to the throne room in\n Castle Zvahl.",s={"Duke Alloces's Decision"}},
      [602] = {n="Odin's Eye",d="Mission Orders:\n You finally meet up with Raebrimm.\n His soul has been severed\n in twain, and he appears\n to be suffering from partial\n memory loss.\n Collect the four pieces of his soul\n and head deeper in.",s={"Odin's Eye"}},
      [612] = {n="Moglesse Oblige",d="Mission Orders:\n Your local Mog House moogle\n says that the time has come for\n moogle and adventurer to work\n as one.\n You must head to the stone\n circle in La Theine Plateau.\n Get a move on!",s={"Moglesse Oblige"}},
      [624] = {n="The Voracious Beast",d="Mission Orders:\n The time is nigh to vanquish\n the betrayer in Castle Zvahl\n and break the seal.\n Work with the beastmen and the\n Destiny Destroyers and claim victory.",s={"The Voracious Beast"}},
      [642] = {n="Your Decision",d="Mission Orders:\n The threat to Valhalla and Vana'diel\n has finally been vanquished, and\n beastmen and the enlightened races\n alike can walk hand in hand to\n secure a brighter future for all.\n Your choice has brought new light\n to the land.",s={"Your Decision"}},
      [999] = {n="?"},
    }},
  },
