    [500] = {n="Mog House Exit: San d'Oria",c=563,d="Speak to Kuu Mohzolhi in Northern San d'Oria (F-8) and complete the quest \"Growing Flowers\" to expand the number of destinations to which you may travel from your Mog House."},
    [501] = {n="Mog House Exit: Bastok",c=563,d="Speak to Valah Molkot in Port Bastok (J-12) and complete the quest \"A Lady's Heart\" to expand the number of destinations to which you may travel from your Mog House."},
    [502] = {n="Mog House Exit: Windurst",c=563,d="Speak to Ojha Rhawash in Windurst Walls (C-13), complete the quest \"Flower Child,\" and expand the number of destinations to which you may travel from your Mog House."},
    [503] = {n="Mog House Exit: Jeuno",c=563,d="Speak to Zona Shodhun in Port Jeuno (E-8), complete the quest \"Pretty Little Things,\" and expand the number of destinations to which you may travel from your Mog House."},
    [504] = {n="Mog House Exit: Aht Urhgan",c=563,d="Speak to Ahkk Jharcham in Aht Urhgan Whitegate (I-10), complete the quest \"Keeping Notes,\" and expand the number of destinations to which you may travel from your Mog House."},
    [505] = {n="Obtain a Support Job",c=563,d="Speak to Isacio in Selbina (G-10) and complete the quest \"Elder Memories\" or speak to Vera in Mhaura (G-10) and complete the quest \"The Old Lady\" to obtain a support job.\nRequirement: Be level 18 or higher."},
    [506] = {n="Obtain an Alter Ego: San d'Oria",c=563,d="Speak to Gondebaud in Southern San d'Oria (L-6), complete the quest \"Trust: San d'Oria,\" and obtain an alter ego of Excenmille.\nRequirement: Be level 5 or higher."},
    [507] = {n="Obtain an Alter Ego: Bastok",c=563,d="Speak to Clarion Star in Port Bastok (K-7), complete the quest \"Trust: Bastok,\" and obtain an alter ego of Naji.\nRequirement: Be level 5 or higher."},
    [508] = {n="Obtain an Alter Ego: Windurst",c=563,d="Speak to Wetata in Windurst Woods (G-10), complete the quest \"Trust: Windurst,\" and obtain an alter ego of Kupipi.\nRequirement: Be level 5 or higher."},
    [509] = {n="Obtain a Chocobo License",c=563,d="Speak to Brutus in Upper Jeuno (G-7), complete the quest \"Chocobo's Wounds,\" and obtain a chocobo license.\nRequirement: Be level 20 or higher."},
    [510] = {n="Obtain Job: Paladin",c=563,d="Speak to Balasiel in Southern San d'Oria (F-7), complete the quest line that begins with \"A Squire's Test,\" and obtain the paladin job.\nRequirements: Be level 30 or higher, reputation of \"I mighta hearda somebody that went by that name\" or the like."},
    [511] = {n="Obtain Job: Dark Knight",c=563,d="Speak to Gumbah in Bastok Mines (J-7), complete the quest \"Blade of Darkness,\" and obtain the dark knight job.\nRequirement: Be level 30 or higher."},
    [512] = {n="Obtain Job: Beastmaster",c=563,d="Examine the Door: Merchant's House in Upper Jeuno (G-11), complete the quest line that begins with \"Save My Son,\" and obtain the beastmaster job.\nRequirements: Be level 30 or higher, Completion of \"Chocobo's Wounds.\""},
    [513] = {n="Obtain Job: Bard",c=563,d="Speak to Mertaire in Lower Jeuno (I-8), complete the quest line that begins with \"The Old Monument,\" and obtain the bard job.\nRequirement: Be level 30 or higher."},
    [514] = {n="Obtain Job: Ranger",c=563,d="Speak to Perih Vashai in Windurst Woods (K-7), complete the quest \"The Fanged One,\" and obtain the ranger job.\nRequirement: Be level 30 or higher."},
    [515] = {n="Obtain Job: Samurai",c=563,d="Speak to Jaucribaix in Norg (K-8), complete the quest \"Forge Your Destiny,\" and obtain the samurai job.\nRequirements: Be level 30 or higher, installation of Rise of the Zilart."},
    [516] = {n="Obtain Job: Ninja",c=563,d="Speak to Kaede in Port Bastok (J-5), complete the quest \"Ayame and Kaede,\" and obtain the ninja job.\nRequirements: Be level 30 or higher, installation of Rise of the Zilart."},
    [517] = {n="Obtain Job: Dragoon",c=563,d="Speak to either Arminibit or Ceraulian in Port San d'Oria (I-10), complete the quest \"The Holy Crest,\" and obtain the dragoon job.\nRequirements: Be level 30 or higher, installation of Rise of the Zilart."},
    [518] = {n="Obtain Job: Summoner",c=563,d="Examine the Door: House of the Hero in Windurst Walls (G-3) while in possession of Carbuncle's ruby, complete the quest \"I Can Hear a Rainbow,\" and obtain the summoner job.\nRequirement: Be level 30 or higher."},
    [519] = {n="Obtain Job: Blue Mage",c=563,d="Speak to Waoud in Aht Urhgan Whitegate (J-10), complete the quest \"An Empty Vessel,\" and obtain the blue mage job.\nRequirements: Be level 30 or higher, installation of Treasures of Aht Urhgan."},
    [520] = {n="Obtain Job: Corsair",c=563,d="Speak to Ratihb in Aht Urhgan Whitegate (J-12), complete the quest \"Luck of the Draw,\" and obtain the corsair job.\nRequirements: Be level 30 or higher, installation of Treasures of Aht Urhgan."},
    [521] = {n="Obtain Job: Puppetmaster",c=563,d="Speak to Shamarhaan in Bastok Markets (F-9), complete the quest \"No Strings Attached,\" and obtain the puppetmaster job.\nRequirements: Be level 30 or higher, installation of Treasures of Aht Urhgan."},
    [522] = {n="Obtain Job: Dancer",c=563,d="Speak to Laila in Upper Jeuno (G-7), complete the quest \"Lakeside Minuet,\" and obtain the dancer job.\nRequirements: Be level 30 or higher, installation of Wings of the Goddess."},
    [523] = {n="Obtain Job: Scholar",c=563,d="Speak to Erlene in the Eldieme Necropolis [S] (J-8), complete the quest \"A Little Knowledge,\" and obtain the scholar job.\nRequirements: Be level 30 or higher, installation of Wings of the Goddess."},
    [524] = {n="Obtain Job: Geomancer",c=563,d="Speak to Sylvie in Western Adoulin (I-5), complete the quest \"Dances with Luopans,\" and obtain the geomancer job.\nRequirements: Be level 30 or higher, installation of Seekers of Adoulin."},
