    [1420] = {n="Rhapsodies of Vana'diel Chapter 2-5",c=581,d="Complete up to \"Of Light and Darkness\" by examining any of the Cavernous Maws in the following locations: Batallia Downs (H-5), Rolanberry Fields (H-6), Sauromugue Champaign (K-9).\nRequirement: Completed \"From the Ruins.\""},
