    [1424] = {n="Rhapsodies of Vana'diel Chapter 2-9",c=581,d="Complete up to \"Uncertain Futures\" by visiting any of the Shattered Telepoints in the following locations: La Theine Plateau (K-9), Konschtat Highlands (I-7), Tahrongi Canyon (j-6).\nRequirement: Completed \"Banished.\""},
