    [1429] = {n="Seekers of Adoulin Chapter 4",c=583,d="Speak to Levil in Western Adoulin (E-8) and complete up to \"Royal Blessings.\"\nRequirements: Allow one Vana'diel day to pass after triggering \"Glimmer of Portent,\" must have reached a certain level of fame in Adoulin."},
